import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAX: [CaseTemplate] = [marketScale, driveThruDash, rareBookLift, churchBellPaint, plowMailbox, yardSignTheft, halloweenEggs, pumpkinPatchTheft, cemeteryFlowers, firewoodLot, baitShopTill, cartInPond, bowlingAlleyScuffle, barTabSkip, tireSwapScam, mowCrewNoShow, formulaShoplift, perfumeShoplift, pizzaOrderScam, utilityShutoffCall, lockedPhoneSale, towTruckOvercharge, stereoNoise, leafBlowerDawn, cartParkingFight, roadRageGesture, shedSprayPaint, pepperSprayParty, schoolLotMarijuana, borrowedBike, landfillSalvage, cellTowerClimb, schoolAfterHours, tailgatingTruck, expiredLicenseStop, taserCarry, voicemailThreatBoss, stolenTrailerHitch, fakeParkingTicket, schoolPermitForge, carBreakinGym, chaseOnBike, cardSwapGas, passwordBorrow, ghostKitchenFee, stolenCharger, lostPackageLocker, rentalTrailerNotReturned, campgroundHookups, hayBaleTheft, catchBasinCover, streetSignTheft, houseSitter, nannyPetty, coachFees, campusBike, phoneWaitress, glovesShoplift, bakerySkip, liquorTheft, cigarCaseSmash, atmHammer, wrongWayRoad, hotelLobbySleep, barBanned, burnoutLot, noiseGenerator, paintballStreet, snowballCar, sprinklerFight, bikeLaneShove, fakeCashMarket, badCheckTires, stolenCheckbook, transitFare, radioStationFake, bingoCheat, craigslistHorse, rentalDepositKeep, gardenGrow, catSittingFraud, christmasLights, fakeCharityDoor, bridgeRailTag, trainCarTag, carHoodDent, tireDeflate, windowEgg, doorKick, shutterTear, fenceFlatten, drunkPorchBell, callbackPrank, fakeRobberyReport, overdoseHoax, fakeStolenCar, givenFalseDOB, hidesInBushes, needlesCar, sleepingDriver]

    static let marketScale = SmallCases.make(
        key: "story.marketScale",
        category: .whiteCollar,
        headlines: ["Vendor's Rigged Scale Shorts Customers at Farmers Market"],
        law: "falsePretenses",
        spec: "Obtained $85 from {V}, a market shopper, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} bought what a scale said was five pounds of tomatoes from {D} on {DATE}. A market inspector later found the scale reading 12 percent heavy. The market had opened for the season a week earlier, and {D}'s stall sells tomatoes and peppers from a folding table. {V} weighed the tomatoes at home, found them light, and an inspector tested the scale the same day.",
        state: [E(.document, 3, "Inspector Report", "The scale reads 12 percent heavy."), E(.statement, 2, "{V}'s Kitchen Scale", "The tomatoes weighed about four and a half pounds at home.")],
        defense: [E(.statement, 1, "Calibrated", "{DL} says the scale was calibrated in the spring.")],
        role: "Market inspector",
        exam: [.direct("Tell the jury about your job at the farmers market.", "\"I'm the market inspector. I test scales, check produce labels, and respond to complaints. I inspect about forty vendors across the season.\""), .direct("What did you find when you tested {D}'s scale?", "\"The scale was reading twelve percent heavy. That means a customer paying for five pounds of tomatoes was getting about four and a half.\""), .direct("How did this come to your attention?", "\"{V} weighed the tomatoes at home on a kitchen scale and found them light, about four and a half pounds, and then called us.\""), .direct("When did you test the scale?", "\"The same day as the complaint. The market had opened for the season a week earlier, and {D}'s stall sells tomatoes and peppers from a folding table.\""), .direct("What happened when you tested {D}'s scale?", "\"I placed certified test weights on the platform. A five-pound weight read about five pounds and eleven ounces, which is twelve percent heavy.\""), .direct("What does that mean for a customer?", "\"A customer who pays for five pounds would receive about four and a half pounds. The error always favored the seller.\""), .cross("A scale can drift over time, can't it?", "\"It can, but not that far. A twelve percent error is well outside normal drift for a scale that is calibrated.\""), .cross("Did you find any sign of tampering on the scale?", "\"I recorded the reading and the result. I cannot tell you from the reading alone whether anyone altered it.\""), .cross("Had any other customer complained about {D}'s scale?", "\"Not to me, no. This was the first complaint I had on that stall.\""), .cross("Did you inspect {D}'s scale earlier in the season?", "\"I check each scale once at the start of the season. I'd tested it three weeks earlier and it was within tolerance.\""), .cross("Did {D} cooperate with your inspection of the scale?", "\"Yes. {D} let me test it and said the scale was calibrated in the spring. {D} did not try to stop me or remove anything.\""), .cross("Could a bump in a van knock a scale out of calibration?", "\"It can. A scale that is jostled can read off, which is why I check for a hidden magnet and any sign of tampering.\"")],
        theory: ("{D} shorted customers with a rigged scale.", "A drifting scale."),
        allocution: "\"I'm sorry.\"",
        truths: ("A magnet was taped under the platform.", "The scale had been bumped in a van."),
        defendant: [.direct("Did you rig the scale at your stall?", "\"No. I never touched the scale to make it read heavy. I use it all day, and I want customers to come back.\""), .direct("When was the scale last calibrated?", "\"In the spring, before the season opened. I had it checked then, and it was fine.\""), .direct("Had anyone complained about your scale before?", "\"Not to me. I have a lot of regulars, and nobody ever told me the weights were wrong.\""), .direct("Tell us how you run your stall.", "\"I grow tomatoes and peppers on a small farm. I set up a folding table at the market every Saturday and weigh what I sell on a digital scale.\""), .direct("When did you last calibrate the scale?", "\"In the spring, with a set of test weights I bought. It was fine then, and I haven't noticed a problem since.\""), .direct("How do you carry the scale to market?", "\"In the back of my van with the rest of the gear. It gets bumped around, and I think that's what happened.\""), .cross("The inspector found it twelve percent heavy. How does that happen?", "\"I do not know. It may have been bumped in the van when I hauled it to the market.\""), .cross("You weigh produce all day. Didn't you notice the scale was off?", "\"No. Without a reference weight in my hand, I could not tell. I trusted it.\""), .cross("Customers lose money when a scale reads heavy, don't they?", "\"Yes, and I feel bad about that. If I had known, I would have fixed it right away.\""), .cross("A twelve percent error is huge. How could a bump do that?", "\"I'm not an expert, but I know scales can be knocked out of adjustment. I wish I'd checked it more often.\""), .cross("Customers have told you before that the weights seemed off, haven't they?", "\"One or two said something. I told them I'd look into it, and I never did.\"")],
        openings: ("{V} bought what a market scale said was five pounds of tomatoes from {D}, then weighed them at home and found about four and a half. An inspector tested the scale the same day and found it twelve percent heavy.", "The defense will present evidence that {D}'s scale was calibrated in the spring and may have been bumped in a van. A bad reading is not proof that {D} meant to cheat anyone."),
        closings: ("Twelve percent heavy is not drift. {V} paid for five pounds and got four and a half, and the scale that did it was at {D}'s stall.", "A scale that was calibrated in spring and carried to market in a van can be knocked out of true. The State has shown a bad reading, but not that {D} did anything on purpose."),
        timeline: [(-7, "The market opens."), (0, "{V} weighs the tomatoes at home."), (0, "An inspector tests the scale.")],
        identified: "Inspector Report",
        mood: .indifferent)

    static let driveThruDash = SmallCases.make(
        key: "story.driveThruDash",
        category: .property,
        headlines: ["Customer Drives Off From Drive-Thru Window With $64 Order"],
        law: "misdLarceny",
        spec: "Stole food valued at $64 belonging to {V}, a restaurant, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A driver took a $64 order at a drive-thru window on {DATE} and drove off without paying. The window camera captured the plate, which belongs to {D}. The restaurant's drive-thru has a single window, and the order went out at 6:10 p.m. in the middle of the dinner rush. The car was gone two minutes later, and the manager reported the plate to deputies the next day.",
        state: [E(.video, 3, "Window Camera", "The car takes the bag and leaves."), E(.document, 2, "Order Receipt", "A $64 order with no payment recorded.")],
        defense: [E(.statement, 1, "Card Declined", "{DL} says the card reader froze.")],
        role: "Restaurant manager",
        exam: [.direct("Tell the jury how your drive-thru works and how busy it was.", "\"We have one window and one lane. At six o'clock on a weekday the line is usually six or seven cars deep.\""), .direct("What happened at your drive-thru window on {DATE}?", "\"At about 6:10 in the evening, in the middle of the dinner rush, a driver took a $64 order through the window and drove off without paying.\""), .direct("What does the window camera show?", "\"The car takes the bag at the window and leaves. It's gone about two minutes later. The camera got the plate, which belongs to {D}.\""), .direct("What did you do about it?", "\"I looked at the register and found the order with no payment recorded. I reported the plate to the deputies the next day.\""), .direct("What did the window camera show about the order?", "\"A car pulls up, the employee hands out a bag, the driver pushes a card toward the reader, and then the car pulls away before the transaction posts.\""), .direct("What did you do after you realized the order hadn't been paid?", "\"I checked the register and saw the $64 order with no payment recorded. I got the plate from the camera and reported it to deputies the next day.\""), .cross("{DL} says the card reader froze, doesn't {D.he}?", "\"We get glitches sometimes. I can't say whether this order hit one, and I wasn't at the window itself.\""), .cross("Did anyone try to stop the car?", "\"No. We have one window and a line behind it, and it all happened fast. The car pulled away before anyone realized.\""), .cross("Did {DL} come back to pay?", "\"Not that I'm aware of. I didn't hear from {D} until the deputies reached out. I'd have taken payment gladly.\""), .cross("Does the card reader freeze often?", "\"Occasionally during busy times. We get a few glitches a month, and the reader log should show if it jammed.\""), .cross("Did the employee at the window tell the driver the card didn't go through?", "\"I asked the employee, who said the driver left before the receipt printed. They didn't see whether the reader had errored.\"")],
        theory: ("{D} drove off without paying.", "A frozen reader."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had skipped payment at the same window twice.", "The reader log shows a jam."),
        defendant: [.direct("What happened at the drive-thru?", "\"I ordered food, and at the window the card reader froze. The employee handed me the bag and I took it, thinking I'd sort it out.\""), .direct("Why did you drive off without paying?", "\"The line behind me was long and the employee seemed busy. I thought I could come back later and pay. I should have stopped.\""), .direct("Did you intend to steal the food?", "\"No. I meant to pay. I had a card ready and the reader wouldn't take it. I was embarrassed and left in a hurry.\""), .direct("Describe what you remember about that evening.", "\"I was picking up dinner for my family. I ordered a few meals and pulled up to the window with a card in my hand.\""), .direct("What happened at the reader?", "\"I held the card against the reader and nothing happened. The employee had already handed me the bag, and the car behind me was honking.\""), .direct("Why did you leave?", "\"I thought the payment had gone through because the screen said 'processing.' I drove off, and I didn't check my receipt.\""), .cross("You drove away with a $64 bag of food, didn't you?", "\"Yes, I did. I understand how it looks. I meant to come back, but I didn't, and I wish I had.\""), .cross("You never called the restaurant, did you?", "\"No. I wish I had. I thought about it and put it off. I'm sorry for not making it right right away.\""), .cross("The window camera shows your plate, doesn't it?", "\"It does. I wasn't hiding. If I'd wanted to steal food, I wouldn't have driven my own car to a window with a camera.\""), .cross("You never contacted the restaurant. Why not?", "\"I didn't realize the order hadn't been paid until deputies called. I'd have paid right away if I had known.\""), .cross("Your plate was on the camera. You'd skipped payment at that window before, hadn't you?", "\"I don't recall that. If I did, it was an error like this one, and I didn't intend to.\"")],
        openings: ("At 6:10 in the dinner rush, a driver took a $64 order through the window and drove off without paying. The window camera caught the plate, which belongs to {D}. The State will show the video and the receipt.", "The defense will present a card reader that froze, a long line behind {D}, and a driver in plain view of a camera who never meant to steal a meal."),
        closings: ("A $64 order, a bag taken at the window, and a car gone in two minutes. The plate is {D}'s, and no payment was ever made.", "A frozen reader and a hurried exit. {D} drove away in plain view of a camera. The State has not proved {D} meant to avoid paying."),
        timeline: [(0, "6:10 p.m.: the order."), (0, "6:12 p.m.: the car leaves."), (1, "The manager reports the plate.")],
        identified: "Window Camera",
        mood: .indifferent)

    static let rareBookLift = SmallCases.make(
        key: "story.rareBookLift",
        category: .property,
        headlines: ["Patron Walks Out of County Library With Rare Local History Books"],
        law: "misdLarceny",
        spec: "Stole books valued at $540 belonging to {V}, a library, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Three rare local history books were missing from a library reading room after {D} left with a tote bag on {DATE}. The gate alarm was switched off that afternoon. The reading room is a quiet space at the back of the library, and the local history books are kept on open shelves. They went into the bag at about 12:40 p.m., and the titles turned up online two days later.",
        state: [E(.video, 3, "Reading Room Camera", "{D} puts three books in a tote bag."), E(.document, 2, "Collection List", "The three titles are marked reference only.")],
        defense: [E(.statement, 1, "Borrowed", "{DL} says {D.he} meant to check them out.")],
        role: "Librarian",
        exam: [.direct("Tell the jury about the reading room and how it's supervised.", "\"It's a quiet room at the back of the library with local history books on open shelves. A volunteer is usually at a small desk, but at lunchtime the desk is unattended.\""), .direct("What did you see in the reading room that day?", "\"On the camera, {D} puts three books into a tote bag at about 12:40 p.m. and walks out. The local history shelves are open in a quiet room at the back.\""), .direct("Can those books be checked out?", "\"No. All three titles are marked reference only, so they can be read in the room but never taken from the building.\""), .direct("What happened after the books left?", "\"The gate alarm had been switched off that afternoon, and the same three titles turned up in an online listing two days later.\""), .direct("What did you see on the reading room camera?", "\"At about 12:40, {D} takes three books from the shelf, looks around, and puts them in a tote bag. {D} walks out through the main gate at 12:45.\""), .direct("What happened with the gate alarm?", "\"It was switched off that afternoon for maintenance. We didn't know until later that it had been off, and no one saw {D} pass through.\""), .cross("Did {D} try to check the books out at the desk?", "\"There is no record of that. I do not know whether {D} went to the desk or not.\""), .cross("Was the checkout desk staffed at that hour?", "\"It was closed for lunch around that time. That is true, and I am not going to hide it.\""), .cross("Are the shelves in that room locked?", "\"No, they are open shelves. Anyone in the room can pick a book up, and that is how we have always run it.\""), .cross("Did {D} ask a staff member about the books or about borrowing them?", "\"Not that I know of. The checkout desk was closed for lunch, and no one was there to ask.\""), .cross("Is it common for researchers to take reference books to a copier or another room?", "\"Some do, with permission. The books are marked reference only and shouldn't leave the room.\"")],
        theory: ("{D} took rare books.", "A forgotten checkout."),
        allocution: "\"I'm sorry.\"",
        truths: ("A pawn listing offered the same titles.", "The checkout desk was closed for lunch."),
        defendant: [.direct("Did you take the books from the library?", "\"I meant to borrow them. I was doing research, and I did not realize they could not leave the building.\""), .direct("Why did you leave without checking them out?", "\"The checkout desk was closed for lunch. I figured I would bring them back the next day and tell the staff.\""), .direct("Did you tell anyone you were leaving with them?", "\"No. I did not tell anyone, and I know that was a mistake. There was nobody at the desk to tell.\""), .direct("Tell us what you were doing at the library.", "\"Researching the history of my neighborhood. I'd been there on and off for a few weeks and I needed these three books for a project.\""), .direct("Where are the books now?", "\"They were recovered from an online listing, which I did not post. I never sold or offered them.\""), .direct("What was your plan for the three books after you left?", "\"I meant to check them out once the desk reopened, and I carried them in a tote bag to read in the park while the desk was closed for lunch.\""), .cross("The titles are marked reference only. Didn't you see that?", "\"I did not look at the labels closely. I saw the books I wanted and put them in my bag.\""), .cross("Why did the same titles show up in an online listing?", "\"I do not know. I did not list them myself, and I cannot explain how they got there.\""), .cross("You walked out of a quiet room with a tote bag full of rare books. How is that borrowing?", "\"It sounds worse than it was. I fully intended to return them, and I should have asked first.\""), .cross("The books are marked reference only. Didn't you see that?", "\"I saw the labels. I thought a researcher could borrow them if the librarian approved, and I figured I'd explain later.\""), .cross("Why did the same titles appear online two days later?", "\"I don't know. I didn't list them, and I can't say who did.\"")],
        openings: ("Three rare local history books marked reference only were put into a tote bag by {D} at 12:40 one afternoon and carried out of a library. Two days later the same titles were offered online.", "Listen for the defense evidence, which will show that the checkout desk was closed for lunch and that {D} meant to borrow the books and bring them back. {D} never intended to keep them."),
        closings: ("The camera shows {D} putting three reference-only books into a bag and walking out with the alarm off. Two days later they were for sale online.", "A closed desk, a researcher in a hurry, and an intent to return. The State must prove {D} meant to keep the books, and borrowing badly is not stealing."),
        timeline: [(0, "12:40 p.m.: the books go into the bag."), (0, "1 p.m.: the shelf is found bare."), (2, "The titles appear online.")],
        identified: "Reading Room Camera",
        mood: .indifferent)

    static let churchBellPaint = SmallCases.make(
        key: "story.churchBellPaint",
        category: .property,
        headlines: ["Church Steps and Bell Tower Painted Overnight"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a church, causing damage of $1,300, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "The steps and tower of a small church were painted with slogans overnight on {DATE}, costing $1,300 to remove. A neighbor's camera showed {D} carrying spray cans. The small church sits on a corner lot with a stone stairway up to the bell tower door, and the paint covered the steps and the door. The camera shows {D} walking toward the church with the cans at about 1 a.m., and the deacon found the damage at 7 a.m.",
        state: [E(.video, 3, "Neighbor Camera", "{D} walks toward the church with cans."), E(.document, 2, "Cleanup Estimate", "$1,300 to remove paint from the steps and the tower door.")],
        defense: [E(.statement, 1, "Walk", "{DL} says {D.he} was walking a dog.")],
        role: "Church deacon",
        exam: [.direct("Tell us about your role at the church and the building.", "\"I'm a deacon, and I open the church for services and look after the building. It's a small stone church on a corner lot, with a stairway up to a bell tower door.\""), .direct("What did you find at the church on {DATE}?", "\"At about seven in the morning, I found slogans painted over the stone steps, the tower, and the tower door. It was fresh and ugly.\""), .direct("What did it cost to put right?", "\"$1,300 to remove the paint from the steps and the door. A cleaning crew has to work on stone carefully, and it took days.\""), .direct("What does the neighbor's camera show?", "\"{D} walking toward the church with spray cans at about one in the morning. The camera sits across the corner from the church.\""), .direct("How much of the building was painted?", "\"The steps, the tower door, and part of the stone wall facing the street. The slogans were in black and red and covered about thirty feet.\""), .direct("How did {D} come to your attention?", "\"A neighbor across the street has a camera that covers our corner. The video shows {D} walking toward the church carrying cans at about one in the morning.\""), .cross("Did the camera show {DL} actually painting anything?", "\"No. It shows {D} walking toward the church with cans. I have no footage of the painting itself.\""), .cross("{DL} says {D.he} was walking a dog, doesn't {D.he}?", "\"I can't say what the camera caught beyond what I saw. I know only what I found at seven.\""), .cross("Do you know {DL}?", "\"I know the person on the video by what the deputies said. I didn't have any trouble with {D} before. There was no known dispute.\""), .cross("Does the camera show {D} at the church steps?", "\"No. It shows {D} on the sidewalk heading in that direction, and then {D} goes out of frame.\""), .cross("Did you find any paint on {D}'s hands or clothes?", "\"No. A deputy spoke with {D} later in the day, and I'm not aware of any paint being found on {D}.\"")],
        theory: ("{D} painted the church.", "A late-night walk."),
        allocution: "\"I'm sorry.\"",
        truths: ("Paint matched cans in {DL}'s garage.", "No dog was on the video."),
        defendant: [.direct("Why were you near the church at 1 a.m.?", "\"I was out walking. It was a quiet night, and the church is on my route. I walk in the evening to clear my head.\""), .direct("Did you carry spray cans?", "\"I may have had something in my hands. I don't remember what. I wasn't carrying anything to paint a church.\""), .direct("Did you paint the church?", "\"No. I would never do that. It's a place of worship, and I respect it. I never touched the steps or the door.\""), .direct("Please describe your late walks.", "\"I have trouble sleeping, so I walk around the neighborhood at night. I usually go past the church because it's quiet and well lit.\""), .direct("What were you carrying that night?", "\"A bag with a couple of items I was returning to a friend. I'd picked them up earlier and I was dropping them off on my way home.\""), .direct("How did you feel when you learned about the paint?", "\"Upset. The church is a place I respect, and I told the deputy I'd had nothing to do with it.\""), .cross("The camera shows you with cans, doesn't it?", "\"It shows something I carried. I can't say it was spray cans for sure. I was walking, and that's all.\""), .cross("You were walking toward the church at 1 a.m., weren't you?", "\"Yes, that's my route. I walked past it. I didn't stop to do anything there.\""), .cross("Nobody saw you with a dog, did they?", "\"I walk alone sometimes. I said I was walking, and I stand by that.\""), .cross("Spray cans were found in your garage that match the slogans. How do you explain that?", "\"I have old cans from home projects. They're not special, and I never used them on the church.\""), .cross("The camera shows you walking toward the church with cans at 1 a.m. Why carry cans on a walk?", "\"I wasn't carrying cans. I was carrying a bag, and the video isn't clear.\"")],
        openings: ("The steps, tower, and door of a small church were covered in slogans overnight, a $1,300 cleanup. A neighbor's camera shows {D} walking toward the church at 1 a.m. with spray cans. The State will show the video and the damage.", "The defense evidence includes a night walker on a regular route, a camera that never shows anyone painting, and no connection between {D} and a single slogan."),
        closings: ("Spray cans on camera at 1 a.m., heading toward the church, and paint all over its steps and door by seven. The timing and the cans point to {D}.", "A walk past a church is not vandalism. The camera never shows paint touching a wall. The State has not proved {D} painted anything."),
        timeline: [(0, "1 a.m.: {DL} passes the church."), (0, "7 a.m.: the deacon finds the paint."), (1, "The camera is reviewed.")],
        identified: "Neighbor Camera",
        mood: .indifferent)

    static let plowMailbox = SmallCases.make(
        key: "story.plowMailbox",
        category: .property,
        headlines: ["Plow Driver Knocks Down Three Mailboxes and Keeps Going"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, mailboxes, causing damage of $420, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Three mailboxes on a rural road were knocked down by a plow blade on {DATE}. A neighbor wrote down the truck's number, which is {D}'s contract truck. The county road is plowed early by contract drivers, and the mailboxes stand at the edge of the plowed lane. The plow passed at about 6 a.m., and {V} found the boxes down at 7 a.m.",
        state: [E(.document, 3, "Truck Log", "{D} drove that route at 6 a.m."), E(.statement, 2, "Neighbor", "Wrote down the number on {D}'s contract truck.")],
        defense: [E(.statement, 1, "Whiteout", "{DL} says snow hid the boxes.")],
        role: "Resident",
        exam: [.direct("Please tell us about your mailbox and where it stands.", "\"I've lived on this road for twenty years. My mailbox stands on a wooden post at the edge of the lane, about two feet from where the plow blade passes.\""), .direct("What did you find that morning?", "\"I found three mailboxes on our rural road knocked flat at about 7 a.m., with the posts bent over at the edge of the plowed lane.\""), .direct("Who gave deputies the truck's number?", "\"A neighbor who was up early wrote down the number of the plow truck. It turned out to be {D}'s contract truck.\""), .direct("What did you see on the posts?", "\"Yellow paint from the blade on the posts. The plow had gone by around 6 a.m., and the paint matched.\""), .direct("What did you find when you went out that morning?", "\"Three mailboxes lying in the ditch, including mine. The posts were snapped at the base and yellow paint was scraped across the wood.\""), .direct("How did you learn which truck did it?", "\"A neighbor who was up early saw the plow go by and wrote down the number on the door. The number matched a contract truck assigned to {D}.\""), .cross("Did the truck stop after it hit the boxes?", "\"No. It kept going down the road. But I do not know whether the driver knew.\""), .cross("Were the mailboxes hard to see in the snow?", "\"They stand at the edge of the lane, and with snow banked up, they can be hard to see. I understand that.\""), .cross("Do contract drivers plow that route every time it snows?", "\"Yes. They come early, before dawn, and I have never had a problem before this.\""), .cross("Did you hear the plow hit anything?", "\"No. I was asleep until the plow passed, and I didn't hear any impact.\""), .cross("Were the boxes easy to see in the snow at that hour?", "\"They stand out from the snow, but it was dark and the snow was falling. I wouldn't call them hard to see.\"")],
        theory: ("{D} destroyed boxes and left.", "A whiteout."),
        allocution: "\"I'm sorry.\"",
        truths: ("Yellow paint from the blade was on the posts.", "The posts stood out from the snow."),
        defendant: [.direct("Did you hit the mailboxes with your plow?", "\"I did not feel anything. I plow a long route in the dark, and I never felt an impact.\""), .direct("Were you driving that road at 6 a.m.?", "\"Yes. That is my route, and the log shows I was there around that time.\""), .direct("How was visibility that morning?", "\"Poor. It was dark, the snow was falling, and the posts blended into the banks.\""), .direct("Please describe your plow route.", "\"I plow county roads under contract, starting around four in the morning. My route covers about thirty miles, and I'd covered it that night.\""), .direct("What was the weather like at 6 a.m.?", "\"Heavy snow, wind, and low visibility. I was driving about fifteen miles an hour and the blade was down.\""), .direct("Did you feel anything hit the blade?", "\"No. I've hit mailboxes before, and I'd have felt it. I'm not sure how three boxes were knocked down without my noticing.\""), .cross("There was yellow paint from your blade on the posts, wasn't there?", "\"I understand that. I still did not feel it. A plow blade throws a lot of snow, and mailboxes are light.\""), .cross("You never stopped or reported hitting anything, did you?", "\"I did not know I hit anything. If I had known, I would have stopped.\""), .cross("You drive that route often. Don't you know where the boxes stand?", "\"I know they are there, but with snow piled up I could not tell how close the blade was.\""), .cross("Yellow paint from your blade was on the posts. How do you explain that?", "\"It must have been me. I can't say I felt it, but I understand the evidence.\""), .cross("You didn't stop or report it. Isn't it your duty to report damage?", "\"Yes. I would have, if I'd known. I didn't know until a deputy called later in the day.\"")],
        openings: ("Three mailboxes on a rural road were knocked down at about 6 a.m. by a plow blade. A neighbor wrote down the truck's number, and it belongs to {D}'s contract truck, with yellow blade paint left on the posts.", "The defense will point you to a dark morning, heavy snow, and a driver who felt nothing. Hitting a mailbox in a snowstorm without knowing it is not a willful act."),
        closings: ("The truck log puts {D} on that route at 6 a.m., a neighbor wrote down the number, and yellow paint was on the posts. The boxes did not knock themselves down.", "In the dark, with snow banked at the edge of the lane, {D} felt nothing. The State must prove a willful act, and an accident in a storm is not that."),
        timeline: [(0, "6 a.m.: the plow passes."), (0, "7 a.m.: {V} finds the boxes down."), (1, "The neighbor gives deputies the number.")],
        identified: "Truck Log",
        mood: .indifferent)

    static let yardSignTheft = SmallCases.make(
        key: "story.yardSignTheft",
        category: .property,
        headlines: ["Candidate Yard Signs Pulled Up Overnight and Loaded Into a Truck"],
        law: "misdLarceny",
        spec: "Stole yard signs valued at $210 belonging to {V}, a campaign, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Forty campaign yard signs worth $210 were pulled up overnight on {DATE}. A doorbell camera showed {D} loading signs into a truck. The signs lined a main road near the polling place. {D}'s truck stopped there at about 11 p.m., and the volunteer found empty lawns at 6 a.m.",
        state: [E(.video, 3, "Doorbell Camera", "{D} loads signs into a truck."), E(.document, 2, "Sign Order", "A campaign order for forty signs.")],
        defense: [E(.statement, 1, "Trash", "{DL} says the signs were abandoned.")],
        role: "Campaign volunteer",
        exam: [.direct("What can you tell us about your role in the campaign and the signs?", "\"I'm a volunteer for the campaign. We ordered forty signs and staked them along the main road near the polling place the week before the election.\""), .direct("What did you find on the main road that morning?", "\"Empty lawns. Forty of our campaign yard signs, worth about $210, had been pulled up overnight along the road near the polling place.\""), .direct("How many signs had you ordered?", "\"Forty. The order form says forty, and we staked every one of them ourselves the week before.\""), .direct("What does the doorbell camera show?", "\"{D} loading signs into a truck at about 11 p.m. The camera is on a house along that road.\""), .direct("When did you discover they were gone?", "\"At six in the morning, I drove the road to check them and found empty lawns. The stakes were pulled up and gone too.\""), .direct("How did you find who took them?", "\"A resident's doorbell camera caught a truck stopping at about eleven at night. A person gets out and loads signs into the bed.\""), .cross("Were the signs abandoned or left loose?", "\"No. We had staked every one. They were not abandoned, and each had a campaign stake.\""), .cross("Could {D} have thought they were trash after the election?", "\"The election had not happened. The signs were up for the vote and the polling place was right there.\""), .cross("Did you see {D} take them?", "\"No. I only know what the camera and deputies told me. I was not there at 11.\""), .cross("Did the video show the person's face?", "\"It shows enough to identify {D}, and a deputy confirmed that against the plate. I can't say more than that.\""), .cross("Were any signs damaged or left behind?", "\"A few stakes were left in the grass. Otherwise every sign on that stretch was gone.\"")],
        theory: ("{D} took campaign signs.", "Signs left behind."),
        allocution: "\"I'm sorry.\"",
        truths: ("Signs were found in {DL}'s shed.", "The signs had campaign stakes."),
        defendant: [.direct("Did you take the campaign signs?", "\"I took them, but they were loose. I thought they were left over and not wanted anymore.\""), .direct("Where did the signs end up?", "\"At the dump. I took what I thought was trash there.\""), .direct("Tell the jury where you were that night.", "\"On the main road, driving home from a late shift. I saw a lot of signs lying around and thought it was trash after a long campaign.\""), .direct("Why did you load them into your truck?", "\"I was making a dump run the next day and thought I'd save a trip. I picked up what looked loose and abandoned.\""), .direct("What did you do with the signs?", "\"Most went to the dump. A few stayed in my shed, and I didn't think about them until the deputy asked.\""), .direct("Why did you believe the yard signs were abandoned?", "\"They were staked along a road with no house nearby, and a few had fallen over. I thought a campaign had left them, and I never read the tag on the stakes.\""), .cross("Signs were found in your shed, weren't they?", "\"A few, yes. I kept them, and I know it looks like I was collecting them.\""), .cross("Staked signs along a road next to a polling place are not trash, are they?", "\"I did not think about that. I just saw signs on the ground and in the way.\""), .cross("You loaded forty at 11 p.m. Why do a dump run in the middle of the night?", "\"It was when I had time. I was not trying to hide, and I did not think anyone cared.\""), .cross("The signs were staked in the ground next to a polling place. Weren't they obviously not trash?", "\"I should have looked closer. It was dark, and I didn't realize they were still part of the campaign.\""), .cross("Signs were found in your shed. Why keep them if you thought they were trash?", "\"I kept them because they were in good shape. I thought they might be useful for something else.\"")],
        openings: ("Forty campaign yard signs worth $210 were pulled up overnight along a road near the polling place. A doorbell camera shows {D} loading them into a truck at 11 p.m.", "Jurors will hear that {D} believed the signs were loose trash and was making a dump run. {D} never meant to take anything of value."),
        closings: ("Forty staked signs, a camera showing {D} loading them, and signs found in {D}'s shed. These were not trash, and they were pulled up just before the vote.", "{D} saw signs lying around and thought they were litter. A mistaken belief about what is trash is not an intent to steal, and the State must prove that intent."),
        timeline: [(0, "11 p.m.: {DL}'s truck stops."), (0, "6 a.m.: the volunteer finds empty lawns."), (1, "A doorbell frame is shared.")],
        identified: "Doorbell Camera",
        mood: .indifferent)

    static let halloweenEggs = SmallCases.make(
        key: "story.halloweenEggs",
        category: .property,
        headlines: ["Teens Egg Parked Cars at Night, Damaging Paint"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a car, causing damage of $650, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Eggs left etched paint on {V}'s car overnight on {DATE}, costing $650 to correct. A neighbor's camera showed {D} throwing eggs from a car. The eggs hit several parked cars along one street, and {V}'s car was one of them. The car cruised the street at about 9 p.m., the eggs hit at 9:10 p.m., and {V} found the paint damaged the next day.",
        state: [E(.video, 3, "Neighbor Camera", "{D} throws eggs at parked cars."), E(.statement, 2, "Neighbor", "Saw a car cruise the street before the eggs hit.")],
        defense: [E(.statement, 1, "Candy Run", "{DL} says it was a harmless prank.")],
        role: "Car owner",
        exam: [.direct("Tell the jury about your car and where it was parked.", "\"A dark gray sedan, parked at the curb in front of my house. I'd washed it that weekend and the paint was in good shape.\""), .direct("What happened to your car overnight on {DATE}?", "\"Eggs hit it and the paint was etched. It cost $650 to correct. I found it the next day.\""), .direct("What did a neighbor see?", "\"A car cruised the street at about nine, and the eggs hit around 9:10. The neighbor saw the car pass before it began.\""), .direct("What did you notice the next morning?", "\"Dried egg yolk on the hood, roof, and windshield, and dull spots where the paint was etched. A neighbor told me a few other cars were hit too.\""), .direct("What did the neighbor's camera show?", "\"A car cruising the street at about nine, slowing as it passed each parked car, and someone throwing eggs out the passenger window.\""), .direct("What did you find on your car when you washed it?", "\"Etched paint in several spots on the hood and roof, where the egg had sat in the sun. The body shop said the clear coat had to be redone.\""), .cross("Isn't it possible this was a Halloween prank?", "\"It may have been meant as one. But eggs eat through paint, and a prank still cost me $650 for the repair.\""), .cross("Did you see who threw the eggs?", "\"No. I was inside. I only know what the camera shows and what the neighbor said.\""), .cross("Were other cars damaged?", "\"Yes, several on the same street. I'm not the only one affected. I only know about mine, though.\""), .cross("Could you see who was in the car?", "\"No. I wasn't outside, and the camera shows a figure but not a face.\""), .cross("How did you learn {D} was the person on the camera?", "\"A deputy identified the car and spoke with {D}. I haven't spoken with {D}.\"")],
        theory: ("{D} egged a car.", "A prank."),
        allocution: "\"I'm sorry.\"",
        truths: ("Eggshells were in {DL}'s back seat.", "The eggs were old."),
        defendant: [.direct("Why did you throw eggs from the car?", "\"It was a Halloween prank. A few of us were cruising around, and we thought it was harmless fun. It wasn't about anyone.\""), .direct("Did you know eggs could damage paint?", "\"Not really. I thought they'd wash right off. I never meant to damage anyone's car.\""), .direct("Did you target {V}'s car?", "\"No. We threw at cars along the street without knowing who owned any of them. {V}'s was one of several.\""), .direct("Tell the jury what you and your friends were doing that night.", "\"It was a couple of nights before Halloween. We were driving around, joking, and someone had a carton of eggs from a store run.\""), .direct("Why did you throw eggs?", "\"As a prank. We thought it was harmless, and we threw at cars at random without picking any particular one.\""), .direct("What did you do when you learned about the damage?", "\"I felt awful. I told a deputy what I'd done and offered to pay for the repairs.\""), .cross("The camera shows you throwing, doesn't it?", "\"It does. I'm not denying it. It was a dumb prank, and I didn't realize the damage.\""), .cross("You cruised the street first, didn't you?", "\"Yes, we drove around before we started. I'm not going to say we didn't plan it a little.\""), .cross("$650 in damage isn't harmless, is it?", "\"No. I understand that now. I just didn't think about it that night.\""), .cross("You cruised the street before throwing. Doesn't that show you were planning it?", "\"We drove around and then decided. I'm not claiming it was spontaneous, only that we didn't choose {V}'s car.\""), .cross("Eggs etch paint. Did you know that?", "\"Not at the time. I know now, and I apologize.\"")],
        openings: ("Eggs hit {V}'s car and several others along one street at about 9:10 at night, etching the paint at a cost of $650. A neighbor's camera shows {D} throwing eggs from a car. The State will show the video and the neighbor.", "Jurors will also see a Halloween prank by a young driver who never knew whose cars they were, and who didn't intend any real damage. A bad idea is not a malicious one."),
        closings: ("The car cruised the street, the eggs hit at 9:10, and the camera shows {D} throwing. The cost to {V} is $650, and the damage was real.", "{D} threw eggs at random cars as a prank and admits it. The State has not proved {D} meant to damage {V}'s paint."),
        timeline: [(0, "9 p.m.: the car cruises the street."), (0, "9:10 p.m.: the eggs hit."), (1, "{V} finds the paint damaged.")],
        identified: "Neighbor Camera",
        mood: .indifferent)

    static let pumpkinPatchTheft = SmallCases.make(
        key: "story.pumpkinPatchTheft",
        category: .property,
        headlines: ["Man Loads Dozens of Pumpkins From Farm Stand Without Paying"],
        law: "misdLarceny",
        spec: "Stole pumpkins valued at $360 belonging to {V}, a farm stand, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A farm stand lost 60 pumpkins worth $360 on {DATE}. A driver was seen loading them into a van, and the plate is {D}'s. The stand sits at the edge of the farm's field and sells on an honor system. The van pulled in at about 4 p.m. and left twenty minutes later, and the owner counted the honor box the next day.",
        state: [E(.video, 3, "Stand Camera", "{D} loads pumpkins into a van."), E(.document, 2, "Closing Count", "Sixty pumpkins counted the night before.")],
        defense: [E(.statement, 1, "Honor Box", "{DL} says {D.he} left money in the box.")],
        role: "Farm owner",
        exam: [.direct("Tell the jury how your farm stand works.", "\"It's a stand at the edge of our field. We put out pumpkins in the fall, with a sign and a locked cash box, and customers drop in money on the honor system.\""), .direct("What was taken from your farm stand?", "\"All sixty pumpkins. I counted them the night before, and in the morning the table was empty, a loss of about $360.\""), .direct("What did the stand camera show?", "\"A van pulled in at about 4 p.m. and {D} loaded pumpkins into it for twenty minutes, then left. The plate is {D}'s.\""), .direct("What was in the honor box?", "\"Only $12 the next day when I counted it. The stand runs on an honor system, so I rely on people to pay.\""), .direct("How many pumpkins were there the night before?", "\"Sixty, which I counted when I closed up at dusk. They were lined up on three tables by size.\""), .direct("What did the camera show?", "\"A white van pulls in at about four o'clock and a person loads pumpkins by the armful. The van leaves twenty minutes later and the tables are empty.\""), .cross("{D} says money was paid in the box, doesn't {D.he}?", "\"Yes. But the box held $12, which does not come close to the value of sixty pumpkins.\""), .cross("Does an honor system make it hard to say who paid?", "\"Yes. I do not know who put what in the box. I can only count what was there in the morning.\""), .cross("Did {D} try to hide the loading from the camera?", "\"No. {D} loaded in the open, in daylight, with the plate in view. I will say that.\""), .cross("Do customers sometimes pay more or less than the posted prices?", "\"Usually they pay what the sign says. Occasionally someone puts in extra, and occasionally someone shorts us.\""), .cross("Did you see {D} put money in the box?", "\"I wasn't there. The camera shows someone near the box but not what was dropped.\"")],
        theory: ("{D} took pumpkins without paying.", "Money in the box."),
        allocution: "\"I'm sorry.\"",
        truths: ("The box held only $12.", "{DL} resells at a roadside stand."),
        defendant: [.direct("Did you pay for the pumpkins?", "\"I put money in the honor box. I paid what I thought was fair for what I loaded.\""), .direct("How many pumpkins did you load?", "\"Quite a lot. I load them myself and I resell them at a roadside stand.\""), .direct("How much did you pay?", "\"A lot. I put in what I had, and I believed it was enough.\""), .direct("Tell us about your pumpkin business.", "\"I sell pumpkins at a roadside stand in the fall. I buy from farms like this one and resell at a small markup.\""), .direct("How many pumpkins did you take, and what did you pay?", "\"About sixty. I put in what I thought was about $360, which is the posted price, and I walked away.\""), .direct("How is it that the box held only $12?", "\"I don't know. Maybe someone took the rest, or I put in less than I thought.\""), .cross("The box had $12. Was that your money?", "\"Some of it was. I cannot say exactly how much I put in, and I know it looks small.\""), .cross("Sixty pumpkins for $12. How is that fair?", "\"It is not. I thought I put in more. I did not count carefully.\""), .cross("You resell pumpkins at your stand. Isn't that why you took so many?", "\"Yes, and I planned to pay for them. I was not trying to rip off a farm.\""), .cross("Sixty pumpkins for $12 is a steal. Doesn't that look like a theft?", "\"It looks that way. I can't explain it, except that I thought I'd paid.\""), .cross("You resell pumpkins. Isn't it convenient to take a farm's whole stock for resale?", "\"I do resell some, but I intended to pay for them. I wouldn't take another farm's stock without paying.\"")],
        openings: ("A farm stand on an honor system lost all 60 of its pumpkins, worth $360. A camera shows a van loading them for twenty minutes, the plate is {D}'s, and the honor box held only $12.", "By the end of this trial, the proof will show that {D} loaded in plain daylight, paid into the honor box, and had no reason to hide. {D} believed the payment was fair."),
        closings: ("Sixty pumpkins counted the night before, an empty table in the morning, and a van with {D}'s plate. The honor box held $12 for $360 of produce.", "{D} loaded openly in daylight and paid into the box as the honor system asks. The State must prove {D} meant to take pumpkins without paying, and an honest mistake about the price is not that."),
        timeline: [(0, "4 p.m.: the van pulls in."), (0, "4:20 p.m.: the van leaves."), (1, "The owner counts the box.")],
        identified: "Stand Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let cemeteryFlowers = SmallCases.make(
        key: "story.cemeteryFlowers",
        category: .property,
        headlines: ["Flower Arrangements Taken From Graves at County Cemetery"],
        law: "misdLarceny",
        spec: "Stole flower arrangements valued at $180 belonging to {V}, a cemetery visitor, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Arrangements placed on graves for Memorial Day were gone by evening on {DATE}. A groundskeeper saw {D} putting several into a trunk. The county cemetery was busy that weekend, and families had left arrangements on many graves. The groundskeeper saw {D} walking the rows at about 3 p.m., the trunk was loaded at 3:30 p.m., and {V} found a bare grave at 5 p.m.",
        state: [E(.video, 3, "Groundskeeper Statement", "{D} loaded arrangements into a trunk."), E(.statement, 2, "{V}", "The arrangement left that morning was gone by 5 p.m.")],
        defense: [E(.statement, 1, "Cleanup", "{DL} says {D.he} was clearing old flowers.")],
        role: "Groundskeeper",
        exam: [.direct("Please tell us about your job at the cemetery.", "\"I'm a groundskeeper. I cut grass, trim hedges, and clear old flowers on a schedule, after holidays, not before.\""), .direct("What did you see at the cemetery on {DATE}?", "\"It was a busy Memorial Day weekend, and families had left arrangements on many graves. I saw {D} walking the rows around 3 in the afternoon.\""), .direct("What did {DL} do with the arrangements?", "\"I saw {D} picking up several and putting them into a trunk. The trunk was loaded at about 3:30.\""), .direct("What did {V} find?", "\"{V} came back at 5 and found the grave bare. The arrangement placed that morning was gone.\""), .direct("What was the cemetery like that weekend?", "\"Packed. Families had left fresh arrangements on hundreds of graves for Memorial Day, and many of them stayed through the evening.\""), .direct("What did you see {D} do?", "\"{D} walked the rows at about three in the afternoon, picked up arrangements from several graves, and put them in the trunk of a car. I watched for a few minutes.\""), .cross("Did you speak to {DL} when you saw {D.him}?", "\"Not right then. I wasn't sure what I was seeing. I watched and then went to find a supervisor.\""), .cross("Do you clear old flowers from graves yourself?", "\"Yes, but we do it on a schedule, after the holiday. I don't take arrangements on a holiday weekend while families are visiting.\""), .cross("Could {DL} have thought the flowers were old?", "\"Possibly. I couldn't tell the age from where I stood. I only know they were arrangements put on graves, and {D} was taking them.\""), .cross("Did you say anything to {D} at the time?", "\"Not right then. I wasn't sure whether {D} was authorized, and I went to get my supervisor.\""), .cross("Are there volunteers who clean up flowers?", "\"Sometimes, on a cleanup day. That day wasn't one, and the flowers were all fresh.\"")],
        theory: ("{D} took flowers from graves.", "A cleanup."),
        allocution: "\"I'm sorry.\"",
        truths: ("The flowers were fresh.", "{DL} sold bouquets at a stand."),
        defendant: [.direct("What were you doing at the cemetery?", "\"I was clearing old flowers from graves. It looked to me like many of them were wilted and left over. I thought I was being helpful.\""), .direct("Did you put arrangements in your trunk?", "\"Yes, I put some in the trunk to dispose of them later. I thought they were old and abandoned.\""), .direct("Did you know families had placed arrangements for Memorial Day?", "\"I knew it was Memorial Day. I should have thought more about it. I didn't mean to take anything from anyone.\""), .direct("Walk us through what you were doing at the cemetery.", "\"I volunteer sometimes to help clear old flowers. I thought it was a cleanup day, and I walked the rows with a bag.\""), .direct("Why did you put arrangements in your trunk?", "\"Some of them looked faded to me, and I planned to throw them out. I didn't check dates or the condition of every one.\""), .direct("What did you do when the groundskeeper came over?", "\"I explained what I was doing and offered to put them back. I was embarrassed and apologized.\""), .cross("Several arrangements were in your trunk, weren't they?", "\"Yes, several. I didn't count. I was working down the rows, and I thought I was cleaning up.\""), .cross("You weren't an employee of the cemetery, were you?", "\"No. I'm not. I assumed it was fine to help. I see how it looks, and I apologize.\""), .cross("A bare grave at 5 p.m. was the result, wasn't it?", "\"Yes. I feel terrible about that. It was never my intention to hurt any family.\""), .cross("You weren't an employee or an assigned volunteer, were you?", "\"No. I was a volunteer on other days, but not that day. I should have asked first.\""), .cross("Several fresh arrangements were in your trunk. How can you say they were old?", "\"I didn't look closely. I should have, and I'm sorry for the families.\"")],
        openings: ("On Memorial Day weekend, arrangements placed on graves vanished by evening. A groundskeeper saw {D} walking the rows and loading several into a trunk, and {V} found a bare grave at 5 p.m. The State will present the groundskeeper and {V}.", "The defense will point you to a volunteer who thought {D.he} was clearing old flowers and who worked in the open in a busy cemetery. Misreading what belonged where is not theft."),
        closings: ("A holiday weekend, fresh arrangements on graves, and {D} loading them into a trunk. {V} came back to a bare grave, and a groundskeeper saw why.", "{D} worked openly in daylight and believed the flowers were old. The State has not proved {D} meant to take what belonged to a family."),
        timeline: [(0, "3 p.m.: {DL} walks the rows."), (0, "3:30 p.m.: the trunk is loaded."), (0, "5 p.m.: {V} finds a bare grave.")],
        identified: "Groundskeeper Statement",
        mood: .indifferent)

    static let firewoodLot = SmallCases.make(
        key: "story.firewoodLot",
        category: .property,
        headlines: ["Stacked Firewood Taken From Roadside Seller at Night"],
        law: "misdLarceny",
        spec: "Stole firewood valued at $300 belonging to {V}, a seller, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A roadside seller lost eight cords of stacked firewood worth $300 overnight on {DATE}. A gas station camera caught {D}'s truck stacked high on the road. The seller keeps the stacks on a rack beside the road with a hand-lettered sign. The stack was intact at 11 p.m., the truck loaded at about 2 a.m., and the seller found the racks empty the next day.",
        state: [E(.video, 3, "Gas Station Camera", "{D}'s truck carries stacked firewood."), E(.statement, 2, "Seller", "The racks were stacked at 11 p.m. and empty the next morning.")],
        defense: [E(.statement, 1, "Own Wood", "{DL} says the wood came from {D.his} property.")],
        role: "Wood seller",
        exam: [.direct("Tell us how you sell firewood and where.", "\"I cut and split wood on my property and sell it by the cord from racks beside the road. I put a hand-lettered sign out and customers leave cash in a coffee can.\""), .direct("What did you lose on {DATE}?", "\"Eight cords of stacked firewood, worth $300, gone overnight. I keep it on a rack beside the road with a hand-lettered sign.\""), .direct("When did you last see the stacks?", "\"They were stacked at 11 p.m. when I closed up. The next morning the racks were empty. Someone had loaded all of it.\""), .direct("How many cords did you have that night, and how was it stacked?", "\"Eight cords, stacked on three racks, each about four feet high. I counted them at eleven when I put the can away.\""), .direct("What did the gas station camera show?", "\"A pickup loaded far above the cab, with split logs stacked tight, passing the pumps at about two in the morning. A deputy matched the truck to {D}.\""), .direct("How did you know the missing cords were yours?", "\"My end stamps are on every piece. When deputies showed me wood with those bark stamps, I knew it came from my racks.\""), .cross("Can you say the wood in the truck was yours?", "\"Firewood looks like firewood. I can say how much I lost and when. I can't point to a mark that proves it in the video.\""), .cross("{DL} says the wood came from {D.his} property, doesn't {D.he}?", "\"I have no way to prove or disprove it by looking at the camera footage.\""), .cross("Were you there at 2 a.m.?", "\"No, I was home asleep. I know what I stacked at eleven and what was missing in the morning.\""), .cross("Is there anything on the wood that proves it was yours?", "\"I stamp the ends of some pieces with a mark, and I recovered a few like that from {D}'s property. Most are plain.\""), .cross("Could {D} have been hauling wood from another source?", "\"It's possible. Lots of people sell firewood in this area, and I can't say all of this load came from my racks.\"")],
        theory: ("{D} took firewood.", "Own wood."),
        allocution: "\"I'm sorry.\"",
        truths: ("Bark stamps matched the seller's.", "{DL} has no trees."),
        defendant: [.direct("Where did the wood in your truck come from?", "\"From my own property. I cut and stacked it myself. I'd been hauling it to sell, and I was on the road with it that night.\""), .direct("Did you take wood from {V}'s racks?", "\"No. I've never taken anything from that rack. I know the seller, and I wouldn't do that.\""), .direct("Describe your firewood for the jury.", "\"I have a wood lot on my property and I cut for my own use and a few neighbors. I'd been cutting all week.\""), .direct("Why were you hauling at 2 a.m.?", "\"I work odd hours at a mill and I'd finished loading my truck late. I was taking the wood to a customer a few miles away.\""), .direct("Have you ever bought wood from {V}'s racks?", "\"Once, a few years ago, and I paid in the can. I never took anything without paying.\""), .direct("Why did you have so much wood at two in the morning?", "\"I was hauling a load I had bought for a customer who needed it before dawn. I had no trees of my own, and I did not stop to think how it would look.\""), .cross("The truck on camera was loaded high, wasn't it?", "\"Yes, it was a big load. I'd been cutting for weeks. It's about the amount I'd haul.\""), .cross("It was two in the morning, correct?", "\"Yes, that's the time. I know it looks odd. It wasn't unusual for me to haul at night.\""), .cross("You can't prove the wood was yours, can you?", "\"Not with paper. It's firewood. I know what I cut, and I'm telling you it was mine.\""), .cross("A load of that size at two in the morning looks like a theft, doesn't it?", "\"I understand why. I load at night because I work days, and the wood in my truck was mine.\""), .cross("Wood with {V}'s end stamps turned up on your property. How do you explain that?", "\"I don't know. I may have bought some from a seller who'd bought from {V}, and I can't say which pieces.\"")],
        openings: ("A roadside seller's eight cords of firewood were stacked at 11 p.m. and gone by morning. A gas station camera shows {D}'s truck stacked high at about 2 a.m. The State will show the video and the seller's account.", "The defense will present a person who cut and hauled firewood from {D.his} own property, and a camera that cannot tell one cord of wood from another."),
        closings: ("Eight cords stacked at eleven, empty by morning, and {D}'s truck on camera loaded high at two. The amount and the timing fit.", "Firewood looks like firewood. The camera shows a loaded truck but not whose wood it was. The State has not proved {D} took it from {V}."),
        timeline: [(0, "11 p.m.: the stack is intact."), (0, "2 a.m.: {DL}'s truck loads."), (1, "The seller sees empty racks.")],
        identified: "Gas Station Camera",
        mood: .indifferent)

    static let baitShopTill = SmallCases.make(
        key: "story.baitShopTill",
        category: .property,
        headlines: ["Bait Shop Till Emptied While Clerk Stepped to the Dock"],
        law: "misdLarceny",
        spec: "Stole $280 belonging to {V}, a bait shop, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "The cash drawer at a bait shop was emptied while the clerk stepped to the dock on {DATE}. A customer, {D}, was the only person inside. The bait shop sits beside the dock and is often run by a single clerk. The clerk stepped out at 2 p.m., the drawer opened at 2:03 p.m., and the clerk was back at 2:10 p.m. to an empty drawer.",
        state: [E(.video, 3, "Counter Camera", "{D} opens the drawer."), E(.document, 2, "Drawer Count", "The drawer was $280 short at the end of the day.")],
        defense: [E(.statement, 1, "Change", "{DL} says {D.he} was making change.")],
        role: "Clerk",
        exam: [.direct("Describe your job at the bait shop for the jury.", "\"I'm the clerk, and on weekdays I'm often the only one working. I sell bait, tackle, and snacks, and I take cash and cards at the counter.\""), .direct("What happened at the bait shop on {DATE}?", "\"I stepped out to the dock at 2 p.m. When I came back at 2:10, the cash drawer was empty. {D} was the only person inside.\""), .direct("What does the counter camera show?", "\"{D} opens the drawer at about 2:03. It's a clear view of the counter and the drawer.\""), .direct("How much was missing?", "\"The drawer was $280 short at the end of the day. I'm usually the only person working, so I'm careful to count it.\""), .direct("What happened that afternoon?", "\"At about two I walked out to the dock to check on a customer's boat. I was gone for about ten minutes and left one person in the store.\""), .direct("What did you find when you came back?", "\"The register drawer was open and nearly empty. I'd counted $280 earlier that day that wasn't there anymore.\""), .cross("Did {DL} take anything out in front of the camera?", "\"The camera shows the drawer opened. I can't see exactly what {D} did with the money from that angle.\""), .cross("{DL} says {D.he} was making change, doesn't {D.he}?", "\"I do sometimes let a customer make change when I step out, but not when I haven't asked.\""), .cross("Were other customers in the shop?", "\"No, only {D}. That's why I noticed. But I wasn't there for seven minutes, so I can't say who may have come in.\""), .cross("Did you see {D} take any money?", "\"No. I was out on the dock. I only know what the counter camera shows.\""), .cross("Do customers ever open the drawer to make change?", "\"No. That's not allowed, and I told {D} afterward that no one should touch the drawer.\"")],
        theory: ("{D} emptied the till.", "Making change."),
        allocution: "\"I'm sorry.\"",
        truths: ("The bills were folded in {DL}'s pocket.", "{DL} had not bought bait."),
        defendant: [.direct("Why were you in the bait shop?", "\"I came in to get something. The clerk had stepped out, and I waited at the counter for a few minutes.\""), .direct("Why did you open the drawer?", "\"I was making change. I needed to break a bill, and the clerk wasn't there. I figured I'd put the money back and tell the clerk.\""), .direct("Did you take $280?", "\"No. I didn't take any money. I was only making change, and I put things back. I wouldn't steal from a small shop.\""), .direct("Walk us through what you were doing at the bait shop.", "\"I'd come in to buy a few supplies before heading to the water. I'd been in the shop for about five minutes when the clerk stepped out.\""), .direct("What did you do with the money?", "\"Nothing. I took out a few bills, realized I shouldn't have, and put them back. I left without buying anything because I was embarrassed.\""), .direct("What did you say to the clerk when you came out of the bait shop?", "\"I told the clerk I had made change from the drawer for a ten, and then I left. I did not explain more, because I was embarrassed and in a rush.\""), .cross("You opened a drawer that wasn't yours, didn't you?", "\"Yes, I did. I shouldn't have. I was impatient, and I know how bad it looks.\""), .cross("The clerk had stepped out, correct?", "\"Yes. That's why I did it. I was alone in the shop, and I didn't think it would matter.\""), .cross("The drawer was empty when the clerk got back, wasn't it?", "\"That's what the clerk says. I don't know how it happened. I didn't take the money.\""), .cross("Bills were folded in your pocket. Whose were they?", "\"Mine. I had folded them earlier. I didn't take $280.\""), .cross("Opening a register that isn't yours is wrong, isn't it?", "\"It is. I knew it as soon as I did it, and I wish I hadn't.\"")],
        openings: ("The clerk of a bait shop stepped out to the dock at 2 p.m. and came back at 2:10 to an empty cash drawer. The counter camera shows {D}, the only person inside, opening the drawer at 2:03. The State will show the video and the count.", "Jurors will also see a customer who opened a drawer to make change in an empty shop, took nothing, and was never seen with money. Opening a drawer is not theft."),
        closings: ("Seven minutes, one person in the shop, a drawer opened on camera, and $280 gone. The timeline leaves little room for doubt.", "The camera shows a drawer opening, not money leaving. {D} says {D.he} was making change. The State has not proved {D} took a dollar."),
        timeline: [(0, "2 p.m.: the clerk steps out."), (0, "2:03 p.m.: the drawer opens."), (0, "2:10 p.m.: the clerk returns.")],
        identified: "Counter Camera",
        mood: .indifferent)

    static let cartInPond = SmallCases.make(
        key: "story.cartInPond",
        category: .property,
        headlines: ["Shopping Carts Pushed Into Retention Pond Behind Grocery Store"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, shopping carts, causing damage of $1,100, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Fourteen shopping carts were found in a pond behind a grocery store on {DATE}. A security camera showed {D} pushing carts down the bank. The retention pond sits behind the grocery store on a slope down from the lot. {D} reached the bank at about 10 p.m., the carts rolled in twenty minutes later, and the manager found the lot short the next day.",
        state: [E(.video, 3, "Security Camera", "{D} pushes carts into the pond."), E(.document, 2, "Cart Inventory", "Fourteen carts missing from the lot.")],
        defense: [E(.statement, 1, "Dare", "{DL} says friends dared {D.him}.")],
        role: "Store manager",
        exam: [.direct("Please tell us about your store and the pond behind it.", "\"I manage the grocery store. There's a retention pond behind our lot, down a grassy slope that drops about fifteen feet from the pavement.\""), .direct("What did you find behind your store on {DATE}?", "\"Fourteen shopping carts in the retention pond behind the lot. The next day I counted the lot and found it short.\""), .direct("What does your security camera show?", "\"{D} pushing carts down the bank toward the pond at about 10 p.m. The carts rolled in over about twenty minutes.\""), .direct("What did it cost the store?", "\"Fourteen carts missing from the inventory, plus the work of getting them out of the water. They are not cheap to replace.\""), .direct("How did you discover the missing carts?", "\"A truck driver making a delivery told me there were carts floating in the pond. I walked back and counted fourteen of ours.\""), .direct("What did you do to recover them?", "\"We hired a company to pull the carts out, clean them, and check for damage. It took a full day and cost us the carts' downtime.\""), .cross("{DL} says friends dared {D.him}, doesn't {D.he}?", "\"I only know the camera shows {D} pushing carts. I can't tell you who else was there.\""), .cross("Can you see the other people on the camera?", "\"Not clearly. The camera is at a distance. I can see {D} and some movement, but I can't identify anyone else.\""), .cross("Were the carts damaged?", "\"Some were bent or rusted from the water. The pond is shallow, so we got them back, but they needed work.\""), .cross("Were any of the carts so damaged that you couldn't reuse them?", "\"Three were bent beyond repair. The other eleven were cleaned and put back.\""), .cross("Did you see {D} on the camera before the carts were pushed?", "\"I saw {D} come into the lot with a couple of other people. The camera doesn't show everything, because one angle was hidden.\"")],
        theory: ("{D} dumped carts.", "A dare."),
        allocution: "\"I'm sorry.\"",
        truths: ("Photos show {DL} laughing.", "The camera was hidden."),
        defendant: [.direct("Why did you push the carts into the pond?", "\"My friends dared me. It was a stupid thing to do. I did it without thinking about what it would cost the store.\""), .direct("Who were the friends?", "\"Some people I was with that night. I'd rather not name them. I'm the one who did the pushing, and I'll take that responsibility.\""), .direct("Did you intend to damage the store?", "\"No. I was acting like a kid. It seemed funny at the time. I didn't think about how much work it would be.\""), .direct("Tell the jury how the evening began.", "\"I was out with a few friends and we ended up behind the grocery store. One of them said I wouldn't push a cart down the bank, and I said I would.\""), .direct("What happened after the first cart?", "\"It rolled into the pond and everyone laughed. Then they dared me to do more, and I kept going.\""), .direct("What did you do when you realized it was serious?", "\"I felt terrible. I went to the store the next day, apologized to the manager, and offered to help pay for the damage.\""), .cross("You pushed fourteen carts, didn't you?", "\"Yes. I didn't count, but it was a lot. I know how that sounds, and I regret it.\""), .cross("It took twenty minutes, didn't it?", "\"Yes, I guess it did. I wasn't watching the clock. It seemed like a game until it was over.\""), .cross("You weren't forced to do it, were you?", "\"No, I wasn't. I made the choice. I know a dare is no excuse.\""), .cross("You pushed fourteen carts over twenty minutes. Isn't that more than a one-time impulse?", "\"It started as a dare and I got carried away. I didn't stop to think about what I was doing.\""), .cross("You won't name the friends. Why protect them?", "\"They aren't the ones who pushed the carts. I'm the one who did, and I'm not trying to blame anyone else.\"")],
        openings: ("Fourteen shopping carts were found in a retention pond behind a grocery store. A security camera shows {D} pushing carts down the bank at about 10 at night. The State will show the video and the inventory.", "The defense evidence includes a dare, a thoughtless prank, and a person who owned up to it. A foolish act among friends is not a plan to destroy property."),
        closings: ("Fourteen carts, twenty minutes, and a camera that shows {D} pushing every one into the water. A dare may explain it, but it does not excuse the cost to the store.", "{D} acted on a dare among friends, owned up to it, and never meant to wreck the store's property. The State must prove intent to destroy, and a foolish prank is not that."),
        timeline: [(0, "10 p.m.: {DL} reaches the bank."), (0, "10:20 p.m.: carts roll in."), (1, "The manager finds carts missing.")],
        identified: "Security Camera",
        mood: .indifferent)

    static let bowlingAlleyScuffle = SmallCases.make(
        key: "story.bowlingAlleyScuffle",
        category: .publicOrder,
        headlines: ["League Bowlers Shout and Throw Balls After Score Dispute"],
        law: "disorderly",
        spec: "Disturbed the peace by fighting and threatening in a public bowling alley, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "League bowlers shouted and threw balls after a score dispute on {DATE}. {D} was heard shouting and kicked a scorer's table. The score dispute came during a league night, with several teams on the lanes. The dispute began at about 8 p.m., the shouting started ten minutes later, and a deputy arrived at 8:20 p.m.",
        state: [E(.statement, 3, "Alley Manager", "{D} shouted and kicked a table."), E(.document, 2, "League Score Sheet", "The disputed frame is marked in two different hands.")],
        defense: [E(.statement, 1, "Heated", "{DL} says it was league banter.")],
        role: "Alley manager",
        exam: [.direct("Tell the jury how the league night works at your alley.", "\"We host a Thursday league with eight teams. Bowlers keep their own scores and a scorer's table records the totals.\""), .direct("What happened at your alley on league night, {DATE}?", "\"A score dispute began at about 8 p.m. By ten minutes later there was shouting, and {D} kicked a scorer's table.\""), .direct("What did you see {DL} do?", "\"{D} shouted and kicked the table. Other bowlers were on the lanes, and I had to step in to get things calmed down.\""), .direct("What did the score sheet show?", "\"The disputed frame is marked in two different hands. That's what the argument was about, and I kept the sheet.\""), .direct("How did the dispute begin?", "\"A bowler on {D}'s team marked a spare on one frame and a bowler on the other team marked a split. The two score sheets didn't match.\""), .direct("What did {D} do?", "\"{D} walked over to the scorer's table, started shouting, and kicked the table hard enough to move it. A dozen bowlers stopped and looked.\""), .cross("{DL} says it was league banter, doesn't {D.he}?", "\"League nights get loud, but a kicked table and shouting went past banter. I called a deputy.\""), .cross("Did {DL} hit anyone?", "\"No. I didn't see anyone get hit. {D} kicked a table and shouted. There was no fight on the lanes.\""), .cross("Did the deputy arrest anyone?", "\"The deputy arrived at 8:20 and talked to those involved. I don't recall other arrests that night.\""), .cross("Did {D} threaten or touch anyone?", "\"No. I didn't see {D} touch anyone, and I didn't hear a threat. It was loud but not physical.\""), .cross("Do disputes like this happen often in your league?", "\"Now and then. Most are settled by a coin toss or a call to the captain, and this was the first where someone kicked a table.\"")],
        theory: ("{D} disturbed the alley.", "Banter."),
        allocution: "\"I'm sorry.\"",
        truths: ("Two lanes cleared out.", "A teammate calmed {DL}."),
        defendant: [.direct("What happened at league night?", "\"We had a disagreement about a score. It got loud. League nights are competitive, and tempers flared. It was just banter.\""), .direct("Did you kick the table?", "\"I did kick the scorer's table. I was frustrated. I didn't break it or hit anyone. I just let my temper show.\""), .direct("Did you mean to threaten anyone?", "\"No. I was shouting about the score. I never made any threat to anyone. It was heated but not violent.\""), .direct("Tell us about your bowling league.", "\"I've bowled in it for six years. We're competitive, we joke around, and we usually settle scores with a laugh.\""), .direct("What happened during the disputed frame?", "\"I thought I'd picked up the spare, and the scorer for the other team marked a split. I got frustrated because it changed the match.\""), .direct("What did you do?", "\"I walked to the scorer's table and shouted that the score was wrong. I kicked the table, and I immediately felt foolish.\""), .cross("You shouted at other bowlers, didn't you?", "\"Yes, I raised my voice. I should have walked away. I know I made it worse.\""), .cross("You kicked the table in front of everyone, didn't you?", "\"Yes, I did. I regret it. I lost my temper over a game.\""), .cross("A deputy had to come, correct?", "\"Yes. The manager called. I didn't resist. I should have calmed down before it got there.\""), .cross("Other bowlers left their lanes because of you. Isn't that a disruption?", "\"Some did. I should have walked outside and cooled off, and I apologized to them afterward.\""), .cross("A deputy had to come. Do you accept that you went too far?", "\"Yes. I'm embarrassed that it came to that.\"")],
        openings: ("A score dispute on a league night became shouting, and {D} kicked a scorer's table while several teams bowled nearby. The alley manager called a deputy. The State will show the manager's account and the disputed score sheet.", "The defense will point you to competitive bowlers on a loud league night, a kicked table, and a person who never touched or threatened anyone. This was banter that got too heated."),
        closings: ("A score dispute, shouting, and a table kicked in front of a dozen bowlers. The manager had to call a deputy to restore order.", "League night gets loud. {D} kicked a table, but never hit or threatened anyone. The State has not shown a public disturbance beyond heated sport."),
        timeline: [(0, "8 p.m.: the score dispute."), (0, "8:10 p.m.: the shouting."), (0, "8:20 p.m.: a deputy arrives.")],
        identified: "Alley Manager",
        mood: .indifferent)

    static let barTabSkip = SmallCases.make(
        key: "story.barTabSkip",
        category: .property,
        headlines: ["Patron Leaves Bar Through Side Door Without Paying $90 Tab"],
        law: "misdLarceny",
        spec: "Stole bar service valued at $90 belonging to {V}, a bar, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A patron ran up a $90 tab and left through a side door on {DATE}. The bartender gave deputies {D}'s card, which was never charged. The bar was busy that night, and the bartender held {D}'s card behind the counter for the tab. The tab opened at about 9 p.m. and {D} left at 10:30 p.m.; the bartender checked the card the next day.",
        state: [E(.document, 3, "Open Tab", "A $90 tab under {D}'s name."), E(.statement, 2, "Bartender", "{D} left through the side door at about 10:30 p.m.")],
        defense: [E(.statement, 1, "Meant to Pay", "{DL} says {D.he} went to get cash.")],
        role: "Bartender",
        exam: [.direct("Tell us about the bar and how tabs work.", "\"It's a neighborhood bar. When a customer wants a tab, we hold a credit card behind the counter and charge it at the end of the night.\""), .direct("What happened with {DL}'s tab on {DATE}?", "\"{D} opened a $90 tab at about nine. The bar was busy, and I held {D}'s card behind the counter for the tab.\""), .direct("How did {DL} leave?", "\"At about 10:30, {D} left through the side door. I didn't see {D} go, but a patron told me and I checked the tab.\""), .direct("What happened with {D}'s tab?", "\"{D} opened a tab at about nine and ran it up to $90 with drinks and a food order. At about 10:30 I looked up and {D} was gone.\""), .direct("What did you do with the card?", "\"I put it in the drawer and charged nothing that night. The next day I handed it to a deputy with the tab slip.\""), .direct("What did you tell deputies about {D} when they came?", "\"I said {D} left through the side door at about 10:30 with the tab still open. I gave them the card, and I checked it the next morning.\""), .cross("{DL} says {D.he} went to get cash, doesn't {D.he}?", "\"People do step out for cash sometimes. But {D} didn't tell me, and {D} didn't come back.\""), .cross("You held {DL}'s card, didn't you?", "\"Yes. I could have run the card myself. I didn't. I should have charged it before {D} left.\""), .cross("Did {DL} come back at any point?", "\"Not that night, that I saw. The bar was busy, and I wasn't watching the door every minute.\""), .cross("Did {D} say anything to you about leaving?", "\"No. It was busy and I didn't see {D} go. I saw the side door close and the stool was empty.\""), .cross("Could {D} have gone out for cash and meant to return?", "\"It's possible. People step out sometimes and come back, but {D} didn't.\"")],
        theory: ("{D} skipped a tab.", "A cash run."),
        allocution: "\"I'm sorry.\"",
        truths: ("The card was left behind.", "The ATM was out of order."),
        defendant: [.direct("Why did you leave the bar?", "\"I needed to go get cash because I thought my card wouldn't cover the whole tab. I left through the side door, which was the closest way out.\""), .direct("Did you plan to come back?", "\"Yes. I meant to come back and pay. I left my card with the bartender because I intended to return.\""), .direct("Did you try to skip the bill?", "\"No. I'd never walk out on a tab. I left my card behind, and I assumed the bartender would hold it.\""), .direct("Describe your evening at the bar for the jury.", "\"I met a friend there after work. We ate, had a few drinks, and I opened a tab on my card.\""), .direct("Why did you leave?", "\"I realized the ATM in the bar was out of order and I wanted to get cash to tip. I walked out the side door to find one.\""), .direct("Why didn't you return?", "\"I got a call from a family member and I had to drive somewhere. I meant to come back the next day, and I forgot.\""), .cross("You never told the bartender you were leaving, did you?", "\"No. It was busy and I didn't want to interrupt. I should have said something.\""), .cross("You didn't return that night, did you?", "\"No. Something came up, and I went home. I should have called. I am truly sorry.\""), .cross("The tab was $90, wasn't it?", "\"Yes. I'm willing to pay it. I'd have paid right then if I'd thought about it.\""), .cross("You didn't tell the bartender you were leaving. Why?", "\"It was busy and I thought I'd be back in a few minutes. I should have said something.\""), .cross("You left your card behind. Does that help you or hurt you?", "\"It helps, because I wouldn't leave a card if I meant to skip. I knew the bartender had it.\"")],
        openings: ("A patron opened a $90 tab at about 9 p.m. and left through a side door at 10:30. The bartender held {D}'s card, which was never charged. The State will show the tab and the bartender's account.", "The defense will present a customer who left a card behind, expecting to come back after getting cash. Leaving a card at a bar is not what a person who means to skip a tab does."),
        closings: ("A $90 tab, a side door, and a patron who never returned. The card sat unused behind the counter, and the bar was never paid.", "{D} left a card behind and meant to return. The State must prove {D} meant to cheat the bar, and leaving a card is the opposite."),
        timeline: [(0, "9 p.m.: the tab opens."), (0, "10:30 p.m.: {DL} leaves."), (1, "The bartender checks the card.")],
        identified: "Open Tab",
        mood: .indifferent)

    static let tireSwapScam = SmallCases.make(
        key: "story.tireSwapScam",
        category: .whiteCollar,
        headlines: ["Mobile Seller Takes Cash for New Tires, Installs Used Ones"],
        law: "falsePretenses",
        spec: "Obtained $520 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} paid {D} $520 for four new tires on {DATE}. A shop later found the tires worn and recapped. The sale was made at a lot where {D} sells tires from a trailer. {V} had the tires checked two days later, and the shop found they were used.",
        state: [E(.document, 3, "Shop Report", "The tires were recapped and worn."), E(.document, 2, "Receipt", "A receipt that says 'new tires.'")],
        defense: [E(.statement, 1, "Supplier", "{DL} says a supplier shipped used tires.")],
        role: "Tire shop owner",
        exam: [.direct("What can you tell us about your shop and how you check tires?", "\"I own a tire shop and have worked on tires for twenty years. I check the date code, tread depth, and the sidewall for repairs.\""), .direct("What did you find when {V} brought the tires to you?", "\"The tires were worn and recapped. I could see the retread seams, and they were not new tires by any measure.\""), .direct("What did the receipt say?", "\"It said 'new tires' and listed $520 for four. {V} had paid that two days earlier at a lot where {D} sells from a trailer.\""), .direct("How long did it take you to tell?", "\"A few minutes of inspection. I do this every day, and recapped tires are easy to spot.\""), .direct("What did you see when {V} brought the tires in?", "\"They were worn smooth in places, with the rough texture of a recap on the tread. The date code was twelve years old.\""), .direct("How can you tell a recap from a new tire?", "\"The tread band has a visible seam and a different texture from the sidewall. A new tire has the manufacturer's brand molded in all over.\""), .cross("Can a customer tell a recap from a new tire at a glance?", "\"Most cannot. That is why people trust the seller and the receipt.\""), .cross("Did you find a supplier invoice from {D}?", "\"No, none was produced to me. I do not know where the tires came from.\""), .cross("Are recapped tires illegal to sell?", "\"No, they can be sold if they are labeled and priced as recaps. The problem is calling them new.\""), .cross("Could a customer easily tell the difference?", "\"Most could not. They'd have to know what to look for or have someone check.\""), .cross("Did you find any paperwork showing where the tires came from?", "\"No. There was only the receipt from {D}, which said 'new tires.'\"")],
        theory: ("{D} sold used tires as new.", "A supplier error."),
        allocution: "\"I'm sorry.\"",
        truths: ("The receipt said 'new'.", "No supplier invoice exists."),
        defendant: [.direct("Did you sell {V} new tires?", "\"I sold what I believed were new tires. I bought them from a supplier and sold them as I got them.\""), .direct("Where did the tires come from?", "\"From a supplier that I bought a lot from. I did not inspect each tire closely.\""), .direct("Do you have an invoice?", "\"I lost it. It was in a pile of paper, and I cannot find it now.\""), .direct("Walk us through how you run your tire business.", "\"I sell tires from a trailer on a lot I rent. I buy from a few suppliers and I mark up what I sell.\""), .direct("Where did these tires come from?", "\"From a supplier I'd used before. I was told they were new, and I trusted the supplier.\""), .direct("Do you have an invoice for them?", "\"I lost it. It was in a stack of papers that got wet, and I couldn't find it when deputies asked.\""), .cross("The receipt says new, and they were recapped. Who is responsible?", "\"I may have been misled by my supplier. I did not know they were recaps.\""), .cross("You sell from a trailer. Don't you inspect what you sell?", "\"I look at them, but I am not an expert. I did not see the retread.\""), .cross("Without an invoice, how can the jury believe you?", "\"I understand. All I can say is that I believed they were new.\""), .cross("You wrote 'new tires' on the receipt. Did you check them yourself?", "\"I looked at them and they seemed fine. I didn't check the date code, and I should have.\""), .cross("You sell from a trailer. Isn't it your job to make sure what you sell is what you say?", "\"Yes, it is. I take responsibility for that, and I'm trying to make it right.\"")],
        openings: ("{V} paid {D} $520 for four tires on a receipt marked 'new tires.' Two days later, a tire shop found them worn and recapped, and no supplier invoice exists.", "The defense evidence will establish that {D} bought the tires from a supplier and believed they were new. If anyone was fooled, {D} was fooled too."),
        closings: ("A receipt that says new, four tires that were recapped and worn, and no invoice to show where they came from. {V} paid $520 for something that was not what was promised.", "{D} sold what {D} believed were new tires. The State must prove {D} knew they were recaps, and a missing invoice is carelessness, not fraud."),
        timeline: [(-2, "The sale."), (0, "{V} checks the tires."), (0, "A shop confirms they are used.")],
        identified: "Shop Report",
        mood: .indifferent)

    static let mowCrewNoShow = SmallCases.make(
        key: "story.mowCrewNoShow",
        category: .whiteCollar,
        headlines: ["Lawn Crew Takes Season Prepayment and Never Mows"],
        law: "falsePretenses",
        spec: "Obtained $450 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} took a $450 season prepayment from {V} for lawn care on {DATE} and never came back. Two other customers say the same. {D}'s crew handed out flyers around the neighborhood at the start of the season. {V} paid thirty days before calling {D}, and then learned that two other customers had paid for the same season.",
        state: [E(.digital, 3, "Texts", "{D} promises a first mow 'Friday'."), E(.document, 2, "Receipt", "A $450 receipt for a season of lawn care.")],
        defense: [E(.statement, 1, "Weather", "{DL} says rain delayed the season.")],
        role: "Homeowner",
        exam: [.direct("Tell us how you came to hire {D}.", "\"A flyer for a lawn care crew came in my mailbox at the start of the season. I called the number and {D} came by and quoted $450 for a season of weekly mowing.\""), .direct("What did you pay {D} for?", "\"$450 for a season of lawn care. I paid in advance, and the receipt says exactly that.\""), .direct("What did {D} promise?", "\"A first mow on Friday. The texts say so, and I waited at home that Friday.\""), .direct("What happened after that?", "\"Nobody ever came. I waited thirty days before I called, and then I learned two other customers had paid for the same season.\""), .direct("How and when did you pay?", "\"I handed {D} $450 in cash and got a handwritten receipt. {D} promised the first mow on a Friday and sent me a text to confirm.\""), .direct("What did you do when no one came?", "\"I waited a few weeks, thinking the rain had delayed things. Then I called and texted, and when {D} stopped responding I called the other customers on the flyer.\""), .cross("Did anyone mow your lawn at all?", "\"No. Not one time. I ended up cutting it myself.\""), .cross("Was the weather bad that spring?", "\"There was some rain, but it was also dry for stretches. I do not think rain explains a month of nothing.\""), .cross("Did {D} ever answer your texts?", "\"For a while, yes. Then the answers stopped, and I had no way to reach {D}.\""), .cross("Did {D} ever tell you the crew was having problems?", "\"Once, in a text, {D} said the mower was in the shop. After that I didn't hear anything.\""), .cross("Was the weather an obstacle to mowing that spring?", "\"There were a few rainy days early on, but after that it was dry for about six weeks, and my grass grew a foot.\"")],
        theory: ("{D} took prepayments.", "A rainy season."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} sold the crew's mower.", "It was dry for six weeks."),
        defendant: [.direct("Did you plan to mow {V}'s lawn?", "\"Yes. I took the money for a season, and I fully planned to mow. I had a crew set up.\""), .direct("Why did the mowing not happen?", "\"Rain. We lost weeks to the weather, and then things fell apart with my crew.\""), .direct("Did you mow any lawns that season?", "\"No. The season never really got going for us, and I fell behind on everything.\""), .direct("What can you tell us about your lawn care business?", "\"I started it in March with two friends and one mower. We handed out flyers and signed up about a dozen customers.\""), .direct("What happened to the crew?", "\"One friend moved away and the other quit after the first rain delay. I was left with the mower and too many customers.\""), .direct("What happened to the mower?", "\"It broke in April, and I sold it to pay for a repair on my truck. I told myself I'd get another, and I never did.\""), .cross("Your crew's mower was sold, wasn't it?", "\"Yes, I sold it to cover bills. I know that was a bad choice.\""), .cross("Why not give refunds?", "\"I did not have the money by then. I meant to pay it back, and I did not.\""), .cross("You took three customers' prepayments and mowed none. Isn't that a scam?", "\"It's a failure, and I didn't intend it as a scam. I overextended and then panicked.\""), .cross("You stopped answering texts. Why?", "\"I was ashamed and I didn't have the money to refund. I should have been honest.\""), .cross("It stayed dry for six weeks, didn't it?", "\"Yes. Rain was not the whole story. I lost my mower and my crew, and I should have told {V} instead of going quiet.\""), .cross("You never offered {V} a refund, did you?", "\"No. I spent the money on bills and expected to catch up. I understand why that looks like taking it and running.\"")],
        openings: ("{D} took a $450 prepayment from {V} for a season of lawn care and never mowed once. Two other customers say they paid for the same season, and no one ever showed up.", "By the end of this trial, the proof will show that {D} meant to mow and that rain and a failing crew got in the way. A failed business is not a crime without intent to cheat."),
        closings: ("Three customers prepaid for a season and none got a single mow. {D} sold the crew's mower and stopped answering. That is how a scheme ends, not a business.", "A wet spring, a crew that fell apart, and a small business that failed. The State must prove {D} intended from the start to take money and do no work."),
        timeline: [(-30, "{V} pays."), (0, "{V} calls {D}."), (0, "{V} finds two other customers.")],
        identified: "Texts",
        mood: .indifferent)

    static let formulaShoplift = SmallCases.make(
        key: "story.formulaShoplift",
        category: .property,
        headlines: ["Shopper Stuffs Infant Formula Into Coat at Pharmacy"],
        law: "larcenyMerchant",
        spec: "Took infant formula valued at $210 from {V}, a pharmacy, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A pharmacy camera showed {D} stuffing six cans of formula into a coat on {DATE}. The cans were worth $210. The formula was on a shelf near the front of the pharmacy. {D} came in at 4 p.m., put the cans in a coat at 4:10 p.m., and left at 4:12 p.m.",
        state: [E(.video, 3, "Aisle Camera", "{D} puts six cans in a coat."), E(.document, 2, "Price Tags", "Six cans priced at $210 in total.")],
        defense: [E(.statement, 1, "Need", "{DL} says {D.he} had no money for {D.his} baby.")],
        role: "Pharmacist",
        exam: [.direct("Tell us about your pharmacy and how formula is stocked.", "\"It's a neighborhood pharmacy. The infant formula is on a shelf near the front, in cans that run $35 or so each.\""), .direct("What did you see on the pharmacy camera on {DATE}?", "\"{D} came in at about 4 p.m. At about 4:10, {D} put six cans of formula into a coat and left two minutes later.\""), .direct("What was the value of the formula?", "\"Six cans priced at $210 in total. The formula sits on a shelf near the front of the pharmacy.\""), .direct("What did you do when you noticed?", "\"I reviewed the camera after I saw the shelf was short, and I reported it. I didn't see it happen live.\""), .direct("What did the aisle camera show?", "\"At about 4:10, {D} takes six cans from the shelf, glances toward the register, and slides them into the lining of a long coat. {D} walks out at 4:12 without stopping.\""), .direct("What did you do after you saw the footage?", "\"I called the sheriff's office, checked the shelf, and wrote down the missing count. The total was six cans, $210.\""), .cross("{DL} says {D.he} had no money for {D.his} baby, doesn't {D.he}?", "\"I understand formula is expensive. I'm not unsympathetic, but it was taken from the shelf without payment.\""), .cross("Did {DL} threaten anyone?", "\"No. {D} came in, took the cans, and left. There was no confrontation with any employee.\""), .cross("Was {DL} offered help at the store?", "\"No. We don't have a program, and nobody spoke to {D}. I wish somebody had, but nobody noticed until after.\""), .cross("Did {D} try to leave quietly or hurry?", "\"{D} walked out at a normal pace. There was no running and no one stopped {D}.\""), .cross("Does the pharmacy have a policy on people who say they can't afford formula?", "\"We direct people to a nearby shelter that provides formula. I wish {D} had asked.\"")],
        theory: ("{D} took formula.", "A hungry baby."),
        allocution: "\"I'm sorry.\"",
        truths: ("The coat was lined for storage.", "A shelter offered formula."),
        defendant: [.direct("Why did you take the formula?", "\"I have a baby at home, and I had no money for formula. I didn't know what else to do that day.\""), .direct("Did you try to get help first?", "\"I did look for help but I was turned away from a couple of places. By the time I got to the pharmacy I was desperate.\""), .direct("How did you feel doing it?", "\"Terrible. I'm not a thief. I knew it was wrong, and I did it anyway because the baby needed to eat.\""), .direct("Please describe your baby.", "\"I have an eight-month-old at home. The baby needs formula and I had run out two days before.\""), .direct("What had you tried before you went to the pharmacy?", "\"I'd called a food pantry, and they were closed. I'd asked a relative for money and been told no.\""), .direct("Why did you put the cans in your coat?", "\"I panicked. I didn't have the money and I couldn't wait any longer. I'd never done anything like it before.\""), .cross("You put six cans in your coat, didn't you?", "\"Yes, I did. I needed enough to last. I know that was a lot, and I regret it.\""), .cross("You didn't try to pay for even one can, did you?", "\"I didn't have the money for even one. I know there are other ways, and I should have looked harder.\""), .cross("The camera shows you leaving, doesn't it?", "\"It does. I walked out. I wasn't running. I was scared and ashamed.\""), .cross("You put six cans in a coat. Isn't that more than a baby needs for a day?", "\"Six cans last about two weeks. I didn't know when I'd be able to buy more.\""), .cross("A shelter offered formula. Why didn't you go there?", "\"I didn't know that. If I'd known, I would have gone.\"")],
        openings: ("A pharmacy camera shows {D} putting six cans of formula, worth $210, into a coat at about 4:10 and walking out two minutes later. The State will show the video and the prices.", "The defense will point you to a desperate parent with a baby to feed, no money, and a theft of necessity. The question is what a decent jury does with that."),
        closings: ("Six cans, a coat, and a walk out the door, all on camera. Whatever the reason, the formula was not {D}'s to take.", "A hungry baby and an empty wallet. {D} took what a child needed, and nothing else. This is the kind of desperation that deserves mercy."),
        timeline: [(0, "4 p.m.: {DL} enters."), (0, "4:10 p.m.: cans go into the coat."), (0, "4:12 p.m.: {DL} leaves.")],
        identified: "Aisle Camera",
        mood: .sympathetic)

    static let perfumeShoplift = SmallCases.make(
        key: "story.perfumeShoplift",
        category: .property,
        headlines: ["Customer Pockets Perfume Bottles From Department Store Counter"],
        law: "larcenyMerchant",
        spec: "Took perfume valued at $330 from {V}, a department store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Three bottles of perfume worth $330 left a department store counter in {D}'s pocket on {DATE}. Security stopped {D} at the doors. The perfume counter stands near the main entrance of the store. {D} was browsing at 1 p.m., the bottles went into the pocket at 1:10 p.m., and security stopped {D} at 1:15 p.m.",
        state: [E(.physical, 3, "Perfume Bottles", "Three tagged bottles in {D}'s pocket."), E(.statement, 2, "Security Officer", "Stopped {D} at the doors with the three bottles.")],
        defense: [E(.statement, 1, "Sample", "{DL} says {D.he} forgot them.")],
        role: "Security officer",
        exam: [.direct("Tell the jury about your job and the perfume counter.", "\"I'm a security officer at a department store. The perfume counter is near the main entrance, and it's one of the places we watch closely.\""), .direct("What did you see at the perfume counter?", "\"Around 1:10 p.m., {D} put three bottles in a pocket after browsing for about ten minutes near the main entrance.\""), .direct("Where did you stop {D}?", "\"At the doors, at about 1:15. {D} had walked past the registers without stopping, with the three bottles still in a pocket.\""), .direct("What did you find on the bottles?", "\"They were still tagged. The three bottles were worth $330 in total.\""), .direct("What did you see?", "\"{D} browsed the counter for about ten minutes, picked up three bottles, and put them into a coat pocket. {D} then walked toward the front doors.\""), .direct("How did you stop {D}?", "\"At the doors, I introduced myself and asked {D} to come back inside. {D} stopped right away and didn't try to run.\""), .cross("Were the tags still attached when you stopped {D}?", "\"Yes. That is what I wrote in my report. Some tags may have come loose, but they were on.\""), .cross("Did {D} try to run when you approached?", "\"No. {D} stopped when I asked. {D} did not fight or flee.\""), .cross("The perfume counter is right near the entrance, isn't it?", "\"Yes. That makes it easy to walk out, and I cannot say whether {D} was heading for the register.\""), .cross("Were the bottles still tagged?", "\"Yes. Each had a security tag, and I saw no sign that any had been cut.\""), .cross("Did {D} say anything when you stopped {D.him}?", "\"{D} said it was a mistake and that {D.he} had forgotten the bottles in the pocket. {D} was polite.\"")],
        theory: ("{D} took perfume.", "Forgotten samples."),
        allocution: "\"I'm sorry.\"",
        truths: ("The tags were cut.", "{DL} passed three registers."),
        defendant: [.direct("Did you pay for the perfume?", "\"I forgot to. I was distracted and I put the bottles in my pocket while I looked at something else.\""), .direct("Why were the tags an issue?", "\"They fell off. I did not cut anything. I do not know how they came off.\""), .direct("Did you pass a register on your way out?", "\"I did. I walked right past one, and I do not remember why I did not stop.\""), .direct("Explain to the jury why you went to the perfume counter.", "\"I was shopping for a gift for a family member. I tried a few scents and took a couple to the register, and then I got a phone call.\""), .direct("What happened with the phone call?", "\"It was a work call and I was distracted. I put the bottles in my coat pocket to free my hands and walked out while I was talking.\""), .direct("What did you do when security stopped you?", "\"I was surprised. I said I'd forgotten about them and offered to pay right then.\""), .cross("You walked past three registers with three bottles in your pocket, didn't you?", "\"I did. I wasn't thinking. I know it looks like I was leaving without paying.\""), .cross("Why put perfume in your pocket instead of a basket?", "\"I did not have a basket. It was easier, and I did not think about it.\""), .cross("You were stopped at the doors. Weren't you leaving the store?", "\"I was leaving, but I would have noticed and gone back. At least I think I would have.\""), .cross("You walked past three registers with three bottles in your pocket. How is that forgetting?", "\"I was on the phone and I wasn't paying attention. It looks bad, I know.\""), .cross("Why put the perfume in your pocket instead of holding it?", "\"I needed my hands for my phone and my bag. I didn't think about what it looked like.\"")],
        openings: ("Three bottles of perfume worth $330 left a department store counter in {D}'s pocket. Security stopped {D} at the doors, five minutes after the bottles went in and after passing several registers.", "The defense witnesses will explain that {D} was distracted, forgot to pay, and did not run when stopped. {D} never meant to steal."),
        closings: ("Three tagged bottles in a pocket, three registers passed, and a stop at the doors. A person who forgets one item does not forget three bottles and every register.", "A distracted shopper who stopped without a fight when approached. The State must prove {D} meant to leave without paying, and a lapse of memory is not that."),
        timeline: [(0, "1 p.m.: {DL} browses."), (0, "1:10 p.m.: bottles in the pocket."), (0, "1:15 p.m.: security stops {DL}.")],
        identified: "Perfume Bottles",
        mood: .indifferent)

