        defense: [E(.statement, 1, "Friend", "{DL} says a friend asked {D.him} to pick it up.")],
        role: "Pizzeria owner",
        exam: [.direct("Tell us about your pizzeria and how phone orders work.", "\"We take large orders by phone for pickup at the counter. The caller gives a name and a card number, and we run the card before we start cooking.\""), .direct("When was the order placed?", "\"At about 5 p.m. someone phoned in $240 worth of pizza for pickup at the counter, and it was picked up about an hour later.\""), .direct("Who picked it up?", "\"{D}. Our counter camera shows {D} at the counter taking the order.\""), .direct("What happened with the card?", "\"The card number was stolen. The card owner disputed the $240 charge two days later, and we lost the money.\""), .direct("What was unusual about this order?", "\"It was $240 for eight large pizzas and sides, placed at about five on a weeknight. The caller was in a hurry and didn't want delivery.\""), .direct("Who picked up the order, and what happened?", "\"{D} came in at about six, gave the name on the order, and carried out eight boxes. Two days later the card owner disputed the charge.\""), .cross("Did {D} place the call?", "\"I cannot say. I took the order by phone, and I did not know the voice.\""), .cross("Did {D} pay at the counter?", "\"The card had been charged already. {D} just picked up the bag.\""), .cross("Did {D} say who the order was for?", "\"{D} gave a name and took the food. I did not ask any more than that.\""), .cross("Did {D} place the phone call?", "\"I don't know. I took the call, but the voice was low and hurried and I didn't see who it was.\""), .cross("Did {D} seem to know the card was stolen?", "\"No. {D} was polite and said it was for a friend's party. I had no sense that anything was wrong.\"")],
