        allocution: "\"I'm sorry.\"",
        truths: ("The phone number matched {DL}'s.", "The friend had no phone."),
        defendant: [.direct("Did you place that order?", "\"No. I did not call it in, and I did not use anyone's card.\""), .direct("Why did you pick it up?", "\"A friend asked me to pick it up. I did not know the card was stolen.\""), .direct("Did you know the order was paid with a stolen card?", "\"No. I had no idea. I thought I was doing a favor.\""), .direct("Explain to the jury how you ended up at the pizzeria.", "\"A friend called and asked me to pick up a big pizza order on my way home. I said sure, since it was on my way.\""), .direct("Why did your friend ask you instead of picking it up?", "\"The friend said they were stuck at work and couldn't leave. I thought nothing of it.\""), .direct("What did you do with the pizzas?", "\"I drove them to a house where my friend said a gathering was going on. I handed them off and left.\""), .cross("The phone number on the order matched your phone, didn't it?", "\"My phone was with my friend at the time. I do not know how it was used.\""), .cross("Why would a friend ask you to pick up pizza?", "\"The friend was busy and asked me for a ride. I know that is hard to prove.\""), .cross("What is the friend's name?", "\"I know the name, but I do not have a way to reach the friend now.\""), .cross("The phone number on the order matched yours. How do you explain that?", "\"My friend borrowed my phone that afternoon to place a call. It seemed like an ordinary request.\""), .cross("You didn't wonder why a friend would use your phone and your name for an order?", "\"I didn't. It was a favor, and I didn't ask questions.\"")],
