        spec: "Obtained $400 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} bought $400 in prepaid cards on {DATE} after a caller said the power would be cut. The cards were redeemed by {D}. The caller used a number that looked local. The call came at 10 a.m., {V} bought the cards at 11 a.m., and the cards were redeemed the next day.",
        state: [E(.digital, 3, "Card Records", "The cards were redeemed by {D}'s account."), E(.statement, 2, "{V}", "The caller said the power would be cut in an hour.")],
        defense: [E(.statement, 1, "Reseller", "{DL} says {D.he} bought the cards secondhand.")],
        role: "Resident",
        exam: [.direct("Describe your day when the call came for the jury.", "\"I was home on a weekday morning when the phone rang at about ten. The number looked local, and the caller said they were from the power company.\""), .direct("How long were you given?", "\"One hour. I felt I had to hurry, and I went out and bought prepaid cards.\""), .direct("What did you do?", "\"I bought $400 in prepaid cards at about 11 a.m. and read the numbers to the caller.\""), .direct("What did the caller say?", "\"That my account was overdue and the power would be cut in an hour unless I paid $400 by prepaid card. The caller sounded stern and gave me a number to read.\""), .direct("What did you do?", "\"I drove to a store, bought $400 in prepaid cards, and read the numbers over the phone. I felt sick afterward when I realized I'd been taken.\""), .direct("What did the caller tell you to do with the cards after you bought them?", "\"To read the numbers over the phone right away. I did that in the pharmacy parking lot, and the caller hung up as soon as I finished.\""), .cross("You never saw the caller, did you?", "\"No. It was only a voice on the phone. I do not know who it was.\""), .cross("Did you call your utility to check?", "\"No. I did not. I wish I had.\""), .cross("Did you speak with {D} at any time?", "\"No. I have never spoken with {D}. I only know that {D}'s account redeemed the cards.\""), .cross("Did you call the power company to confirm?", "\"No. I should have, but the caller said there wasn't time. I was afraid of losing power with my medical equipment.\""), .cross("Did the caller ever give a name or a number you could call back?", "\"A first name and a number that went to voicemail. I never spoke to anyone else.\"")],
