        headlines: ["Seller Sells Used Phones That Are Carrier-Locked and Reported Lost"],
        law: "falsePretenses",
        spec: "Obtained $360 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} paid {D} $360 for a used phone on {DATE}. The carrier had it locked as lost and refused to activate it. {D} sold the phone out of a shop, and {V} took it to the carrier the next day. The carrier refused to activate it, and {V} called {D} the day after that.",
        state: [E(.document, 3, "Carrier Notice", "The phone is locked and reported lost."), E(.statement, 2, "{V}", "Paid $360 and could not activate the phone.")],
        defense: [E(.statement, 1, "Unaware", "{DL} says {D.he} did not know.")],
        role: "Buyer",
        exam: [.direct("Tell us about the phone you bought.", "\"A recent model, in good shape, advertised at a shop as a used phone for $360. I paid in cash and the seller gave me a receipt.\""), .direct("What happened when you tried to use the phone?", "\"The carrier refused to activate it. They told me it was locked and reported lost, so it could not be used.\""), .direct("What did you pay?", "\"$360 to {D} at a shop. I took the phone to the carrier the next day.\""), .direct("Did {D} refund you?", "\"No. I called {D} the day after the carrier refused, and I did not get my money back.\""), .direct("What happened when you tried to activate it?", "\"The carrier's system said the phone had been reported lost or stolen and was blocked. A representative said it was a permanent lock on that serial number.\""), .direct("What did you do?", "\"I went back to the shop the next day and asked for a refund. The seller said the shop didn't do refunds and told me to call later.\""), .cross("Did {D} tell you the phone was used?", "\"Yes, I knew it was used. What I did not know was that it was locked.\""), .cross("Did {D} offer any help after you called?", "\"I was told {D} might offer something. Nothing came of it.\""), .cross("Did you check the phone's status before you paid?", "\"No. I did not. I know that is on me too.\""), .cross("Did the seller tell you where the phone came from?", "\"Only that it was a trade-in. I didn't ask any more.\""), .cross("Did you check the phone's serial number against any database before buying?", "\"No. I should have, but I took the seller's word for it.\"")],
        theory: ("{D} sold a locked phone.", "An unaware seller."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} sold three such phones that month.", "{DL} bought them in a lot."),
        defendant: [.direct("Did you know the phone was locked?", "\"No. I bought it in a lot with others and did not check each one.\""), .direct("Did you offer {V} a refund?", "\"Yes. I offered one when {V.he} called me. I never refused.\""), .direct("Did you tell {V} the phone was locked?", "\"No. I did not know it was locked, so I could not have told {V.him}.\""), .direct("Please tell us about your shop.", "\"I buy and sell used phones. I take trade-ins, buy lots at auctions, and sell them at a markup.\""), .direct("How did you get this phone?", "\"In a lot of about twenty phones from an online auction. I tested each one for power and screen damage, but I couldn't check the lock status of every one.\""), .direct("What did you do when {V} came back?", "\"I told {V.him} I didn't know about the lock and offered a refund. We didn't agree on the terms, and then it went to deputies.\""), .cross("You sold three such phones that month, didn't you?", "\"Yes, from the same lot. I did not know any of them were locked.\""), .cross("A carrier notice says the phone was reported lost. Didn't that make you suspicious?", "\"I never saw that notice before. I assumed they were fine.\""), .cross("If you offered a refund, why hasn't {V} been paid?", "\"I am working on it. I did not have the money all at once.\""), .cross("You sold three phones from that lot that turned out to be locked. Didn't that make you suspicious?", "\"It did, after the third one. I stopped selling from the lot and offered refunds.\""), .cross("You didn't check the lock status before selling. Isn't that your job as a seller?", "\"It is, and I've changed how I do it. At the time I trusted the auction and didn't run the checks.\"")],
        openings: ("{V} paid {D} $360 for a used phone, and the carrier refused to activate it because it was locked and reported lost. {D} sold three phones like it that month and never refunded the money.", "Weigh the defense proof, which will show that {D} bought phones in a lot and did not know any were locked. {D} offered a refund and acted in good faith."),
        closings: ("A phone reported lost, locked by the carrier, sold for $360, and no refund. {D} sold three such phones in one month, and that is not an accident.", "{D} bought a lot of used phones and sold them without knowing the lock status. An honest mistake and an offer of a refund are not a crime."),
        timeline: [(-1, "The sale."), (0, "The carrier refuses to activate it."), (1, "{V} calls {D}.")],
        identified: "Carrier Notice",
        mood: .indifferent)

    static let towTruckOvercharge = SmallCases.make(
        key: "story.towTruckOvercharge",
        category: .whiteCollar,
        headlines: ["Tow Operator Charges Fees Not on Posted Rate Sheet"],
        law: "falsePretenses",
        spec: "Obtained $310 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} charged {V} $310 to release a towed car on {DATE}, including fees not on the posted rate sheet. {V} went to the tow lot to retrieve the car and paid on the spot. {V} paid $310 the day after the tow and read the posted rate sheet the same day.",
        state: [E(.document, 3, "Rate Sheet", "The posted total was $185."), E(.document, 2, "Receipt", "A $310 receipt for the release.")],
        defense: [E(.statement, 1, "Storage", "{DL} says storage fees were extra.")],
        role: "Car owner",
        exam: [.direct("Tell the jury how your car came to be towed.", "\"I parked at a shopping center for about an hour and came out to find an empty space. A sign on the pole said the lot was customers-only, and a tow company had taken the car.\""), .direct("What was the posted rate to release a towed car?", "\"$185. The rate sheet posted at the lot says $185 for the release, and that is what I expected to pay.\""), .direct("What did you actually pay?", "\"$310. I paid on the spot because I needed my car, and the receipt shows the total.\""), .direct("What did you do after paying?", "\"I read the posted rate sheet the same day, and saw that I had been charged well above it.\""), .direct("How did you get the car back?", "\"I called the number on the sign and got directions to a tow lot. I took a taxi there and the clerk said the fee to release it was $310, cash or card.\""), .direct("What did you notice at the lot?", "\"A rate sheet posted on the wall behind the counter. It listed a $185 release fee and said storage for the first day was included.\""), .cross("The tow lot included storage in the fees, didn't it?", "\"Storage was added. The sheet I saw listed storage as included, so I did not expect more.\""), .cross("Did you ask about the difference when you paid?", "\"I asked, but I was in a hurry. I paid and left.\""), .cross("Where was the rate sheet posted?", "\"Inside the office. I did not see it until after I paid.\""), .cross("Did you ask the clerk about the difference?", "\"I did. The clerk said the sheet was out of date and that storage was charged separately. I didn't have time to argue and paid.\""), .cross("Did the clerk give you a copy of the sheet or a receipt that itemized the charges?", "\"A receipt for $310 with a single line. No itemization and no copy of the sheet.\"")],
        theory: ("{D} overcharged.", "Storage fees."),
        allocution: "\"I'm sorry.\"",
        truths: ("The sheet listed storage as included.", "{DL} had no daily rate posted."),
        defendant: [.direct("Did you overcharge {V}?", "\"I charged for storage. It is a normal fee, and I add it when a car sits in the lot.\""), .direct("Was the rate sheet posted?", "\"Yes, inside the office. It is on the wall where customers can see it.\""), .direct("Was storage listed on the sheet?", "\"I thought it was. I believed storage was covered by the posted rates.\""), .direct("Tell the jury about your tow business.", "\"I run a tow lot and handle about forty cars a month. Most come from private lots with contracts, and customers pay a release fee to get their cars back.\""), .direct("How do you set your fees?", "\"A release fee plus a storage fee after the first night. I believed our rate sheet covered both, but I hadn't updated it in a while.\""), .direct("What did you tell {V} about the total?", "\"That the release fee was $185 and storage added $125. I didn't hide it, and I gave a receipt.\""), .cross("The sheet lists storage as included, doesn't it?", "\"I see that now. I did not read it that way when I charged.\""), .cross("No daily storage rate is posted, is there?", "\"No, there is not. I know that is a problem.\""), .cross("You took $310 for a $185 release. Isn't that overcharging?", "\"I charged what I thought was fair. I did not mean to cheat anyone.\""), .cross("The sheet lists storage as included. Why did you charge extra?", "\"I know that's what it says. It was out of date, and I should have corrected it.\""), .cross("No daily storage rate is posted. How is a customer supposed to know what to expect?", "\"They aren't, and I accept that. I've since posted a clear rate.\"")],
        openings: ("{V} paid $310 to release a towed car after seeing a posted rate of $185. The receipt includes storage fees that the posted sheet lists as included, and no daily rate is posted.", "Jurors will hear that {D} charged a normal storage fee and honestly believed it was covered. A billing dispute is not a crime."),
        closings: ("A posted rate of $185, a receipt for $310, and a sheet that lists storage as included. {V} paid more than the sign said, and the sign was {D}'s.", "{D} charged storage in the way tow lots do and believed it was allowed. The State has shown a pricing disagreement, not a plan to defraud."),
        timeline: [(0, "The car is towed."), (1, "{V} pays $310."), (1, "{V} reads the rate sheet.")],
        identified: "Rate Sheet",
        mood: .indifferent)

    static let stereoNoise = SmallCases.make(
        key: "story.stereoNoise",
        category: .publicOrder,
        headlines: ["Car Stereo Bass Shakes Apartment Windows at 2 A.M."],
        law: "disorderly",
        spec: "Disturbed the peace by making loud noise in a residential area at night, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Neighbors called deputies at 2 a.m. on {DATE} about bass from {D}'s parked car. {D} was warned twice.",
        state: [E(.statement, 3, "Deputy", "The bass was audible from 200 feet.")],
        defense: [E(.statement, 1, "Low", "{DL} says the volume was low.")],
        role: "Sheriff's deputy",
        exam: [.direct("Tell the jury how the call came in.", "\"At about two in the morning, dispatch sent me to an apartment complex parking lot for a noise complaint. Three residents had called about heavy bass.\""), .direct("What were you called to at 2 a.m.?", "\"Neighbors called about heavy bass coming from {D}'s parked car. I drove over and could hear it before I could even see the car.\""), .direct("How loud was it when you arrived?", "\"I could hear it clearly from about 200 feet away. At that hour, in a residential area, that is far louder than it should be.\""), .direct("What did you do about it?", "\"I spoke to {D} and asked for the volume to come down. I gave two warnings in all before I took further action.\""), .direct("What did you see and hear when you arrived?", "\"A parked sedan with the engine running and bass I could feel in my chest from about two hundred feet. Windows were lit in several units.\""), .direct("What did you say to {D} the first time?", "\"I introduced myself and told {D} to turn it down. {D} nodded and lowered the volume for about ten minutes.\""), .cross("Did {D} seem to understand your warnings?", "\"{D} seemed to be listening to the music more than to me. I cannot say how much {D} heard over it.\""), .cross("Was anyone harmed or threatened?", "\"No. Nobody was hurt and nobody was threatened. The complaint was purely about the noise.\""), .cross("Was the car parked legally?", "\"Yes. It was parked on the street and not blocking anything. The only problem was the sound.\""), .cross("Did you measure the volume with a meter?", "\"No. I didn't have a meter with me, and I based my report on how far I could hear it.\""), .cross("Did any resident tell you windows were rattling?", "\"Two residents said so. I confirmed it in one unit, where a window pane vibrated when the bass hit.\"")],
        theory: ("{D} blasted the stereo.", "A modest volume."),
        allocution: "\"I'm sorry.\"",
        truths: ("Windows rattled in three units.", "{DL} had been warned the week before."),
        defendant: [.direct("Was your music loud that night?", "\"Not very. I had the stereo on, but I did not think it was loud enough to bother anyone.\""), .direct("Did you hear the deputy's warnings?", "\"I did not hear them. The music was on and my windows were up. I only realized when the deputy knocked.\""), .direct("Why were you parked there at 2 a.m.?", "\"I was waiting for a friend to get off work. I sat in my car with the stereo on to pass the time.\""), .direct("Explain to the jury why you were in the parking lot.", "\"I was waiting for a friend who got off a late shift. I'd parked near the building with the stereo on low.\""), .direct("What did you hear when the deputy came to your window?", "\"I had the windows up and the music going, so I didn't hear the first warning. I only noticed when the deputy tapped on the glass.\""), .direct("What did you do after the second warning?", "\"I turned the stereo off and apologized. My friend came out a few minutes later, and we drove off.\""), .cross("Windows rattled in three apartments, didn't they?", "\"I did not know that. I did not think it was that loud.\""), .cross("You had been warned about noise the week before, hadn't you?", "\"I remember a conversation. I did not think of it as a formal warning.\""), .cross("You could have turned it down when you saw a deputy, couldn't you?", "\"I did once I realized. I know I should have caught on earlier.\""), .cross("Neighbors say the bass shook windows. Do you dispute that?", "\"I didn't think it was that loud. I couldn't hear what it sounded like outside my car.\""), .cross("You'd been warned about noise the week before. Why again?", "\"I thought I'd keep it low this time. I misjudged how much sound traveled.\"")],
        openings: ("At 2 a.m., neighbors called deputies about bass pounding from {D}'s parked car. A deputy could hear it from 200 feet away, and {D} had been warned twice.", "The defense evidence will establish that {D} was waiting for a friend with the stereo at a normal level and never heard the warnings through closed windows."),
        closings: ("Bass audible from 200 feet away at 2 a.m., windows rattling in three units, and two warnings that went unheeded. This was a disturbance.", "{D} did not hear the warnings through closed windows and did not know the music was loud. The State must prove a knowing disturbance, and it has not."),
        timeline: [(0, "1:40 a.m.: the bass."), (0, "2 a.m.: the first warning."), (0, "2:30 a.m.: the second warning.")],
        identified: "Deputy",
        mood: .indifferent)

    static let leafBlowerDawn = SmallCases.make(
        key: "story.leafBlowerDawn",
        category: .publicOrder,
        headlines: ["Landscaper Runs Leaf Blower at 5 A.M. After Complaints"],
        law: "disorderly",
        spec: "Disturbed the peace by making loud noise in a residential area before dawn, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} ran a leaf blower at 5 a.m. on {DATE} outside homes after repeated complaints. The houses on the street sit close together, and the blower could be heard from several yards. Neighbors called at 5:20 a.m. and a deputy arrived at 5:40 a.m.",
        state: [E(.statement, 3, "Deputy", "The blower was still running at 5:45 a.m."), E(.statement, 2, "Neighbor", "Four neighbors had called about the noise before.")],
        defense: [E(.statement, 1, "Early Job", "{DL} says {D.he} starts early before the heat.")],
        role: "Sheriff's deputy",
        exam: [.direct("Describe the street and what happened that morning in your own words.", "\"A residential street where the houses sit close together. At about 5:20 a.m. several neighbors called about a leaf blower running outside, and I got there at 5:40.\""), .direct("What time did you arrive at {D}'s street?", "\"At 5:40 a.m., after neighbors started calling about 5:20. The blower was still running when I got there at about 5:45.\""), .direct("Why had neighbors been complaining?", "\"Four neighbors had called about the noise before. The houses are close together, and the blower could be heard from several yards away.\""), .direct("Did {D} stop when asked?", "\"Only after I came over and spoke to {D}. Until then, it just kept running.\""), .direct("What did you see when you arrived?", "\"{D} was working in front of a house with a gas leaf blower, moving leaves toward the curb. The sound carried up and down the street.\""), .direct("What did you say to {D}?", "\"I introduced myself and explained that the ordinance didn't allow power equipment before eight. {D} turned the blower off after I spoke.\""), .cross("What does the county noise ordinance say about leaf blowers?", "\"As I understand it, the ordinance restricts noise early in the morning. I would have to check the exact hour for this kind of equipment.\""), .cross("Did {D} threaten anyone?", "\"No. {D} was working and did not threaten or argue with anyone.\""), .cross("Did you personally hand {D} a written warning?", "\"There was a written warning in the file, but I did not hand it over myself.\""), .cross("Did {D} argue with you or resist?", "\"No. {D} was polite and said {D.he} hadn't known the rule. {D} stopped as soon as I asked.\""), .cross("Was there a written warning on file for {D}?", "\"A notice from the county was mailed a few weeks earlier. I can't say whether {D} received it.\"")],
        theory: ("{D} ignored complaints.", "An early start."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had a written warning.", "The county ordinance starts at 8."),
        defendant: [.direct("Why were you running a leaf blower at 5 a.m.?", "\"It was a hot week, and I wanted to finish before the heat came up. I thought early would be better for everyone.\""), .direct("What time did you start?", "\"About five. I did not think about the neighbors still sleeping. I wanted to get an early start.\""), .direct("Had you seen any written warning?", "\"Not that I recall. If one was left at the house, I did not see it.\""), .direct("Tell us about your yard work.", "\"I do yard work for several homeowners on that street. It was a hot week and I wanted to start before the heat set in.\""), .direct("What time did you start, and were you aware of the ordinance?", "\"About five. I knew there were noise rules, but I thought they applied to construction and not to leaf blowers.\""), .direct("What did you do when the deputy spoke to you?", "\"I turned the blower off right away and apologized. I told the deputy I'd start after eight from then on.\""), .cross("Four neighbors had complained before, hadn't they?", "\"I did not know the number. I heard that some people were upset, but nobody said it to me.\""), .cross("You kept running it until a deputy came over, didn't you?", "\"I did not realize anyone was calling. When the deputy spoke to me, I stopped right away.\""), .cross("The county ordinance starts the allowed hours at 8, doesn't it?", "\"I did not know that. I should have looked it up.\""), .cross("Four neighbors had complained before. Did you know?", "\"I'd heard something. I didn't realize it was that many, and no one had come to me directly.\""), .cross("A county notice was mailed to you. Did you read it?", "\"I don't remember it. It may have gone into a pile of mail I didn't open.\"")],
        openings: ("At 5 a.m., {D} ran a leaf blower on a street where the houses sit close together. Four neighbors had complained before, and the blower was still running when a deputy arrived at 5:45.", "By the end of this trial, the proof will show that {D} started early because of the heat and never saw a written warning. {D} stopped the moment a deputy asked."),
        closings: ("A leaf blower at 5 a.m., four earlier complaints, a written warning, and an ordinance that starts at 8. {D} kept going until a deputy walked up.", "{D} wanted to beat the heat and did not know the rules. The State has not shown that {D} saw the warning or meant to disturb anyone."),
        timeline: [(0, "5 a.m.: the blower starts."), (0, "5:20 a.m.: neighbors call."), (0, "5:40 a.m.: a deputy arrives.")],
        identified: "Deputy",
        mood: .indifferent)

    static let cartParkingFight = SmallCases.make(
        key: "story.cartParkingFight",
        category: .violent,
        headlines: ["Shoppers Fight in Parking Lot After Cart Hits a Parked Car"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A shopping cart rolled into {V}'s parked car on {DATE}. {D} pushed {V} after an argument, and a bystander filmed it. The lot was crowded, and the cart rolled from a cart return toward {V}'s car. The argument followed, then the push, and a bystander recorded the push.",
        state: [E(.video, 3, "Bystander Video", "{D} pushes {V}."), E(.statement, 2, "Bystander", "Saw the push and recorded it.")],
        defense: [E(.statement, 1, "Self-Defense", "{DL} says {V} swung first.")],
        role: "Car owner",
        exam: [.direct("Tell us what happened in the parking lot.", "\"The lot was crowded. I came out of the store and saw a shopping cart sitting against my car door, with a fresh scratch where it had rolled.\""), .direct("What happened in the lot on {DATE}?", "\"A shopping cart rolled into my parked car from a cart return. The lot was crowded, and a person came up in the middle of it and we argued.\""), .direct("Who was the person you argued with?", "\"{D}. We argued about the cart and my car. The argument got heated.\""), .direct("What happened after that?", "\"{D} pushed me. A bystander saw it and recorded it. That's the video the jury will see.\""), .direct("What did you say to {D}?", "\"{D} was standing near the cart return. I asked whether the cart was {D.his} and {D} said it wasn't. I said someone should pay for the dent.\""), .direct("How did the argument end?", "\"{D} stepped toward me and shoved me with both hands. I stumbled back into my car door, and a bystander shouted and started filming.\""), .cross("{DL} says you swung first, doesn't {D.he}?", "\"I don't recall swinging. My hands were up while I pointed at the dent. The video will show what it shows.\""), .cross("Were you angry?", "\"Yes. I was upset about the dent and the cart. I raised my voice. I'm not going to pretend I was calm.\""), .cross("Were you seriously hurt?", "\"I wasn't badly hurt. I was shoved back and shaken up. It was the principle of it, and I was scared.\""), .cross("Did you raise your hands or swing at {D}?", "\"I raised my hands in front of me, palms out, to keep distance. I didn't swing.\""), .cross("How loud was the argument before the push?", "\"Both of us were raising our voices. I was angry about the dent and I said so.\"")],
        theory: ("{D} pushed a stranger.", "A response to a swing."),
        allocution: "\"I'm sorry.\"",
        truths: ("The video shows no swing.", "{V} stepped back."),
        defendant: [.direct("Why did you push {V}?", "\"{V} swung at me first. I pushed to get {V.him} away and protect myself. I didn't mean to hurt anyone.\""), .direct("How did the argument start?", "\"The cart rolled toward {V}'s car. I wasn't the one who pushed it. We argued about it, and it escalated.\""), .direct("How did you feel?", "\"Scared and angry. I'd never been in a fight like that. I only wanted it to stop.\""), .direct("Tell the jury how the argument started.", "\"The cart rolled from the cart return toward {V}'s car. {V} came over and accused me of letting it go.\""), .direct("What did {V} do before you pushed?", "\"{V} stepped right up to me, pointing and shouting, and I thought {V} swung. I put my hands out and pushed.\""), .direct("What did you do after the push?", "\"I stepped back and said I was sorry. I didn't want to fight, and I'd never been in a fight.\""), .cross("The video shows you pushing {V}, doesn't it?", "\"Yes, it shows a push. I'm not going to say it didn't happen. I reacted to a swing.\""), .cross("Can the video show {V} swinging?", "\"I don't know what's on the video. I know what I felt. I felt like I was about to be hit.\""), .cross("You could have walked away, couldn't you?", "\"Yes, I could have. I wish I had. I let myself get pulled in.\""), .cross("The video shows no swing from {V}. How do you explain that?", "\"It happened fast, and the angle may not show it. I thought {V} swung.\""), .cross("You could have walked away. Why push?", "\"I was scared, and it seemed like the only way to create space.\"")],
        openings: ("A shopping cart rolled into {V}'s parked car in a crowded lot. {D} argued with {V} and then pushed {V}, and a bystander recorded the push. The State will show the video and the bystander.", "The defense will point you to a person who says {V} swung first, a push made to get away, and a heated moment in a busy lot. {D} was defending {D.himself}."),
        closings: ("An argument over a dent, then a push, caught on a bystander's phone. {D} put hands on {V}, and the video shows it.", "Watch the video for the moment before the push. {V} was angry and close, and {D} reacted. The State has not proved the push wasn't self-defense."),
        timeline: [(0, "The cart rolls."), (0, "The argument."), (0, "The push.")],
        identified: "Bystander Video",
        mood: .indifferent)

    static let roadRageGesture = SmallCases.make(
        key: "story.roadRageGesture",
        category: .publicOrder,
        headlines: ["Driver Follows Motorist and Shouts Through Window at Stoplight"],
        law: "disorderly",
        spec: "Disturbed the peace by shouting at {V}, a motorist, in a public street, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} followed {V} for two miles on {DATE} and shouted through the window at a stoplight. The two drivers were on a main road with several traffic lights. The lane change came at about 4 p.m., the shouting at the stoplight eight minutes later, and {V} reported it at 4:15 p.m.",
        state: [E(.video, 3, "Dash Camera", "{D} shouts at the stoplight."), E(.statement, 2, "{V}", "Was followed for two miles and shouted at.")],
        defense: [E(.statement, 1, "Cut Off", "{DL} says {V} cut {D.him} off.")],
        role: "Motorist",
        exam: [.direct("Please describe your drive that afternoon.", "\"I was driving on the main road, a busy four-lane with several traffic lights. At about four I changed lanes to make a turn and a car behind me honked.\""), .direct("What happened on the road that afternoon?", "\"At about 4 p.m. I changed lanes, and {D} followed me for two miles on a main road before we stopped at a light.\""), .direct("Did {D} touch your car?", "\"No. {D} never touched my car or got out. It was the following and the shouting that upset me.\""), .direct("How long did {D} follow you?", "\"About two miles, right behind my bumper, through four lights. {D} stayed close the whole way.\""), .direct("What did {D} do at the stoplight?", "\"{D} pulled up next to me, rolled down the window, and shouted. I couldn't hear all of it, but it was loud and angry.\""), .direct("What did you do right after {D} drove off?", "\"I pulled over and wrote down the plate and the time. At 4:15 I called the sheriff's office to report what happened.\""), .cross("How long did the shouting last?", "\"Only the length of a light. A minute or so. But it came after a two-mile follow, so it felt longer.\""), .cross("You changed lanes in front of {D}, didn't you?", "\"I changed lanes, yes. I did not think I cut anyone off, but I may have been close.\""), .cross("Both of you were on the same road, weren't you?", "\"Yes, it is a main road with many lights. I understand that someone going the same way would be behind me.\""), .cross("Did {D} threaten you or say what {D.he} would do?", "\"I couldn't make out most of it. I felt threatened by the following and the shouting.\""), .cross("Did you change lanes in front of {D} suddenly?", "\"I signaled and moved over. I don't think it was sudden, but there was a car close behind.\"")],
        theory: ("{D} harassed a motorist.", "A cut-off."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} tailgated before the light.", "The dash camera shows no cut-off."),
