    static let borrowedBike = SmallCases.make(
        key: "story.borrowedBike",
        category: .property,
        headlines: ["Neighbor Borrows Mountain Bike and Sells It at Flea Market"],
        law: "misdLarceny",
        spec: "Stole a bicycle valued at $400 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} borrowed {V}'s mountain bike on {DATE} and sold it at a flea market for $90. A vendor kept the receipt. {V} lent the bike for a weekend ride and expected it back. {D} sold it at a flea market two days later, and {V} saw it for sale three days after that.",
        state: [E(.document, 3, "Vendor Receipt", "{D} sold the bike for $90."), E(.statement, 2, "{V}", "Lent the bike for a weekend ride.")],
        defense: [E(.statement, 1, "Gift", "{DL} says {V} gave {D.him} the bike.")],
        role: "Bike owner",
        exam: [.direct("What can you tell us about your bike and why you lent it?", "\"It's a mountain bike I bought for $800 and take care of. {D} asked to borrow it for a weekend ride, and I said yes.\""), .direct("What did you lend {DL} on {DATE}?", "\"My mountain bike, for a weekend ride. I lent it with the understanding that it would be returned afterward.\""), .direct("What happened to the bike?", "\"{D} sold it at a flea market two days later for $90. I saw it for sale there three days after that.\""), .direct("How do you know {DL} sold it?", "\"A vendor kept the receipt. It shows {D} sold the bike for $90, and that's how I traced it.\""), .direct("What did you expect to happen after the weekend?", "\"I expected the bike back on Monday. {D} never returned it, and when I called, {D} said something about a flea market.\""), .direct("How did you find the bike?", "\"I went to a flea market on Saturday and saw it on a vendor's table. My name was engraved on the frame, and the vendor showed me a receipt.\""), .cross("{DL} says you gave {D.him} the bike, doesn't {D.he}?", "\"I never gave it away. I lent it for a weekend and expected it back.\""), .cross("Did you put the loan in writing?", "\"No. It was a friendly loan. We didn't write anything down. I wouldn't have thought I needed to.\""), .cross("Could {DL} have misunderstood you?", "\"I don't see how. I said it was for the weekend. I'd never give away a bike worth far more than $90.\""), .cross("Did you ever tell {D} the bike was a gift?", "\"Never. I never gave it away, and I wouldn't have.\""), .cross("You lent {D} the bike for a weekend, correct, and that was all?", "\"Yes. I lent it for a weekend ride and expected it back Monday. I never said it was a gift, and I would not have given it away.\"")],
        theory: ("{D} sold a borrowed bike.", "A gift."),
        allocution: "\"I'm sorry.\"",
        truths: ("{V}'s name was engraved on the frame.", "No one witnessed a gift."),
        defendant: [.direct("How did you get the bike?", "\"{V} gave it to me. {V} said I could have it, and I took that as a gift. I wasn't borrowing it.\""), .direct("Why did you sell it?", "\"I needed money. I thought it was mine to sell, since {V} said I could have it. I didn't think I was doing anything wrong.\""), .direct("Why did you sell it for only $90?", "\"I took what I could get at the flea market. I wasn't trying to get the best price. I just needed the cash.\""), .direct("Tell us how you came to have the bike.", "\"{V} said I could have it. We'd been talking about my needing a ride and {V} offered it as a favor.\""), .direct("What did you do when {V} called?", "\"I told {V} I'd sold it and that I thought it was a gift. {V} was angry and said it was a loan.\""), .direct("What did you tell the flea market vendor about where the bike came from?", "\"I said it was mine to sell. I believed {V} had given it to me, and I never mentioned the engraved name on the frame.\""), .cross("{V} says it was a weekend loan, doesn't {V.he}?", "\"That's what {V} says. I understood it differently. I think there was a misunderstanding.\""), .cross("Nothing in writing shows a gift, does it?", "\"No. There was nothing in writing. It was a conversation. I know that makes it hard for the jury.\""), .cross("You sold it two days later, didn't you?", "\"Yes. I needed the money quickly. I didn't think about what it would mean to {V}.\""), .cross("The bike has {V}'s name engraved on the frame. How is that a gift?", "\"I didn't notice the engraving. I thought it was a nice bike and I didn't look closely.\""), .cross("Nothing in writing shows a gift. Why should anyone believe you?", "\"I understand that. It was a conversation, and I know that's not much.\"")],
