    static let fakeParkingTicket = SmallCases.make(
        key: "story.fakeParkingTicket",
        category: .whiteCollar,
        headlines: ["Man Prints Fake Parking Citations and Leaves Them on Windshields"],
        law: "forgery",
        spec: "Falsely made parking citations with intent to defraud, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} left printed parking citations with a payment address on windshields downtown on {DATE}. The downtown blocks have metered spaces and frequent enforcement. The forms were on windshields in the morning, officers collected them at noon, and two payments arrived five days later.",
        state: [E(.physical, 3, "Citations", "Printed forms with a P.O. box.", .search), E(.statement, 2, "Parking Enforcement Officer", "Collected forty forms at noon.")],
        defense: [E(.statement, 1, "Joke", "{DL} says it was a prank.")],
        role: "Parking enforcement officer",
        exam: [.direct("Describe your job and the downtown blocks for the jury.", "\"I'm a parking enforcement officer. The downtown blocks have metered spaces, and I walk them every day writing citations.\""), .direct("What did you find on downtown windshields on {DATE}?", "\"Printed parking citations with a payment address on them, left on windshields in the metered blocks. They were on the cars in the morning.\""), .direct("How many did you collect?", "\"Forty forms at about noon. I went block to block pulling them off windshields, and we kept them as evidence.\""), .direct("What happened afterward?", "\"Five days later, two payments came to the address on the forms. That's how we knew people had been fooled into paying.\""), .direct("How did the forms come to your attention?", "\"Merchants called about papers on windshields that looked like citations. I went block by block and collected forty of them.\""), .direct("What did the forms say?", "\"They looked like county citations, with a fine of $35 and a P.O. box for payment. The logo was close to ours but not exact.\""), .cross("Did the forms look official?", "\"They were printed to look like citations, with a payment address. They weren't ours, but a driver in a hurry might think so.\""), .cross("{DL} says it was a prank, doesn't {D.he}?", "\"A prank doesn't usually include a payment address, and two people did pay.\""), .cross("Did anyone lose a large amount?", "\"No. The two payments were small, like a normal parking fine. I don't have evidence of larger losses.\""), .cross("Did the forms carry a citation number or badge number?", "\"A number, but it wasn't in our system. A real citation has a number from our books, which these didn't.\""), .cross("Did anyone report losing money?", "\"Two people mailed $35 each before we put out a warning. I don't know of anyone else who paid.\"")],
        theory: ("{D} forged citations.", "A prank."),
        allocution: "\"I'm sorry.\"",
        truths: ("Two people mailed payments.", "The P.O. box was {DL}'s."),
        defendant: [.direct("Why did you put these forms on cars?", "\"It was a joke. I printed them as a prank, to see people's reactions. I never thought anyone would actually pay.\""), .direct("Did you want anyone's money?", "\"No. I never meant for anyone to send anything. I didn't check what happened afterward, and I never saw any payments.\""), .direct("What did you think the address was for?", "\"I put an address on them to make it look real. I didn't think anyone would use it, and I didn't watch it.\""), .direct("Tell us how you came up with the idea.", "\"I was in a class on graphic design, and the assignment was to make a realistic form. I printed some as a joke and put them on cars.\""), .direct("Why did you include a payment address?", "\"To make it look real. I used a P.O. box I already had, and I didn't think anyone would send money.\""), .direct("What did you do when you heard two people paid?", "\"I was shocked. I told a deputy I'd made them as a prank and offered to return the money.\""), .cross("Two people mailed payments, didn't they?", "\"I've heard that. I didn't know until the deputies told me. I'm sorry that happened.\""), .cross("You printed forty of these, didn't you?", "\"Yes, about that many. It was a lot of work for a joke. I didn't think about how it would affect people.\""), .cross("A fake citation with a payment address isn't a joke, is it?", "\"I see that now. At the time it seemed harmless. I should have thought more about it.\""), .cross("You put a payment address on forty forms. Didn't you expect someone to pay?", "\"Not really. I thought people would throw them away.\""), .cross("You cashed the two payments. Why?", "\"I didn't know they'd been sent until a deputy called, and I never cashed them. They were in the box.\"")],
        openings: ("Forty printed parking citations with a payment address appeared on downtown windshields, and two drivers mailed payments. The State will show the forms and the officer who collected them at noon.", "Jurors will also see a prank that got out of hand, a person who never meant anyone to pay, and no evidence {D} ever collected a dime."),
        closings: ("Forty fake citations on windshields, a payment address printed on each, and two drivers who paid. A prank that takes money from people is not harmless.", "A joke with a printer, and no sign {D} ever looked for payment or kept any. The State has not proved {D} meant to trick anyone out of money."),
        timeline: [(0, "Morning: forms on windshields."), (0, "Noon: officers collect them."), (5, "Two payments arrive.")],
        identified: "Citations",
        mood: .indifferent,
        genders: ["D": .male])

    static let schoolPermitForge = SmallCases.make(
        key: "story.schoolPermitForge",
        category: .whiteCollar,
        headlines: ["Student Forges Parent Signature on Parking Permit Application"],
        law: "forgery",
        spec: "Falsely made a parent's signature on a permit application with intent to defraud, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} signed a parent's name on a college parking permit application on {DATE}. The college requires a parent's signature on parking permits for dependent students. {D} signed the form, the clerk called the parent that day, and the parent denied it the next day.",
        state: [E(.document, 3, "Application", "The signature differs from the parent's."), E(.statement, 2, "Parent", "Did not sign the application.")],
        defense: [E(.statement, 1, "Permission", "{DL} says the parent allowed it.")],
        role: "College clerk",
        exam: [.direct("Please describe your job at the college.", "\"I'm a clerk in the parking office. I process permit applications for students, and I verify signatures when a parent is required to sign.\""), .direct("What did you notice about the parking permit application?", "\"The signature on the parent line did not match the parent's signature on file. It looked different in the letter shapes and the slant.\""), .direct("Why does the college require a parent's signature?", "\"For dependent students, we require a parent to sign the parking permit form. {D} is a dependent student, so the form had to carry it.\""), .direct("What did you do when you noticed the difference?", "\"I called the parent that same day. The parent told me the next day that the parent never signed the application.\""), .direct("What made you question this application?", "\"The signature on the parent line looked different from the one on file from last year. The letters were more rounded and the pressure was different.\""), .direct("What steps do you take when an application looks wrong?", "\"I compare the signature to the one on file and call the parent. In this case, I did both, and the parent said they never signed the form.\""), .cross("The parent could have approved it by text, couldn't they?", "\"That is possible. I was not shown any text, and the parent told me they did not sign.\""), .cross("Was the parent reachable when you first called?", "\"I did reach the parent that day. The parent was out of state, so I understand it would be hard to sign in person.\""), .cross("What was the permit worth?", "\"It is a parking permit, so not a large amount of money. But the signature requirement matters to us.\""), .cross("Did {D} try to avoid questions when you asked about it?", "\"No. {D} answered right away and said the parent had agreed by text.\""), .cross("How can you be sure the parent didn't sign it?", "\"The parent told me so by phone the next day and said they were out of state at the time.\"")],
        theory: ("{D} forged a signature.", "Permission."),
        allocution: "\"I'm sorry.\"",
        truths: ("The parent was out of state.", "A text said 'ok'."),
        defendant: [.direct("Did you sign your parent's name on the form?", "\"Yes, but I had permission. My parent was out of state and told me to go ahead and sign it for them.\""), .direct("How did you get that permission?", "\"By text. My parent wrote 'ok' when I asked if I could sign for them, because I could not get the form mailed in time.\""), .direct("Why not wait for your parent to sign?", "\"The permit deadline was coming up, and my parent was away. I did not think it was a big deal.\""), .direct("Tell us why you signed the form.", "\"The permit deadline was approaching and my parent was traveling. I texted and asked if I could sign, and my parent wrote 'ok'.\""), .direct("Do you still have the text?", "\"Yes, I showed it to the clerk. It says 'ok' in reply to my question, and my parent didn't object.\""), .direct("What did you think about the form?", "\"That I was doing what my parent had told me to. I wasn't trying to deceive anyone.\""), .cross("The parent told the clerk they never signed. Are they lying?", "\"I do not think so. I think they forgot about the text, or they did not know I signed the form itself.\""), .cross("'Ok' in a text is not the same as permission to sign a name, is it?", "\"I understood it as permission. I know now I should have asked for something clearer.\""), .cross("Can you show the jury that text?", "\"I have it on my phone. I can show it, but I understand it is short.\""), .cross("A one-word text isn't a signature. Why not wait until your parent could sign?", "\"I know I should have. I was worried about the deadline and I thought the text was enough.\""), .cross("The parent was out of state when you signed, wasn't the parent?", "\"Yes. The parent was traveling and I could not reach anyone by phone that day. I should have waited for a real signature.\"")],
        openings: ("A college requires a parent's signature on a parking permit for a dependent student. {D} signed the parent's name, the clerk saw it did not match, and the parent said the next day that no one asked.", "By the end of this trial, the proof will show that the parent was out of state and answered 'ok' by text when {D} asked about signing. {D} believed there was permission."),
        closings: ("The signature did not match, the parent never signed, and {D} signed anyway. A one-word text is not permission to write someone else's name.", "{D} asked, got 'ok,' and signed for a parent who was away. An honest belief in permission means there was no intent to defraud, and the State must prove otherwise."),
        timeline: [(0, "{DL} signs the form."), (0, "The clerk calls the parent."), (1, "The parent denies it.")],
        identified: "Application",
        mood: .indifferent)

    static let carBreakinGym = SmallCases.make(
        key: "story.carBreakinGym",
        category: .property,
        headlines: ["Truck Window Smashed Outside Gym, Duffel Bag Taken"],
