        spec: "Broke or entered a motor vehicle of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A truck window was smashed outside a gym on {DATE} and a duffel taken. A lot camera showed {D}. The truck was parked in the gym's open lot. {V} went inside at about 6 p.m., the window broke at 6:20 p.m., and {V} reported it the next day.",
        state: [E(.video, 3, "Lot Camera", "{D} smashes the window and takes a bag."), E(.document, 2, "Repair Estimate", "A new window for the truck.")],
        defense: [E(.statement, 1, "Found Bag", "{DL} says {D.he} found the bag.")],
        role: "Truck owner",
        exam: [.direct("Please tell us about your truck and where you parked.", "\"A pickup I use for work. I parked in the gym's open lot at about six and went inside for a workout.\""), .direct("What happened to your truck outside the gym on {DATE}?", "\"I parked in the gym's open lot and went in at about 6 p.m. At 6:20 my window was smashed and a duffel bag was taken.\""), .direct("What does the lot camera show?", "\"{D} smashing the window and taking the bag. It's a clear view, and the truck is right in the frame.\""), .direct("What was the cost to you?", "\"A new window for the truck. I have an estimate for the repair, and I lost what was in the duffel, which was personal.\""), .direct("What did you find when you came back out?", "\"The driver's window was shattered, glass was all over the seat, and a duffel bag I'd left behind the seat was gone. My gym clothes and a tablet were in it.\""), .direct("How did you learn who did it?", "\"The gym lets members see lot footage after an incident. It shows {D} walking up, breaking the window, and taking the bag.\""), .cross("Did you see {DL} take the bag?", "\"No. I was inside the gym. I only know what the camera shows and what I found after my workout.\""), .cross("When did you report it?", "\"The next day. I was shaken, and I wasn't sure what to do. I found out about the camera after I called.\""), .cross("{DL} says {D.he} found the bag, doesn't {D.he}?", "\"The camera shows the window being smashed, so I don't see how the bag was just lying around.\""), .cross("Did you see {D} near your truck before the break-in?", "\"No. I was inside the whole time. I've never met {D}.\""), .cross("Was the duffel ever returned?", "\"A deputy later recovered it from {D}, but a few items were missing.\"")],
        theory: ("{D} broke into a truck.", "A found bag."),
        allocution: "\"I'm sorry.\"",
        truths: ("Glass was on {DL}'s shoes.", "The bag had {V}'s tags."),
        defendant: [.direct("How did you end up with the bag?", "\"I found it. It was lying near a truck in the gym lot. I picked it up, thinking it was left behind.\""), .direct("Did you smash any window?", "\"No. I didn't break anything. I'd never break into a truck. I only picked up what I thought was abandoned.\""), .direct("What did you do with the bag?", "\"I took it with me. I looked through it to see whose it was. I know I should have turned it in.\""), .direct("Walk us through what you were doing at the gym that evening.", "\"I stopped by to use the weights. I parked in the same lot and I was there for about an hour.\""), .direct("Where did you find the bag?", "\"On the ground near a truck on the far side of the lot. It had a name tag on it, and I thought it had been dropped.\""), .direct("What did you do with it?", "\"I took it to my car to look for an ID so I could return it. I opened it, saw a tablet, and then I got nervous.\""), .cross("The video shows the window smashed, doesn't it?", "\"It shows something happening near the truck. I can't tell you what it is. I wasn't the one smashing anything.\""), .cross("You took a bag from a truck lot, didn't you?", "\"Yes, I took a bag. I thought it was abandoned. I know now that I should have left it.\""), .cross("You didn't report finding the bag, did you?", "\"No. I didn't. I thought about it but didn't. I made a bad decision.\""), .cross("The video shows a window being smashed. Is that you?", "\"It shows someone in my coat doing it, but I didn't break anything. I found the bag after that.\""), .cross("There was glass on your shoes. Why?", "\"The lot has broken glass in several places. I walked across it on my way to my car.\"")],
