    static let chaseOnBike = SmallCases.make(
        key: "story.chaseOnBike",
        category: .traffic,
        headlines: ["Cyclist Pedals Away From Deputy Who Ordered Him to Stop at Night"],
        law: "fleeing",
        spec: "Operated a bicycle on a street while fleeing a law enforcement officer, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A deputy ordered {D} to stop on a bicycle at night on {DATE}. {D} pedaled away through yards and was caught in an alley. The streets in that neighborhood have narrow alleys behind the houses. The order came at 10 p.m., the chase began two minutes later, and {D} was caught at 10:10 p.m.",
        state: [E(.video, 3, "Body Camera", "{D} pedals away after the order."), E(.statement, 2, "Deputy", "Called out for the cyclist to stop.")],
        defense: [E(.statement, 1, "No Light", "{DL} says {D.he} did not hear.")],
        role: "Sheriff's deputy",
        exam: [.direct("Describe what you were doing that night.", "\"I was on patrol in a neighborhood with narrow alleys behind the houses. At about ten, I saw a person on a bicycle with no front light.\""), .direct("What did you see on the street at 10 p.m. on {DATE}?", "\"A person on a bicycle at night in the neighborhood. I called out for the cyclist to stop, and the cyclist pedaled away.\""), .direct("What happened after that?", "\"The chase began about two minutes later. {D} went through yards and narrow alleys behind the houses until I caught {D} at about 10:10.\""), .direct("What does your body camera show?", "\"{D} pedaling away right after the order. You can hear me tell the cyclist to stop and you can see {D} keep going.\""), .direct("What did you say to the cyclist?", "\"I called out 'Sheriff's Office, stop' from my patrol car. The cyclist looked toward me and then pedaled faster into a yard.\""), .direct("How did the chase end?", "\"I followed on foot through three yards and into an alley. About eight minutes later, I found {D} behind a garage, out of breath.\""), .cross("{DL} says {D.he} did not hear you, doesn't {D.he}?", "\"I was close enough to be heard. I used a loud voice and had my lights on.\""), .cross("Was the bicycle lit?", "\"I don't recall a light on the bike. That's partly why I tried to stop the cyclist. It was dark.\""), .cross("Did {DL} resist when caught?", "\"No. {D} was out of breath and stopped when I got there in the alley. There was no fight.\""), .cross("How loud was your voice, and were your lights on?", "\"My lights were on and I called out clearly. The window was down, and the street was quiet.\""), .cross("Did {D} look back at you while pedaling away?", "\"Yes, twice, according to my camera. That tells me {D} was aware someone was behind, though I cannot say what {D} heard.\"")],
