        key: "story.bakerySkip",
        category: .property,
        headlines: ["Customer Fills Pastry Box and Leaves Through Back Door"],
        law: "larcenyMerchant",
        spec: "Took pastries valued at $64 from {V}, a bakery, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} filled a box with pastries worth $64 and left through the back door on {DATE}. {D} came in at 8 a.m. and was gone by 8:10 a.m. The baker checked the register at 8:15 a.m.",
        state: [E(.video, 3, "Bakery Camera", "{D} leaves with a full box."), E(.document, 2, "Register Tape", "No sale recorded for the morning's pastries.")],
        defense: [E(.statement, 1, "Paid", "{DL} says {D.he} paid at the front.")],
        role: "Baker",
        exam: [.direct("Describe your bakery and how a morning rush works for the jury.", "\"I own a small bakery. At eight in the morning we get a line of commuters, and the register is staffed by one person while I bake in the back.\""), .direct("What happened at your bakery on {DATE}?", "\"At about 8 a.m. {D} came in, filled a box with pastries worth $64, and left through the back door by 8:10.\""), .direct("How did you learn what had happened?", "\"I checked the register at 8:15 and there was no sale for those pastries. I then reviewed the bakery camera.\""), .direct("What does the bakery camera show?", "\"{D} leaves with a full box. It shows the box being filled and {D} walking out the back, not past the front counter.\""), .direct("What did {D} do at the bakery?", "\"{D} came in, filled a bakery box with pastries from the case, and walked toward the back hallway. I thought {D} was going to the restroom.\""), .direct("How did you discover the missing pastries?", "\"At 8:15 I checked the register and found no sale. I looked at the camera and saw {D} leaving through the back door.\""), .cross("{DL} says {D.he} paid at the front, doesn't {D.he}?", "\"The register tape shows no sale, so I don't see how a payment was rung up.\""), .cross("Were you at the front counter the whole time?", "\"No. I was in the back baking. A customer could have paid and I might not have seen it, but the register shows nothing.\""), .cross("Do you ever let customers pay later?", "\"Sometimes for regulars. {D} wasn't a regular I knew. I'd have remembered an arrangement like that.\""), .cross("Did {D} approach the counter?", "\"The camera shows {D} near the counter for a moment, but there was a line. I can't say whether {D} ordered.\""), .cross("Was the back door marked as an exit for customers?", "\"It's an emergency exit that leads to the parking lot. It isn't meant for regular use.\"")],
        theory: ("{D} took pastries.", "A paid order."),
        allocution: "\"I'm sorry.\"",
        truths: ("The register shows no sale.", "The box was empty on entry."),
        defendant: [.direct("What did you do at the bakery that morning?", "\"I picked out pastries, put them in a box, and I thought I paid at the front. Then I left out the back, the way people do.\""), .direct("Why did you leave through the back door?", "\"It was closer to where I parked. The door was open and other customers were using it. I didn't think anything of it.\""), .direct("Did you intend to take the pastries without paying?", "\"No. I believed I had paid. If I hadn't, it was a mistake. I would never walk out on a bakery like that.\""), .direct("Tell the jury about your morning at the bakery.", "\"I was on my way to work and stopped to pick up pastries for a meeting. I filled a box and waited in line to pay.\""), .direct("Did you intend to pay?", "\"Of course. I had cash in my wallet and I thought I'd already paid. I realized when a deputy called.\""), .direct("What did you do with the box after you left the bakery?", "\"I carried it to my car and took it to work for coworkers. When I got there I realized I had not paid, and I felt sick about it.\""), .cross("The register shows no sale, doesn't it?", "\"That's what the baker says. I remember paying, but I can't produce a receipt. I'd expected one to be handed over.\""), .cross("You walked right past the register, didn't you?", "\"I was in a hurry and the line was long. I thought a clerk had rung me up already.\""), .cross("$64 is a lot of pastries to carry out, isn't it?", "\"It was for a family event. I didn't count how much it came to. I trusted that it was handled.\""), .cross("The register shows no sale. How do you explain that?", "\"I don't know. Maybe I paid someone and they didn't ring it in, or maybe I forgot.\""), .cross("You didn't ask for a receipt. Why not?", "\"I never do. I thought the cashier took my money.\"")],
        openings: ("At 8 in the morning {D} filled a box with $64 in pastries and left through the back door by 8:10. The register shows no sale, and the bakery camera caught it. The State will show the video and the tape.", "Jurors will also see a customer who believed {D.he} had paid, left by the back door like others do, and had no reason to risk a theft over a box of pastries."),
        closings: ("A full box of pastries, a back door, and a register that shows no sale. The camera records every step of {D}'s exit.", "A busy morning, a long line, and a mix-up about payment. The State has not proved {D} meant to leave without paying."),
        timeline: [(0, "8 a.m.: {DL} enters."), (0, "8:10 a.m.: {DL} leaves."), (0, "8:15 a.m.: the baker checks.")],
        identified: "Bakery Camera",
        mood: .indifferent)

    static let liquorTheft = SmallCases.make(
        key: "story.liquorTheft",
        category: .property,
        headlines: ["Teen Steals Liquor Bottle From Convenience Store"],
        law: "larcenyMerchant",
        spec: "Took liquor valued at $38 from {V}, a convenience store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} put a bottle of liquor in a backpack and left a convenience store on {DATE}. The bottle was priced at $38. The clerk stopped {D} at the door after {D} walked out.",
        state: [E(.video, 3, "Store Camera", "{D} puts a bottle in a backpack."), E(.document, 2, "Price Tag", "A $38 price tag on the shelf where the bottle sat.")],
        defense: [E(.statement, 1, "Forgot", "{DL} says {D.he} forgot it.")],
        role: "Clerk",
        exam: [.direct("Please tell us about your store and the liquor shelf.", "\"It's a convenience store with a liquor shelf behind the counter and a few bottles on a shelf near the door. The bottle {D} took was a $38 bourbon.\""), .direct("What happened at the store?", "\"{D} put a $38 bottle of liquor in a backpack and walked out the door. I stopped {D} at the door after {D} left.\""), .direct("How did you see it?", "\"The store camera shows {D} putting the bottle in a backpack. I watched the footage right after.\""), .direct("What was the price of the bottle?", "\"$38. The price tag is on the shelf where the bottle sat.\""), .direct("What did the camera show?", "\"{D} picks up the bottle, tucks it into a backpack, and walks toward the door. {D} doesn't stop at the register.\""), .direct("What did you do?", "\"I followed {D} to the door and said I needed to see a receipt. {D} stopped, took off the backpack, and handed me the bottle.\""), .cross("Did {D} have an ID?", "\"No. {D} had no ID showing age, and I cannot say how old {D} is.\""), .cross("Did {D} try to run?", "\"No. {D} stopped when I called. {D} did not fight.\""), .cross("Was the bottle hidden?", "\"It was tucked into a backpack. I could not see it from the register.\""), .cross("Did {D} try to run or argue?", "\"No. {D} stopped immediately and was calm.\""), .cross("Did {D} have money on hand?", "\"I don't recall. I called the sheriff's office before I checked, and {D} was polite until deputies came.\"")],
        theory: ("{D} took liquor.", "A forgotten item."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had no ID of age.", "The bottle was tucked."),
        defendant: [.direct("Did you pay for the bottle?", "\"I forgot. I put it in my backpack to carry it, and I walked out without thinking.\""), .direct("Did you try to hide it?", "\"No. I put it in the backpack because it was easier to carry, not to hide it.\""), .direct("What did you do when the clerk stopped you?", "\"I stopped. I was embarrassed. I told the clerk I forgot to pay.\""), .direct("Walk us through what you were doing at the store.", "\"I stopped for a few things after work. I picked up the bottle for a friend's birthday and put it in my backpack while I got my phone.\""), .direct("Why did you walk toward the door?", "\"I'd forgotten the bottle was in my bag. I was looking at a text and I walked right past the register.\""), .direct("What happened when the clerk stopped you?", "\"I was embarrassed. I gave the bottle back and offered to pay, but the clerk had already called deputies.\""), .cross("You walked past the register with a bottle in your backpack, didn't you?", "\"I did. I was distracted, and I know how that looks.\""), .cross("You do not have an ID showing your age, do you?", "\"No. I did not bring it. I should not have been buying liquor.\""), .cross("Why put a bottle in a backpack instead of carrying it to the counter?", "\"I was holding other things, and it was easier.\""), .cross("You walked past the register with a bottle in your bag. Isn't that what theft looks like?", "\"It looks like that. I know it does, and I wish I'd paid first.\""), .cross("You didn't have ID showing your age. Does that matter?", "\"I'm over twenty-one, but I didn't have my ID with me. That's why I wasn't trying to buy it at the counter.\"")],
        openings: ("{D} put a $38 bottle of liquor in a backpack at a convenience store and walked out the door. The camera shows it, and the clerk stopped {D} at the door.", "The defense case is that {D} forgot to pay while carrying the bottle in a backpack and did not run when stopped."),
        closings: ("A bottle off the shelf, into a backpack, and out the door, all on camera. {D} had no ID and no receipt, and no excuse for passing the register.", "{D} forgot to pay and stopped when called. The State must prove {D} meant to take the bottle without paying, and forgetting is not the same."),
        timeline: [(0, "{DL} enters."), (0, "{DL} leaves."), (0, "The clerk stops {DL}.")],
        identified: "Store Camera",
        mood: .indifferent)

    static let cigarCaseSmash = SmallCases.make(
        key: "story.cigarCaseSmash",
        category: .property,
        headlines: ["Customer Smashes Smoke Shop Display Case After Refusal of Sale"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a smoke shop, causing damage of $540, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} smashed a glass display case at a smoke shop on {DATE} after the clerk refused to sell without ID. {D} asked to buy a pack at about 5 p.m., the clerk asked for ID, and the glass broke two minutes later. Deputies arrived at 5:10 p.m., and the case cost $540 to replace.",
        state: [E(.video, 3, "Shop Camera", "{D} smashes the case with a fist."), E(.document, 2, "Repair Invoice", "$540 to replace the glass display case.")],
        defense: [E(.statement, 1, "Accident", "{DL} says {D.he} slipped.")],
        role: "Clerk",
        exam: [.direct("Please tell us about your smoke shop and why you ask for ID.", "\"We sell tobacco and vaping supplies. State law requires us to ask for ID from anyone who looks under thirty and to refuse a sale without it.\""), .direct("What happened at your counter around 5 p.m. on {DATE}?", "\"{D} asked to buy a pack. I asked for ID, because that's the law. {D} became upset and the glass broke two minutes later.\""), .direct("What does the shop camera show?", "\"{D} smashes the display case with a fist. You can see the swing and the glass going, and then me calling for help.\""), .direct("What did it cost to fix?", "\"$540 to replace the glass display case. I have the repair invoice. Deputies arrived at 5:10.\""), .direct("What happened at the counter?", "\"{D} asked for a pack and I asked for ID. {D} said {D.he} had left it in the car, and I said I couldn't sell without it.\""), .direct("What did {D} do after the refusal?", "\"{D} swore, stepped back, and swung a fist at the glass display case. The glass shattered and fell onto the floor.\""), .cross("{DL} says {D.he} slipped, doesn't {D.he}?", "\"The video shows a fist hitting the glass. I can't see how a slip would look like that.\""), .cross("Was {DL} hurt?", "\"I think {D} cut a hand. I wasn't focused on that. I was trying to stay safe and call for help.\""), .cross("Did {DL} threaten you?", "\"No. {D} yelled, but I don't remember a threat. {D} was frustrated about the ID.\""), .cross("Did {D} threaten you or anyone else?", "\"No. {D} was angry and loud but never threatened or touched me.\""), .cross("Did {D} stay or run after the glass broke?", "\"{D} stayed in the shop. {D} said {D.he} was sorry and waited for deputies.\"")],
        theory: ("{D} smashed a case.", "A slip."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} swung twice.", "The glass broke outward."),
        defendant: [.direct("Why did you go into the smoke shop?", "\"I wanted a pack. The clerk asked for ID, and I didn't have it with me. I got frustrated about it.\""), .direct("What did you do after it broke?", "\"I stayed there. I told the clerk I was sorry and waited for the deputies. I didn't run.\""), .direct("Tell us why you went into the shop.", "\"I wanted a pack of cigarettes after a long day. I'd left my ID in my car and I told the clerk I'd go get it.\""), .direct("How did the glass break?", "\"I was turning to leave and my foot caught on something. I put my hand out and it hit the case. I didn't swing.\""), .direct("What did you do afterward?", "\"I stayed and apologized. I told the clerk I'd pay for it and waited for the deputies.\""), .direct("What did you say to the clerk before the glass broke?", "\"I said I was an adult and that I was tired of being treated like a kid. I was loud, and the clerk said again that the store needed ID.\""), .cross("The video shows a fist hitting the case, doesn't it?", "\"It looks like a fist, I'll admit. I was frustrated, and my hand came down. I didn't mean to smash it.\""), .cross("You were angry about the ID, weren't you?", "\"Yes. I was irritated. I didn't think the rule mattered. I understand it does.\""), .cross("$540 of damage is not a slip, is it?", "\"I know. I'm willing to pay. I wasn't trying to destroy anything, but I did cause it.\""), .cross("The video shows a fist hitting the glass. Isn't it clear you were angry?", "\"I was angry about the refusal. I didn't mean to break anything, and I don't remember swinging.\""), .cross("You were upset about being refused. Isn't breaking a display case an act of anger?", "\"It might look that way. I'm telling you I slipped, and I wish I'd just left.\"")],
        openings: ("{D} asked to buy a pack at a smoke shop, was asked for ID, and two minutes later smashed a glass display case. The shop camera captured it, and the repair cost $540.", "The defense will point you to a frustrated customer who lost balance, never threatened anyone, and stayed to answer for what happened. The State must prove an intentional smash."),
        closings: ("A refusal for no ID, a fist, and a broken case, all on camera. The $540 repair is the result of {D}'s anger.", "The video is brief and can be read two ways. {D} stayed, apologized, and had no reason to break the case on purpose. The State has not proved intent."),
        timeline: [(0, "5 p.m.: the refusal."), (0, "5:02 p.m.: the glass breaks."), (0, "5:10 p.m.: deputies arrive.")],
        identified: "Shop Camera",
        mood: .indifferent)

    static let atmHammer = SmallCases.make(
        key: "story.atmHammer",
        category: .property,
        headlines: ["Man Smashes ATM Screen With Hammer After Card Is Swallowed"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a bank, causing damage of $1,400, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} smashed an ATM screen with a hammer on {DATE} after the machine kept {D.his} card. The machine swallowed {D}'s card at 7 p.m., the hammer came five minutes later, and deputies arrived at 7:20 p.m. The screen cost $1,400 to replace.",
        state: [E(.video, 3, "Bank Camera", "{D} swings a hammer at the ATM."), E(.document, 2, "Repair Invoice", "$1,400 to replace the ATM screen.")],
        defense: [E(.statement, 1, "Frustration", "{DL} says {D.he} needed the card.")],
        role: "Bank manager",
        exam: [.direct("Please describe your bank and the ATM.", "\"I manage the branch. The ATM is in a vestibule off the lobby and is accessible after hours with a card. It records every transaction and a camera covers the screen.\""), .direct("What happened at your bank on {DATE}?", "\"At about 7 p.m. the ATM swallowed {D}'s card. About five minutes later, {D} swung a hammer at the machine's screen.\""), .direct("What does the bank camera show?", "\"{D} swings a hammer at the ATM. It shows the swing and the screen breaking, and a deputy arrived about 7:20.\""), .direct("What did it cost to repair?", "\"$1,400 to replace the ATM screen. The invoice is in evidence. The machine was out of service for days.\""), .direct("What happened that evening?", "\"At about 7 p.m. the machine kept {D}'s card because of a card read error. Five minutes later {D} came back with a hammer and swung it at the screen.\""), .direct("What was the damage?", "\"The screen shattered and the card reader was bent. The vendor charged $1,400 to replace the screen, and the machine was out of service for two days.\""), .cross("{DL} says {D.he} needed the card, doesn't {D.he}?", "\"Cards are retained when the machine has trouble reading them. We would have returned it the next business day.\""), .cross("Did {DL} threaten anyone?", "\"No. {D} was frustrated and loud, but didn't threaten any employee. The damage was to the machine only.\""), .cross("Was the bank open at that hour?", "\"The lobby was closed, but the ATM is outside and available. {D} could have called our number on the machine.\""), .cross("Did {D} threaten anyone or try to take cash?", "\"No. {D} only hit the screen and then stood there. Nothing was taken from the machine.\""), .cross("Was the bank open at the time?", "\"The lobby had closed at five, but a teller was inside doing the day's balancing. {D} could have knocked on the door.\"")],
        theory: ("{D} smashed an ATM.", "Frustration."),
        allocution: "\"I'm sorry.\"",
        truths: ("The hammer was brought in a bag.", "The bank was open."),
        defendant: [.direct("Why did you hit the ATM?", "\"The machine kept my card, and I needed it. I was frustrated and panicked. I lost my temper and swung the hammer.\""), .direct("Why did you need the card right then?", "\"It was the only way I could get my money for the weekend. I was out of cash, and I didn't know who to call.\""), .direct("How do you feel about it?", "\"I'm ashamed. It was a stupid reaction. I'd like to pay for the damage, and I never meant to hurt anyone.\""), .direct("Tell the jury why you needed the card that night.", "\"It was my only debit card, and my rent money was in the account. I had no other way to get cash.\""), .direct("What happened when the machine kept your card?", "\"It beeped and the screen said 'card retained.' I pushed buttons, called the number on the machine, and got a recording.\""), .direct("Why did you come back with a hammer?", "\"I was angry and desperate. I went to my car, got the hammer I keep in the trunk, and I swung at the machine without thinking.\""), .cross("You brought a hammer, didn't you?", "\"I had it with me. I don't remember why I took it out. I didn't plan to use it on the machine.\""), .cross("The ATM screen cost $1,400, didn't it?", "\"I know. That's a lot of money. I'm willing to work it off. I wasn't thinking about the cost.\""), .cross("You could have called the bank, couldn't you?", "\"Yes. I was panicking and didn't think of it. I should have called instead.\""), .cross("The bank was open for tellers. Why not knock on the door?", "\"I didn't see anyone inside. I was too upset to think.\""), .cross("You planned to hit the machine when you got the hammer. Isn't that premeditated?", "\"It wasn't planned. It was a bad moment that I regret.\"")],
        openings: ("An ATM swallowed {D}'s card at 7 p.m., and five minutes later {D} swung a hammer at the screen. The bank camera shows it, and the repair cost $1,400. The State will present the manager and the video.", "The defense will present a person who lost a card and lost control, owned up to it, and never threatened anyone. This was frustration, not a crime of malice."),
        closings: ("A swallowed card, a hammer, and a $1,400 screen. The camera shows the swing. Frustration does not give anyone the right to smash a machine.", "{D} panicked over a lost card and swung once at a machine. No one was threatened. The State has not proved the willful, malicious damage the law requires."),
        timeline: [(0, "7 p.m.: the card is swallowed."), (0, "7:05 p.m.: the hammer."), (0, "7:20 p.m.: deputies arrive.")],
        identified: "Bank Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let wrongWayRoad = SmallCases.make(
        key: "story.wrongWayRoad",
        category: .traffic,
        headlines: ["Driver Speeds the Wrong Way Down a One-Way Street Through Town Square"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} drove the wrong way at 40 mph down a one-way street in a town square on {DATE}, and pedestrians dove aside. {D} turned onto the street at 4 p.m. A deputy stopped {D} at 4:05 p.m.",
        state: [E(.video, 3, "Square Camera", "{D} drives the wrong way."), E(.document, 2, "Street Signs", "One-way signs posted at both ends of the street.")],
        defense: [E(.statement, 1, "Lost", "{DL} says {D.he} was lost.")],
        role: "Pedestrian",
        exam: [.direct("Tell the jury where you were and what you were doing.", "\"I was walking through the town square with my family on a Saturday afternoon. The square has a one-way street along one side with benches and a fountain.\""), .direct("What did you see in the town square?", "\"At 4 p.m., a car came down a one-way street the wrong way, directly at us. Pedestrians had to dive aside.\""), .direct("How fast was the car going?", "\"About 40 miles an hour. That is very fast for a town square with people crossing.\""), .direct("What signs were posted on that street?", "\"One-way signs at both ends of the street. They are clear, and they face the traffic.\""), .direct("What did you see?", "\"A silver car turned onto the one-way street in the wrong direction and kept coming. It didn't slow down.\""), .direct("How did you react?", "\"I grabbed my child's arm and pulled us onto the sidewalk. Other people dove out of the way, and a stroller was pushed aside.\""), .cross("Was the car speeding up or slowing down?", "\"It sped up after other drivers honked, as I remember. Then it stopped when a deputy pulled it over at 4:05.\""), .cross("Did the car strike anyone?", "\"No. Nobody was hit, but it was close.\""), .cross("Were you far from the street?", "\"I was on the sidewalk near the corner. I had a clear view.\""), .cross("Was the car going faster as it came toward you?", "\"It seemed to speed up after a driver honked at it. I can't say for certain.\""), .cross("Did anyone get hurt?", "\"Luckily not. One person fell and scraped a hand, but was fine.\"")],
        theory: ("{D} drove recklessly.", "A lost driver."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} sped up after being honked at.", "The signs were posted."),
        defendant: [.direct("Were you driving fast?", "\"Maybe faster than That is on me. I did not look at the speedometer.\""), .direct("Why were you on that street?", "\"I was looking for a different street in town. I did not know the layout well.\""), .direct("Tell the jury how you ended up on that street.", "\"I was visiting the town and looking for a parking garage. My phone's map was unclear and I turned where I thought it said.\""), .direct("Did you see the one-way signs?", "\"No. The sun was in my eyes and I was looking at my phone. I didn't see any signs until a deputy stopped me.\""), .direct("Why were you going 40?", "\"I wasn't paying attention to my speed. I wanted to get out of the square once I realized I was in the wrong place.\""), .direct("What did you do after you saw people dive out of the way?", "\"I stopped as soon as I realized where I was and backed off the street. I found a deputy to apologize, and I was shaking.\""), .cross("Signs at both ends, and you did not see either?", "\"I was distracted. I was looking for an address.\""), .cross("You sped up when others honked. Why?", "\"I panicked. I was trying to get out of the street.\""), .cross("Pedestrians had to dive out of the way. Doesn't that bother you?", "\"It does. I am glad no one was hurt, and I am so sorry.\""), .cross("There were signs at both ends of the street. How could you miss both?", "\"I was distracted and I was concentrating on the map. I know it sounds bad.\""), .cross("People had to jump out of the way. Didn't you see them?", "\"Not until the last second. I felt sick afterward.\"")],
        openings: ("At 4 p.m., {D} turned onto a one-way street in a town square and drove the wrong way at about 40 miles an hour. Pedestrians dove aside, and a deputy stopped {D} five minutes later.", "The defense evidence will establish that {D} was lost, looking for another street, and never saw the signs. {D} panicked when others honked."),
        closings: ("One-way signs at both ends, a car doing 40 the wrong way, and pedestrians diving for safety. The camera records it all.", "{D} was lost and did not see the signs. The State must prove {D} drove recklessly with knowledge of the danger, and being lost does not prove that."),
        timeline: [(0, "4 p.m.: the turn."), (0, "4:01 p.m.: the wrong way."), (0, "4:05 p.m.: a deputy stops {DL}.")],
        identified: "Square Camera",
        mood: .indifferent)

