        state: [E(.video, 3, "Lobby Camera", "{D} sleeps in a chair."), E(.statement, 2, "Hotel Clerk", "Gave two orders to leave, at 2 a.m. and 5 a.m.")],
        defense: [E(.statement, 1, "Waiting", "{DL} says {D.he} was waiting for a ride.")],
        role: "Hotel clerk",
        exam: [.direct("Please describe your job at the hotel overnight.", "\"I'm the night clerk. I'm the only front desk employee on shift from eleven to seven, and I watch the lobby from behind the counter.\""), .direct("What did you see in the lobby of your hotel on {DATE}?", "\"{D} sat in a lobby chair at about 1 a.m. and fell asleep. I thought {D} might be waiting for someone.\""), .direct("What orders did you give {DL}?", "\"The first order to leave was at 2 a.m., and the second at 5 a.m. {D} stayed in the chair after both.\""), .direct("How long did {DL} stay?", "\"About four hours in all. The lobby camera shows {D} sleeping in the chair the whole time.\""), .direct("What happened at about one in the morning?", "\"A person came in, sat in a chair near the window, and stayed there. I assumed it was a guest waiting for a ride.\""), .direct("What did you do at two?", "\"I walked over and asked if {D} was a guest. {D} said no and that {D.he} was waiting for a ride, and I told {D} that the lobby was for guests only and {D.he} needed to leave.\""), .cross("{DL} says {D.he} was waiting for a ride, doesn't {D.he}?", "\"A ride for four hours seems long. I didn't see anyone come for {D}.\""), .cross("Did {DL} cause any trouble?", "\"No. {D} slept quietly. There was no disturbance, and nothing was damaged or taken.\""), .cross("Did you call deputies right away?", "\"No. I gave the orders first and gave {D} time. I called later when {D} still didn't leave.\""), .cross("Was {D} disruptive?", "\"No. {D} was asleep for most of the night, and didn't bother any guests.\""), .cross("Did you offer to call a ride or a taxi?", "\"No. I was busy with the desk, and I wasn't sure what else to do.\"")],
        theory: ("{D} trespassed.", "Waiting for a ride."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had no key.", "The ride never came."),
        defendant: [.direct("Why were you in the hotel lobby?", "\"I was waiting for a ride. I sat down to wait and I was tired, so I fell asleep. I wasn't there to cause trouble.\""), .direct("Did you hear the clerk ask you to leave?", "\"I remember being asked once or twice. I was groggy and thought I could wait a bit longer. I told the clerk my ride was coming.\""), .direct("Why didn't you leave?", "\"I had nowhere else to go, and I thought the ride was on its way. I didn't want to be outside in the middle of the night.\""), .direct("Explain to the jury why you were at the hotel at that hour.", "\"I was waiting for a ride home after a late shift. My ride had said it would be there in half an hour.\""), .direct("What happened while you waited?", "\"I sat down and fell asleep. I woke when the clerk asked me to leave, and I said I was waiting for a ride.\""), .direct("Why did you stay after the first request?", "\"I couldn't call the ride because my phone had died. I thought the clerk would let me wait a little longer.\""), .cross("You were told to leave twice, weren't you?", "\"Yes, at 2 and at 5. I stayed because I was waiting. I should have gone outside.\""), .cross("You weren't a guest at the hotel, were you?", "\"No. I wasn't. I know I had no right to be there for four hours.\""), .cross("Four hours is a long wait for a ride, isn't it?", "\"It is. The person said they were coming. I kept waiting and fell asleep.\""), .cross("You were told twice to leave and stayed. Isn't that trespassing?", "\"I understand that. I had nowhere to go, and I didn't want to wake anyone.\""), .cross("Your ride never came. Why didn't you leave and find another way?", "\"I fell asleep again. I wasn't thinking clearly, and it was a bad night.\"")],
        openings: ("At 1 a.m. {D} sat down in a hotel lobby chair and stayed about four hours, ignoring two orders to leave from the clerk. The lobby camera shows it. The State will present the clerk and the video.", "The defense evidence includes a person waiting for a ride, asleep in a chair, who caused no disturbance and who had nowhere to go in the middle of the night."),
