        defense: [E(.statement, 1, "Thought Over", "{DL} says {D.he} thought the ban ended.")],
        role: "Bar owner",
        exam: [.direct("Please describe your bar and why you banned {D}.", "\"I own a neighborhood bar. About a month before, {D} had been involved in a loud dispute with another patron, and I gave {D} a written ban for ninety days.\""), .direct("What did you do about {DL} before {DATE}?", "\"A month earlier I banned {D} in writing. I handed over a ban letter, and I kept a copy with the date.\""), .direct("What happened on {DATE}?", "\"{D} came in at 9 p.m. I recognized {D} right away and asked {D.him} to leave. Deputies arrived about twenty minutes later.\""), .direct("Why was {DL} banned?", "\"I'd rather not go into every detail. {D} had caused trouble in the bar before, and I decided I didn't want {D} there anymore.\""), .direct("What did the ban letter say?", "\"That {D} was not permitted on the premises for ninety days and that entry would be treated as trespassing. {D} signed it in front of me.\""), .direct("What happened when {D} returned?", "\"At about nine, {D} came in, sat at the same stool, and ordered a drink. I recognized {D}, told {D.him} the ban hadn't expired, and asked {D.him} to leave.\""), .cross("{DL} says {D.he} thought the ban ended, doesn't {D.he}?", "\"The letter has no end date. I never told {D} the ban was over.\""), .cross("Did {DL} cause trouble that night?", "\"Not that I saw. {D} came in and sat down. I told {D} to go, and {D} didn't leave right away.\""), .cross("Did {DL} try to hide?", "\"No. {D} walked in and sat in plain view. {D} wasn't sneaking.\""), .cross("Did {D} argue or refuse at first?", "\"{D} said the ban was a month and was over. {D} didn't move until I said I'd call deputies.\""), .cross("Was {D} causing any trouble that night?", "\"No. {D} was quiet. The only issue was that {D} was banned.\"")],
        theory: ("{D} returned during a ban.", "A misread date."),
        allocution: "\"I'm sorry.\"",
