    static let burnoutLot = SmallCases.make(
        key: "story.burnoutLot",
        category: .traffic,
        headlines: ["Driver Does Burnouts in Church Parking Lot After Sunday Service"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} did burnouts in a church lot as families left on {DATE}, nearly striking a stroller. The service ended at noon, the burnouts began ten minutes later, and deputies arrived at 12:20 p.m. The lot is the church's main parking lot.",
        state: [E(.video, 3, "Church Camera", "{D}'s car spins close to families."), E(.statement, 2, "Church Usher", "Families were crossing the lot when the car spun.")],
        defense: [E(.statement, 1, "Empty Lot", "{DL} says the lot looked empty.")],
        role: "Church usher",
        exam: [.direct("Tell us about your role at the church and the parking lot.", "\"I'm an usher. After services I stand near the door and help families to their cars, and the main lot is right in front of the church.\""), .direct("What did you see in the church lot on {DATE}?", "\"The service ended at noon. About ten minutes later, {D}'s car began spinning in a burnout in our main lot while families were leaving.\""), .direct("What did your church camera record?", "\"{D}'s car spinning close to families. A deputy arrived at 12:20 and spoke to {D}.\""), .direct("What did you see at about ten past noon?", "\"A black coupe came into the lot and started spinning in circles near the middle. The tires screamed and smoke covered part of the lot.\""), .direct("How close did the car come to people?", "\"Within about ten feet of a parent pushing a stroller. The parent had to run, and a few other people jumped aside.\""), .direct("What did you do when you saw the car spinning near the families?", "\"I ran into the lot and waved my arms. I told people to get back on the sidewalk, and I grabbed a child's hand as the car came close.\""), .cross("{DL} says the lot looked empty, doesn't {D.he}?", "\"The lot is large, and people were still coming out of the church. It wasn't empty.\""), .cross("Did anyone get hurt?", "\"No. Thank God. The stroller was nearly hit, but nobody was struck. It was close, and everyone was shaken.\""), .cross("Was {DL} still there when the deputy arrived?", "\"Yes. {D} stayed in the lot and talked to the deputy. {D} didn't try to leave.\""), .cross("Was the lot crowded?", "\"Not as crowded as when the service let out. By then, many families had gone, but a good number were still walking to their cars.\""), .cross("Did the driver stop when people shouted?", "\"The car stopped after a minute and the driver got out. {D} said {D.he} thought the lot was empty.\"")],
        theory: ("{D} drove recklessly.", "A mistaken empty lot."),
        allocution: "\"I'm sorry.\"",
        truths: ("People were outside.", "{DL} circled twice."),
        defendant: [.direct("Why were you in the church lot?", "\"I was pulling in after the service ended. I wanted to try a burnout in an open lot, and it looked like a good spot.\""), .direct("Did you see people in the lot?", "\"I thought it was clear. I didn't see anyone near me. I'd never do that if I thought someone was close.\""), .direct("How did you feel when you learned about the stroller?", "\"I felt sick. I'd never want to hurt a child. I'm ashamed, and I'm sorry to those families.\""), .direct("Tell us what you were doing at the church.", "\"I was dropping off a donation at the office. I was driving through the lot on my way out and thought it was empty.\""), .direct("Why did you spin the car?", "\"It was a stupid impulse. The lot was open and I wanted to see what the tires would do.\""), .direct("What did you do when you saw people?", "\"I stopped as soon as I saw them, got out, and apologized to a family. I felt terrible.\""), .cross("The service had just ended, hadn't it?", "\"I didn't know that. I came when I thought it was done. I should have looked more carefully.\""), .cross("You did burnouts in a church parking lot, didn't you?", "\"Yes. That was a stupid thing to do. I thought of it as a joke, and I didn't think about who might be there.\""), .cross("Families were crossing the lot, weren't they?", "\"So I've been told. I didn't see them. If I had, I would have stopped.\""), .cross("The service had just ended at noon. Wasn't it obvious people would be there?", "\"I thought it was over. I didn't see anyone until I'd started spinning.\""), .cross("The camera shows you circling twice. Isn't that a deliberate act?", "\"It was deliberate in that I did it on purpose, but I didn't see people. I'm so sorry.\"")],
        openings: ("After a church service ended at noon, {D} did burnouts in the main parking lot as families crossed it, nearly striking a stroller. The church camera shows it. The State will present the usher and the video.", "The defense will present a driver who thought the lot was empty, never saw the families, and stopped when the deputy came. {D} made a foolish mistake, not a deliberate threat."),
        closings: ("Families leaving church, a car spinning in the lot, and a stroller nearly struck. {D} drove recklessly where people gather, and the camera shows how close it came.", "{D} believed the lot was empty. Nobody was hit, and {D} stayed and answered to the deputy. The State has not proved a willful disregard for safety."),
        timeline: [(0, "12 p.m.: the service ends."), (0, "12:10 p.m.: the burnouts."), (0, "12:20 p.m.: deputies arrive.")],
        identified: "Church Camera",
        mood: .indifferent)

