        defense: [E(.statement, 1, "Provoked", "{DL} says {V} sprayed first.")],
        role: "Neighbor",
        exam: [.direct("Tell us about your street and the mail route.", "\"I live on a quiet street where the mailboxes are lined up at the curb. I walk down to check mine around two every afternoon.\""), .direct("What did {D} do?", "\"Five minutes later, {D} pushed me, and I landed in the hedge. It happened fast, and I had my back to it.\""), .direct("Who saw it?", "\"A neighbor saw the push into the hedge and took video. Deputies arrived at about 2:20.\""), .direct("What happened with the sprinkler?", "\"A sprinkler in {D}'s yard had been spraying the sidewalk and the mail route for about an hour. I walked through it on my way to the mailbox and got wet.\""), .direct("What happened when you spoke to {D}?", "\"I said the sprinkler was soaking the mail route and asked {D} to move it. {D} said it was my problem and came toward me.\""), .direct("What did you do right after you landed in the hedge?", "\"I got up, called for deputies, and showed them the scratches and the wet mail. I also got a neighbor's video that showed the push.\""), .cross("The sprinkler soaked {D}, didn't it?", "\"It got {D} a little wet. I do not deny that.\""), .cross("Was the hose in {D}'s hand?", "\"I think {D} had the hose at one point. I did not see exactly who held what.\""), .cross("Did you step back before the push?", "\"I stepped back when {D} came at me. I may have moved when {D} did.\""), .cross("Did you spray {D} with a hose?", "\"No. I didn't have a hose. I may have gestured at the sprinkler, but I never sprayed anyone.\""), .cross("Were you angry when you spoke?", "\"Yes. I was irritated about the water and I raised my voice.\"")],
        theory: ("{D} pushed a neighbor.", "A provoked push."),
        allocution: "\"I'm sorry.\"",
        truths: ("The hose was in {DL}'s hand.", "{V} stepped back."),
        defendant: [.direct("Did you push {V}?", "\"Once. I pushed {V.him} after we argued about the sprinkler soaking everything.\""), .direct("Why did you push?", "\"I was sprayed, and I lost my temper.\""), .direct("Were you soaked?", "\"A little. My clothes were wet, and I was angry.\""), .direct("Describe the sprinkler and why it was on in your own words.", "\"I was watering a patch of new grass. I'd set the sprinkler that morning and forgot to move it.\""), .direct("What did you think when your neighbor yelled at you?", "\"I was surprised and annoyed. I'd been working in the yard all day and I was tired.\""), .direct("What happened next?", "\"We argued and I stepped toward my neighbor. I pushed once and my neighbor stumbled back into the hedge.\""), .cross("{V} landed in a hedge. Isn't that more than a shove?", "\"It was a push, and {V.he} stepped back into the hedge. I did not mean for it to go that way.\""), .cross("A neighbor filmed you, didn't they?", "\"Yes. I know what it shows. I regret it deeply.\""), .cross("You were holding the hose, weren't you?", "\"At one point, yes. I was turning it away from my house.\""), .cross("Your neighbor landed in a hedge. Isn't that more than a shove?", "\"It was one push, and I didn't mean for it to be hard. I am truly sorry.\""), .cross("You could have walked away. Why push?", "\"I was angry. I should have turned around.\"")],
        openings: ("A sprinkler soaked the neighborhood mail route at 2 p.m., and five minutes later {D} pushed {V} into a hedge in front of a neighbor who recorded it on video.", "Jurors will hear that {D} was soaked while arguing with {V}, lost a temper once, and pushed once, with no plan to hurt anyone and no injury beyond some scratches."),
        closings: ("A neighbor's video shows {D} pushing {V} into a hedge. A wet sleeve does not give anyone the right to put hands on another person.", "{D} pushed once in an angry moment, after being soaked. {V} was not hurt. The law treats a single shove very differently from a serious assault."),
        timeline: [(0, "2 p.m.: the sprinkler."), (0, "2:05 p.m.: the push."), (0, "2:20 p.m.: deputies arrive.")],
