    static let bikeLaneShove = SmallCases.make(
        key: "story.bikeLaneShove",
        category: .violent,
        headlines: ["Cyclist Shoves Jogger on Greenway After Near Collision"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A cyclist, {D}, shoved {V}, a jogger, on a greenway after a near collision on {DATE}. The greenway has a marked bike lane beside the walking path. The near miss came at 7 a.m., the shove a moment later, and {V} called deputies at 7:20 a.m.",
        state: [E(.video, 3, "Trail Camera", "{D} shoves {V}."), E(.document, 2, "Scrape", "A scrape on {V} from the fall.")],
        defense: [E(.statement, 1, "Cut Off", "{DL} says {V} stepped into the bike lane.")],
        role: "Jogger",
        exam: [.direct("Please tell us about your morning run.", "\"I run the greenway three mornings a week. There's a marked bike lane on one side and a walking path on the other, with a painted line between them.\""), .direct("What happened on the greenway at 7 a.m. on {DATE}?", "\"I was jogging when a cyclist, {D}, came close in a near collision. A moment later, {D} shoved me.\""), .direct("What happened when you were shoved?", "\"I fell and scraped myself on the pavement. The trail camera recorded the shove, and I have the scrape documented.\""), .direct("What did you do afterward?", "\"I called deputies at 7:20. I wanted it on record. The shove wasn't an accident, and I still felt it a day later.\""), .direct("What happened right before the shove?", "\"A cyclist came up fast behind me and swerved around me, so close I could feel the bike pass. I stumbled and turned around and said something.\""), .direct("What did {D} do next?", "\"{D} stopped, got off the bike, and walked back toward me. Then {D} put a hand on my shoulder and pushed me down onto the pavement.\""), .cross("{DL} says you stepped into the bike lane, doesn't {D.he}?", "\"I was keeping to the path as best I recall. I can't swear exactly where my feet were.\""), .cross("Was there a near collision before the shove?", "\"Yes. We came close. It startled both of us, and we exchanged words. Then {D} pushed me.\""), .cross("Were you seriously injured?", "\"No, just a scrape and some soreness. But the shove could have been much worse, and I was shaken.\""), .cross("Were you running in the bike lane?", "\"I was on the path, near the line. I may have drifted a little to avoid a puddle.\""), .cross("Did you shout at {D}?", "\"I said something sharp like 'watch it.' I didn't threaten {D.him}.\"")],
        theory: ("{D} shoved a jogger.", "A bike-lane dispute."),
        allocution: "\"I'm sorry.\"",
        truths: ("{V} was in the jogger's lane.", "{DL} braked."),
        defendant: [.direct("What happened on the greenway?", "\"A jogger stepped into the bike lane right in front of me. I braked hard, and we nearly collided.\""), .direct("Why did you push the jogger?", "\"I was scared and angry. I put my hand out to get the jogger away from my bike, and it turned into a shove.\""), .direct("Did you mean to hurt the jogger?", "\"No. I reacted. I didn't think the jogger would fall. I'm sorry that happened.\""), .direct("Please describe your ride that morning.", "\"I ride the greenway to work. I was on my usual route at about seven when a jogger stepped into the bike lane in front of me.\""), .direct("What did you do to avoid a collision?", "\"I braked hard and swerved. My wheel skidded and I nearly went down.\""), .direct("What happened after you stopped?", "\"I was shaking and angry. I put my hand out to push the jogger away and the jogger fell.\""), .cross("The trail camera shows you shoving {V}, doesn't it?", "\"Yes, it shows a push. I should have talked instead.\""), .cross("The jogger was left with a scrape, wasn't {V.he}?", "\"I understand so. I didn't mean that. I feel bad about it.\""), .cross("You could have ridden on, couldn't you?", "\"Yes. I wish I had. I was shaken and let it get the better of me.\""), .cross("The trail camera shows you getting off the bike and walking back. Why?", "\"I wanted to say something about the near miss. I wasn't planning to push anyone.\""), .cross("Doesn't that show you were angry enough to push?", "\"I was angry and I acted on it. I regret it.\"")],
        openings: ("A cyclist and a jogger nearly collided on a greenway at 7 a.m. A moment later, {D} shoved {V}, and the trail camera recorded it. {V} was scraped in the fall. The State will show the video and the scrape.", "Jurors will also see a cyclist startled by a jogger stepping into the bike lane, a reflex shove after a near collision, and no intent to injure."),
        closings: ("A near miss, then a shove, and {V} on the pavement with a scrape. The trail camera shows {D} choosing to push.", "A bike lane, a near collision, and a reflex. {D} did not mean to hurt {V}. The State has not proved an intentional assault."),
        timeline: [(0, "7 a.m.: the near miss."), (0, "7:01 a.m.: the shove."), (0, "7:20 a.m.: {V} calls deputies.")],
