        mood: .indifferent)

    static let fakeCashMarket = SmallCases.make(
        key: "story.fakeCashMarket",
        category: .whiteCollar,
        headlines: ["Man Passes Counterfeit Bills at Three Flea Market Stalls"],
        law: "uttering",
        spec: "Offered counterfeit currency to {V}, a vendor, knowing it to be forged, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} passed counterfeit twenties at three flea market stalls on {DATE}. A vendor's pen marked them. The flea market stalls line a gravel lane, and vendors test bills with a pen. {D} passed the first bill at 10 a.m. and the third at 10:30 a.m., and security stopped {D} at 11 a.m.",
        state: [E(.physical, 3, "Bills", "Three counterfeit twenties.", .search), E(.physical, 2, "Marker Test", "A vendor's pen marked three bills black.")],
        defense: [E(.statement, 1, "Change", "{DL} says {D.he} got them as change.")],
        role: "Vendor",
        exam: [.direct("Describe your stall and how you check bills for the jury.", "\"I sell used tools at the flea market. We take mostly cash, and I check twenties with a counterfeit detection pen.\""), .direct("How did you spot a bad bill at your stall on {DATE}?", "\"A customer handed me a twenty, and I ran a vendor's pen across it. It marked black, which means counterfeit.\""), .direct("How did this connect to {DL}?", "\"Three vendors found counterfeit twenties. {D} passed the first at 10 a.m. and the third at 10:30, and security stopped {D} at 11.\""), .direct("What happened with the bills?", "\"Three counterfeit twenties were seized from the stalls. A vendor's pen marked all three black.\""), .direct("What happened when {D} came to your stall?", "\"{D} bought a small tool for $5 and handed me a twenty. I marked it with the pen and the ink turned black.\""), .direct("What did you do?", "\"I told the vendor next to me, and word spread. Two other vendors had already taken twenties from the same person.\""), .cross("{DL} says {D.he} got them as change, doesn't {D.he}?", "\"It's possible a customer got them somewhere else. I can't say where {D} got them.\""), .cross("Did {DL} act suspicious?", "\"No. {D} was friendly and handed over the bills like anyone else. I didn't think anything of it.\""), .cross("Did the pen test all bills as counterfeit?", "\"The three I saw. A pen isn't perfect, but all three marked black, which was enough to concern me.\""), .cross("Did {D} seem to know the bill was fake?", "\"No. {D} seemed surprised and said it came as change from somewhere.\""), .cross("Did you see {D} pass any other bills?", "\"Only mine. The other two vendors told me about theirs.\"")],
        theory: ("{D} passed counterfeit bills.", "Bills received as change."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had five more in a wallet.", "He bought nothing."),
        defendant: [.direct("Where did you get the twenties?", "\"As change from somewhere, I think. I didn't look at them closely. I didn't know they were counterfeit.\""), .direct("Did you try to pass bad bills?", "\"No. I'd never do that on purpose. I handed over what I had, and I didn't know they were fake.\""), .direct("What can you tell us about your day at the market?", "\"I was browsing, buying a few small things. I paid with twenties I'd gotten from a gas station and a restaurant.\""), .direct("What did you think when the first vendor marked a bill?", "\"I was shocked. I didn't know the bills were counterfeit, and I offered to pay with a card.\""), .direct("What did you do when security stopped you?", "\"I cooperated, emptied my wallet, and told them where I thought the bills came from. I wasn't hiding anything.\""), .direct("What did you do with the five other twenties in your wallet?", "\"I kept them as change and meant to spend them later. After the pen marked the first one, I realized they were all from the same source.\""), .cross("You passed three bills at three stalls, didn't you?", "\"Yes. I bought small things at different stalls. I used what I had. I didn't think about it.\""), .cross("All three marked black on the pen, didn't they?", "\"That's what the vendors say. I didn't know. I can't tell a fake just by looking.\""), .cross("You can't say where you got them, can you?", "\"No. I took change from several places. I know that's vague, but that's how cash works.\""), .cross("Three counterfeit bills at three stalls in half an hour. Isn't that a pattern?", "\"It looks that way, but I got the bills in the same batch. I passed them without knowing.\""), .cross("You had more in your wallet. Why keep them if you thought they were fake?", "\"I didn't know. I had no idea until the vendor's pen turned black.\"")],
        openings: ("{D} passed three counterfeit twenties at three flea market stalls between 10 and 10:30 in the morning. Each bill marked black under a vendor's pen, and security stopped {D} at 11. The State will show the bills and the pen test.", "The defense evidence includes a shopper who received the bills as change, spent them without knowing, and cooperated when stopped. Passing a fake bill is not the same as knowing it is fake."),
        closings: ("Three counterfeit bills at three stalls in half an hour, each marked black. A person who passes three in a row can't claim to be unlucky.", "Cash passes through many hands. {D} used the bills like any shopper and cooperated fully. The State has not proved {D} knew they were counterfeit."),
        timeline: [(0, "10 a.m.: the first stall."), (0, "10:30 a.m.: the third stall."), (0, "11 a.m.: security stops {DL}.")],
        identified: "Bills",
        mood: .indifferent,
        genders: ["D": .male])

    static let badCheckTires = SmallCases.make(
        key: "story.badCheckTires",
        category: .whiteCollar,
        headlines: ["Man Writes Worthless Check for Four Tires"],
        law: "uttering",
        spec: "Offered a worthless check for $640 to {V}, a tire shop, knowing the account was closed, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} paid for four tires with a $640 check on {DATE} from a closed account. The account had closed thirty-five days earlier. The check came back five days after the sale, and the shop owner could not reach {D}.",
        state: [E(.document, 3, "Returned Check", "Returned: account closed."), E(.document, 2, "Bank Notice", "The account closed thirty-five days before the sale.")],
        defense: [E(.statement, 1, "Mistaken", "{DL} thought the account was open.")],
        role: "Tire shop owner",
        exam: [.direct("Tell the jury about your tire shop and the sale.", "\"I own a tire shop and install tires while customers wait. {D} bought four tires for $640 and paid with a check.\""), .direct("What did {DL} buy from you on {DATE}?", "\"Four tires, for $640. {D} paid with a check, and I put the tires on that day.\""), .direct("What happened to the check?", "\"It came back five days later marked account closed. The bank notice shows the account had closed thirty-five days before the sale.\""), .direct("What did you do then?", "\"I tried to reach {D}. I called and left messages, and I never got an answer. I couldn't reach {D} at all.\""), .direct("How do you check a check before accepting it?", "\"I ask for ID and compare the name. I don't call the bank for every check, and this one looked normal.\""), .direct("What happened five days later?", "\"The bank returned it marked 'account closed.' I called {D} and left messages, but nobody picked up.\""), .cross("{DL} says {D.he} thought the account was open, doesn't {D.he}?", "\"I can't see inside anyone's head. I know the account was closed over a month earlier.\""), .cross("Did {DL} seem to be hiding anything?", "\"No. {D} was friendly and polite at the counter. Nothing seemed off until the check came back.\""), .cross("Did {DL} ever pay you afterward?", "\"I don't believe I'd been paid at the time I made my report. I may have been told something later.\""), .cross("Did {D} say anything about the account when you took the check?", "\"No. {D} handed it over and said it was fine.\""), .cross("Did you try to recover the tires?", "\"I sent a letter and called. {D} never answered, and the tires were already on {D.his} car.\"")],
        theory: ("{D} wrote a worthless check.", "A mistaken balance."),
        allocution: "\"I'm sorry.\"",
        truths: ("The account closed a month earlier.", "A letter said so."),
        defendant: [.direct("Did you know the account was closed?", "\"No. I thought it was open. I had been using it for a while and nothing told me it was closed.\""), .direct("Why did you pay by check?", "\"I didn't have cash on me. I'd used the account before, so I thought it was safe. I never meant to cheat the shop.\""), .direct("Why didn't you answer the owner's calls?", "\"I was embarrassed and didn't know how to fix it. I let the calls go to voicemail, and that was wrong.\""), .direct("What can you tell us about the check?", "\"I wrote it from an account I'd had for years. I thought it was still open and that I had enough money.\""), .direct("How did you find out the account was closed?", "\"When the tire shop called. I looked at my mail and found a letter from the bank dated a month earlier.\""), .direct("Why didn't you respond to the calls?", "\"I was ashamed and I didn't have the money to cover it. I should have called back.\""), .cross("The bank closed the account thirty-five days before, didn't it?", "\"That's what the notice says. I don't recall getting anything about it. I should have checked.\""), .cross("You didn't call the shop back, did you?", "\"No. I own that. I didn't have the money, and I was afraid.\""), .cross("$640 is a lot to put on a check you didn't verify, isn't it?", "\"It is. I should have checked the balance. I assumed the account was fine.\""), .cross("The bank sent a letter thirty-five days before the sale. Didn't you read it?", "\"It was in a pile and I didn't open it. I know I should have.\""), .cross("You drove away on new tires you hadn't paid for. Isn't that a theft?", "\"I thought I'd paid. When I learned I hadn't, I felt awful and tried to figure out how to make it right.\"")],
        openings: ("{D} paid $640 for four tires with a check, and it came back five days later marked account closed. The account had closed thirty-five days before the sale. The State will show the check and the bank notice.", "The defense will point you to a customer who believed the account was open and who was embarrassed rather than devious. A bad check is not always a fraud."),
        closings: ("A $640 check for four tires, on an account closed a month earlier. The tires are on {D}'s car and the shop is out the money.", "{D} thought the account was open. The State must prove {D} knew it was closed, and a missed notice is not proof."),
        timeline: [(-35, "The account closes."), (0, "{D} buys tires."), (5, "The check is returned.")],
        identified: "Returned Check",
        mood: .indifferent,
        genders: ["D": .male])

