        state: [E(.document, 3, "Checks", "Three checks with a forged signature."), E(.document, 2, "Check Images", "Three checks totaling $480.")],
        defense: [E(.statement, 1, "Found", "{DL} says {D.he} found the checkbook.")],
        role: "Bank teller",
        exam: [.direct("Tell us about your bank and how checks are processed.", "\"I work at a teller window. We check ID, compare the signature on the check, and look at the check's date and amount.\""), .direct("What was wrong with the checks?", "\"The signature was not right. Three checks were presented, and each carried a forged signature.\""), .direct("Who cashed them?", "\"{D}. The first check was cashed the day after it was found, and the bank flagged all three two days later.\""), .direct("How much did the checks total?", "\"$480. The check images show the three checks and the amounts.\""), .direct("What was wrong with the checks that {D} presented?", "\"The signature didn't look right. The strokes were hesitant and the letters were smaller than the signature on file.\""), .direct("How many checks did {D} cash?", "\"Three. The first was cashed the day after the account holder reported the checkbook missing, and the other two over the next two days.\""), .cross("{D} told you a checkbook was found in a rental car, didn't {D.he}?", "\"Yes, that is what {D} said. I cannot confirm where the checkbook came from.\""), .cross("Did {D} use {D.his} own ID?", "\"Yes, {D} used a real ID. I would note that.\""), .cross("The name on the checks was not {D}'s, was it?", "\"No. The name on the checks was someone else's. {D} signed it in a new hand.\""), .cross("Did {D} try to hide who {D.he} was?", "\"No. {D} showed an ID in a different name from the one on the checks.\""), .cross("Did you flag the checks at the time?", "\"Not at the window. The bank's fraud team flagged them two days later.\"")],
