        exam: [.direct("What can you tell us about your trip and your cat?", "\"I went out of town for a long weekend. I have an elderly cat that needs feeding twice a day and medication.\""), .direct("What happened with the visits?", "\"No visit came on Saturday. There were no messages from {D} after I paid. I returned from the trip on Monday.\""), .direct("What does the payment record show?", "\"$240 paid to {D} for three visits. The messages show nothing after the deposit. I'd hoped for updates.\""), .direct("What did you arrange with {D}?", "\"Three visits, on Saturday, Sunday, and Monday morning. I paid $240 by app on Friday, as {D} asked.\""), .direct("What did you find when you got home?", "\"The cat was hungry and weak, with an empty bowl and no sign anyone had come. The cat spent a night at the vet.\""), .direct("How did you find the cat when you got home on Monday?", "\"Hungry and restless, with the bowl empty and the litter box full. I called the vet and checked for dehydration, and the cat was fine.\""), .cross("{DL} says {D.he} fell ill, doesn't {D.he}?", "\"If so, I'd have expected a message. I never heard from {D}, and I wasn't given a chance to find someone else.\""), .cross("Did you try to reach {DL}?", "\"Yes, I sent messages after Saturday. There was no answer. I didn't know what was happening at home.\""), .cross("Did {DL} refund any of the $240?", "\"Not that I recall. I may not have asked right away. I was focused on getting home.\""), .cross("Did {D} give any reason before you left?", "\"No. {D} said everything was fine and told me to enjoy the trip.\""), .cross("Did you try to reach {D} while you were away?", "\"Twice by text and once by phone. There was no answer.\"")],
        theory: ("{D} took deposits and skipped.", "Illness."),
        allocution: "\"I'm sorry.\"",
        truths: ("No messages were sent.", "The cat went hungry."),
        defendant: [.direct("Why didn't you show up for the pet-sitting?", "\"I got sick on Friday night. I was in bed and couldn't get up. I should have told {V}, and I didn't.\""), .direct("Why didn't you send messages?", "\"I was too ill and I wasn't thinking. I meant to send something, and it slipped away. I feel terrible about it.\""), .direct("Did you mean to keep {V}'s money?", "\"No. I meant to do the visits. I was sick. I'll refund the money if I haven't.\""), .direct("Please describe your pet-sitting work.", "\"I do it a few times a month for neighbors. I take payment in advance and I plan my visits around my day job.\""), .direct("What happened on the weekend of the trip?", "\"I came down with a high fever on Friday night. I was in bed for two days and could barely stand.\""), .direct("Why didn't you tell {V} or find a replacement?", "\"I was too sick to think. I meant to, and I didn't have a friend I could call.\""), .cross("You took $240 and never went, didn't you?", "\"I got sick. That's the truth. I know I should have told someone or found a substitute.\""), .cross("You didn't send one message, did you?", "\"No. I was too sick and I didn't think. I should have asked someone to tell {V}.\""), .cross("Nobody can confirm you were ill, can they?", "\"No. I was home alone. I don't have a doctor's note, and I know that makes it hard to believe.\""), .cross("You took $240 and never went. Isn't that taking money for nothing?", "\"I see it that way now. I meant to go, and I should have given the money back.\""), .cross("The cat went hungry for two days. Do you feel responsible?", "\"Yes. I should have found someone else, and I'm very sorry.\"")],
        openings: ("{D} took $240 from a neighbor for three pet-sitting visits, never showed up, and sent no messages. {V} came home on Monday. The State will show the payment record and the silence.", "The defense will point you to a sitter who fell ill, failed to notify {V}, and did not mean to keep the money. Being unreliable isn't the same as being a thief."),
        closings: ("Two hundred forty dollars paid on Friday, no visit on Saturday, and no word from {D}. {V} left home trusting {D}, and {D} took the money and vanished.", "A sudden illness and a failure to call is poor judgment, not fraud. The State has not proved {D} planned from the start not to show up."),
        timeline: [(0, "Friday: the deposit."), (0, "Saturday: no visit."), (0, "Monday: the owner returns.")],
        identified: "Payment App Record",
        mood: .indifferent,
        genders: ["D": .female])

    static let christmasLights = SmallCases.make(
        key: "story.christmasLights",
        category: .property,
        headlines: ["Man Takes Neighbor's Rooftop Christmas Lights"],
        law: "misdLarceny",
        spec: "Took property of {V}, valued at $190, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} unplugged and took $190 in roof lights from a neighbor's house on {DATE}. The lights were on in the evening and came down at 11 p.m. The neighbor's doorbell camera recorded {D} pulling them off the eave.",
        state: [E(.video, 3, "Doorbell Camera", "{D} pulls the lights off the eave."), E(.document, 2, "Purchase Receipt", "$190 for the roof lights.")],
        defense: [E(.statement, 1, "Thought Trash", "{DL} says they looked abandoned.")],
        role: "Neighbor",
        exam: [.direct("Tell us about your lights and your home.", "\"I put up string lights along the roof edge every December. They cost $190 and I plug them in each evening.\""), .direct("What happened to your roof lights on {DATE}?", "\"They were on in the evening, and at about 11 p.m. {D} took them down. I paid $190 for them and I have the receipt.\""), .direct("What does your doorbell camera show?", "\"{D} pulling the lights off the eave. You can see the reach up, the lights coming down, and {D} walking away with them.\""), .direct("What did you see on your doorbell camera?", "\"At about eleven, {D} walks up the driveway with a stepladder and starts pulling the lights off the eave. The lights were still lit.\""), .direct("How did you know {D}?", "\"{D} lives two houses down. I recognized {D} on the video and went to the sheriff's office the next day.\""), .direct("How did the lights look before and after {D} took them down?", "\"They were lit and plugged in until 11 p.m. Afterward I found cords on the lawn and a bare eave, and the roof looked stripped.\""), .cross("{DL} says the lights looked abandoned, doesn't {D.he}?", "\"They were on my roof, and I'd put them up for the holidays. They weren't abandoned.\""), .cross("Did you speak to {DL} that night?", "\"No. I saw it only on the camera afterward. I wasn't aware of it happening at the time.\""), .cross("Were the lights damaged?", "\"Some of the strand was damaged where they were pulled down. I have the receipt for the full set.\""), .cross("Were the lights plugged in when {D} took them?", "\"Yes. They were on, which I think should have told {D} they weren't abandoned.\""), .cross("Did you speak to {D} before going to the sheriff?", "\"No. I didn't have a chance. I only knew from the video.\"")],
        theory: ("{D} took lights.", "A mistake."),
        allocution: "\"I'm sorry.\"",
        truths: ("They were still plugged in.", "It was January."),
        defendant: [.direct("Why did you take down the lights?", "\"I thought they were abandoned. They looked old and I thought the owner had left them hanging. I didn't think about it much.\""), .direct("Did you know they belonged to {V}?", "\"I knew {V} lived there, but I thought the lights had been forgotten. I didn't think they were wanted.\""), .direct("What did you do with them?", "\"I took them home. I didn't try to sell them or hide them. I'd have returned them if anyone had asked.\""), .direct("What can you tell us about the walk home?", "\"I was walking my dog at about eleven. The lights on the roof were strung loosely and looked worn.\""), .direct("Why did you think they were abandoned?", "\"They were hanging down in places and it was January. I thought they'd been left up from the holidays and forgotten.\""), .direct("What did you do with the lights after you took them down?", "\"I coiled them and carried them home. I meant to use them for my own porch, and I should have asked who owned them.\""), .cross("They were on {V}'s roof, weren't they?", "\"Yes. I know now that was a mistake. I should have asked first.\""), .cross("You took them at 11 at night, didn't you?", "\"Yes. I was out late and noticed them. It was a bad idea to do it that late and without asking.\""), .cross("The lights cost $190, didn't they?", "\"I didn't know. I'm willing to pay for them. I shouldn't have taken them without asking.\""), .cross("The lights were lit and on {V}'s roof. How could they be abandoned?", "\"I should have noticed. I wasn't thinking clearly.\""), .cross("You needed a ladder to get them. Isn't that a lot of effort for trash?", "\"I had it in my truck. I thought it would be a quick pickup.\"")],
        openings: ("At 11 p.m. the doorbell camera caught {D} pulling a string of $190 roof lights off a neighbor's eave. The State will show the video and the receipt, and {V} will say the lights were not abandoned.", "The defense will present a neighbor who thought the lights were old and forgotten, took them in the open, and never tried to hide them."),
        closings: ("A string of lights on {V}'s own roof, a camera showing {D} pulling them down at 11 at night, and $190 gone. Nothing about that was abandoned.", "{D} acted in the open, on a camera, with no effort to hide anything. The State has not proved {D} knew the lights belonged to someone who wanted them."),
        timeline: [(0, "Evening: the lights are on."), (0, "11 p.m.: they come down.")],
        identified: "Doorbell Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let fakeCharityDoor = SmallCases.make(
        key: "story.fakeCharityDoor",
        category: .property,
        headlines: ["Door Knocker Collects Cash for a Charity That Does Not Exist"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $60, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} collected $60 at a doorstep on {DATE} for a children's fund that did not exist. The knock came at noon, and {V} reported it at 1 p.m. The flyer {D} left shows no registration number for the fund.",
        state: [E(.document, 3, "Flyer", "The flyer lists a fund with no registration."), E(.document, 2, "Receipt Slip", "A handwritten slip for $60 signed by {D}.")],
        defense: [E(.statement, 1, "Real Cause", "{DL} says {D.he} meant to donate it.")],
        role: "Homeowner",
        exam: [.direct("Walk us through what happened at your door at noon.", "\"Someone knocked and said they were collecting for a children's fund that helps local families. I was home from work, and they seemed polite and well dressed.\""), .direct("What happened at your door at noon on {DATE}?", "\"{D} knocked and asked for a donation for a children's fund. I gave $60 and was handed a handwritten slip signed by {D}.\""), .direct("What do the flyer and the slip show?", "\"The flyer lists the fund with no registration. The slip is for $60 and bears {D}'s signature.\""), .direct("What did you do?", "\"I gave $60 in cash because the person said every little bit helps. {D} wrote a handwritten slip, signed it, and handed me a flyer.\""), .direct("Why did you report it?", "\"After {D} left, I looked at the flyer and saw no registration number for the fund. I searched online and found no charity by that name.\""), .direct("What did the person at your door say about the fund?", "\"That it helped sick children and that every dollar counted. I asked for a number, and the person wrote a slip instead.\""), .cross("Did {DL} say anything false to you?", "\"{D} said the money was for a children's fund. I took that at face value. I can't say what happened to the money later.\""), .cross("Did {DL} pressure you?", "\"No. {D} was polite. I chose to give the money. It was a quick conversation on the porch.\""), .cross("Did you check the fund before giving?", "\"No. I own that. I saw children mentioned and I trusted it, and I didn't ask for the registry.\""), .cross("Did {D} say the fund was registered with the state?", "\"Not in so many words. {D} said it was a local fund, and I took that to mean it was legitimate.\""), .cross("Did you see {D} go to other houses?", "\"I saw {D} walking toward a neighbor's door as I closed mine.\"")],
        theory: ("{D} collected for a fake fund.", "A real cause."),
        allocution: "\"I'm sorry.\"",
        truths: ("No registry shows the fund.", "{DL} kept the cash."),
        defendant: [.direct("What were you doing at {V}'s door?", "\"I was asking for donations to a children's fund. I really thought it was a real cause, and I told {V} about it.\""), .direct("What did you plan to do with the $60?", "\"I meant to donate it. I intended to pass it along to the fund. I didn't mean to keep it for myself.\""), .direct("Why does the flyer have no registration number?", "\"I didn't know it needed one. I handed out what I was given. I didn't check the paperwork.\""), .direct("Tell the jury about the fund you were collecting for.", "\"A group of volunteers was raising money for children's winter coats and school supplies. I'd been asked to help by a friend of a friend.\""), .direct("What did you do with the $60?", "\"I put it in an envelope with the other donations. I planned to give it to the volunteer leader at the weekend meeting.\""), .direct("What did you say to {V} to get the $60?", "\"I said I was collecting for a children's fund and handed over a flyer. I took the money and wrote a slip, and I should have checked the fund first.\""), .cross("You signed the receipt slip yourself, didn't you?", "\"Yes. I wrote it out. I wanted {V} to have a record. I wasn't hiding anything.\""), .cross("No registered fund exists, does it?", "\"That's what the officers say. I believed it did. If I was fooled, I apologize.\""), .cross("You can't show where the $60 went, can you?", "\"Not with paper. I meant to give it to the fund. I know I should have kept better records.\""), .cross("You can't name the group's leader. Why not?", "\"I know a first name and a phone number, but the number has been disconnected.\""), .cross("No fund by that name is registered anywhere. Isn't that a red flag?", "\"It is now. I didn't know to check, and I trusted the people who asked me.\"")],
        openings: ("At noon, {D} knocked on {V}'s door, collected $60 for a children's fund, and handed over a signed slip. The fund was not registered anywhere. The State will show the flyer and the slip.", "Jurors will also see a collector who believed in the cause, wrote a receipt with {D.his} own signature, and never hid who {D.he} was."),
        closings: ("A flyer with no registration, a slip signed by {D}, and $60 for a fund that does not exist. {V} gave in good faith and was deceived.", "{D} used a real signature, a real flyer, and acted in the open. The State has not proved {D} knew the fund was not real."),
        timeline: [(0, "Noon: the knock."), (0, "1 p.m.: the report.")],
        identified: "Flyer",
        mood: .indifferent)

    static let bridgeRailTag = SmallCases.make(
        key: "story.bridgeRailTag",
        category: .property,
        headlines: ["Teen Sprays Tag on County Bridge Rail"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a county, with graffiti, causing damage of $350, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} sprayed a tag on a county bridge rail on {DATE}. The rail was clean at dusk. The road supervisor found the tag the next morning, and cleaning it cost $350.",
        state: [E(.physical, 3, "Spray Can", "A can with paint matching the tag."), E(.document, 2, "Cleanup Invoice", "$350 to remove the tag.")],
        defense: [E(.statement, 1, "Not Mine", "{DL} says the can was found.")],
        role: "Road supervisor",
        exam: [.direct("Tell the jury about the bridge and how it's maintained.", "\"It's a county bridge on a rural road with a steel guardrail. We inspect it quarterly, and at dusk the rail was clean.\""), .direct("What did you find on {DATE}?", "\"The county bridge rail had been tagged with spray paint. It was clean at dusk the day before, and I found the tag the next morning.\""), .direct("What did it cost to clean?", "\"$350 to remove the tag. The invoice is in evidence, and a crew had to close a lane while they worked.\""), .direct("What was recovered that connects to {DL}?", "\"A spray can with paint matching the tag. Deputies took it from {D}.\""), .direct("What did you find the next morning?", "\"A large tag in black spray paint across about eight feet of the rail. It was still tacky when I touched it.\""), .direct("What did cleanup involve?", "\"A crew sandblasted the paint and repainted the rail. The invoice was $350, plus a closed lane for part of the day.\""), .cross("Did anyone see {DL} spray the bridge?", "\"Not that I know of. I found the tag in the morning, and I can't say who did it.\""), .cross("{DL} says the can was found, doesn't {D.he}?", "\"I can't say where {D} got it. I only know the paint matches what was on the rail.\""), .cross("How many cans of that paint exist?", "\"It's a common brand and color. Lots of people could have a can that matches.\""), .cross("Did anyone see {D} near the bridge?", "\"No. We have no witness who saw {D} there, and no camera at the bridge.\""), .cross("Is the paint color a common one?", "\"Yes. It's a standard black sold in hardware stores everywhere.\"")],
        theory: ("{D} tagged the rail.", "A found can."),
        allocution: "\"I'm sorry.\"",
        truths: ("The can was in {DL}'s bag.", "The paint was wet."),
        defendant: [.direct("Did you spray the bridge rail?", "\"No. I've never done that. I'd never put graffiti on a county bridge, and I didn't touch that rail.\""), .direct("Why did you have a spray can?", "\"I found it. It was lying near the road, and I picked it up. I thought I might use it for a project.\""), .direct("How do you explain the paint matching?", "\"I can't. It's a common color. I didn't know the can was connected to anything until the deputies asked me about it.\""), .direct("Tell us about the spray can.", "\"I found it lying near the road while I was walking. It was about half full, and I picked it up and put it in my bag.\""), .direct("Why did you keep it?", "\"I thought I might use it for a project. I didn't think about where it came from.\""), .direct("Where were you the night the bridge was tagged?", "\"At home. I had no reason to be near the bridge, and I've never painted anything on public property.\""), .cross("The paint on your can matches the tag, doesn't it?", "\"That's what they say. I don't know why. I didn't use the can on a bridge.\""), .cross("You can't say who left the can, can you?", "\"No. It was just there. I know that sounds convenient, but it's what happened.\""), .cross("You had the can with you when stopped, didn't you?", "\"Yes. I carried it with me. I'd picked it up a short time before and hadn't thought about it.\""), .cross("The paint matches the tag. How is that a coincidence?", "\"It's a common color. Lots of people have cans like it.\""), .cross("The paint on the rail was wet. Was the can wet too?", "\"I don't know. I didn't check it when I found it.\"")],
        openings: ("The bridge rail was clean at dusk and tagged by morning, and cleanup cost $350. A spray can with matching paint was taken from {D}. The State will show the can and the invoice.", "The defense evidence includes a can picked up off the ground, a common paint color, and no one who saw {D} spray anything."),
        closings: ("A clean rail at dusk, a tag by morning, and a can of matching paint taken from {D}. The simplest explanation is the one the evidence points to.", "A matching color is not a match to a person. Nobody saw {D} paint, and the can was found. The State has not proved {D} sprayed that rail."),
        timeline: [(0, "Dusk: the rail is clean."), (0, "Next morning: the tag.")],
        identified: "Spray Can",
        mood: .indifferent)

