        state: [E(.video, 3, "Rail Yard Camera", "{D} paints a car."), E(.document, 2, "Cleanup Estimate", "$420 to remove the paint.")],
        defense: [E(.statement, 1, "Art", "{DL} says it was art.")],
        role: "Rail agent",
        exam: [.direct("Describe your job and the rail yard for the jury.", "\"I'm a rail agent. The yard holds parked freight cars waiting to be assigned, and it's surrounded by a chain-link fence with signs.\""), .direct("What did you find in the rail yard?", "\"Paint on a parked freight car. It sat in a fenced yard, and the camera shows {D} painting it at 2 a.m.\""), .direct("What did {D} paint?", "\"Initials on the side of the car. They were large and easy to read.\""), .direct("What did the cleanup cost?", "\"$420 to remove the paint. We got an estimate from a cleaning crew.\""), .direct("What did the yard camera show?", "\"At about two in the morning, {D} climbs the fence, walks to a parked car, and paints initials on its side with a can. It takes about ten minutes.\""), .direct("What did the cleanup involve?", "\"A crew removed the paint with solvent and repainted a section of the car. The estimate was $420.\""), .cross("Was the car in use?", "\"No. It was parked in the yard. It was not moving, and it was not loaded that night.\""), .cross("Was the yard fenced?", "\"Yes. {D} had to get in through the fence or an opening.\""), .cross("Did {D} come back more than once?", "\"The camera shows {D} twice. I do not know of any other visits.\""), .cross("Was the car in service or carrying cargo?", "\"It was empty and parked on a siding. It wasn't going anywhere that night.\""), .cross("Did {D} damage anything besides the paint?", "\"No. The fence wasn't cut and nothing else was touched.\"")],
        theory: ("{D} painted a car.", "Art."),
        allocution: "\"I'm sorry.\"",
        truths: ("The yard was fenced.", "{DL} came back twice."),
        defendant: [.direct("Did you paint the freight car?", "\"Yes, I did. I painted my initials on it. It was something I wanted to do as art.\""), .direct("Why did you do it?", "\"I think of it as art. I did not mean to damage anything of value.\""), .direct("Was the car in use?", "\"No. It was parked. I did not touch any cars that were in operation.\""), .direct("Walk us through what you were doing in the yard.", "\"I wanted to paint something on a freight car. I think of it as a form of art, and I'd seen other pieces on trains.\""), .direct("How did you get into the yard?", "\"I climbed the fence. I knew it was wrong and I did it anyway.\""), .direct("Did you come back?", "\"Twice, before that night, to look at the cars. I didn't paint anything until the night the camera caught me.\""), .cross("You climbed into a fenced rail yard at 2 a.m., didn't you?", "\"Yes. I know I should not have. It was foolish.\""), .cross("You came back twice, didn't you?", "\"Yes. I wanted to finish the piece.\""), .cross("$420 to clean it. Will you pay?", "\"I would like to. I did not think about the cost.\""), .cross("You climbed a fenced rail yard at 2 a.m. Wasn't that dangerous?", "\"It was, and I wasn't thinking about it. I could have been hurt.\""), .cross("You call it art. Isn't it also damage?", "\"It was damage. I wasn't trying to hurt the railroad, but I understand it cost them money.\"")],
        openings: ("At 2 a.m., a rail yard camera shows {D} painting initials on a parked freight car inside a fenced yard. The cleanup cost $420.", "Weigh the defense proof, which will show that the car was parked, no one was hurt, and {D} sees this as art. {D} regrets the damage."),
