        mood: .indifferent,
        genders: ["D": .male])

    static let carHoodDent = SmallCases.make(
        key: "story.carHoodDent",
        category: .property,
        headlines: ["Man Dents Car Hood During Parking Dispute"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, causing damage of $900, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} jumped on a car hood on {DATE} in a parking dispute. The dispute began at 5 p.m., the stomp came a minute later, and the garage camera recorded it. The dent cost $900 to repair.",
        state: [E(.video, 3, "Garage Camera", "{D} stomps the hood."), E(.document, 2, "Repair Estimate", "$900 to repair the hood.")],
        defense: [E(.statement, 1, "Provoked", "{DL} says the driver nearly hit {D.him}.")],
        role: "Car owner",
        exam: [.direct("What can you tell us about your car and the garage?", "\"I parked in a public garage near my office. I was pulling out at about five when someone walked in front of the car.\""), .direct("What happened in the parking garage on {DATE}?", "\"We got into a parking dispute at about 5 p.m. A minute later, {D} jumped on the hood of my car.\""), .direct("What does the garage camera show?", "\"{D} stomping the hood. You can see the dispute and then {D} climbing up and stomping.\""), .direct("What did the damage cost?", "\"$900 to repair the hood. The repair estimate is in evidence. The dent was deep.\""), .direct("What happened next?", "\"I stopped and honked. The person shouted, then stepped up and jumped on my hood with both feet.\""), .direct("What damage did the car have?", "\"A large dent in the hood, about a foot across, and scratches on the paint. The repair estimate was $900.\""), .cross("{DL} says you nearly hit {D.him}, doesn't {D.he}?", "\"I was pulling into a space, moving slowly. I never intended to hit anyone.\""), .cross("Were you moving when {DL} stepped on the car?", "\"I was close to a stop. I can't swear to the exact speed. The garage was tight.\""), .cross("Did you honk or shout at {DL}?", "\"I may have honked. I think I said something. It was a heated moment, and I don't remember each word.\""), .cross("Did your car nearly hit {D}?", "\"I was moving slowly and I stopped before I reached {D.him}. I don't think I came close.\""), .cross("Did you say anything to {D} before the stomp?", "\"I rolled down my window and said to watch where {D.he} was going. I wasn't yelling.\"")],
        theory: ("{D} dented a hood.", "Provoked."),
        allocution: "\"I'm sorry.\"",
        truths: ("The car had stopped.", "{DL} kept stomping."),
        defendant: [.direct("Why did you jump on the car?", "\"The car nearly hit me. I was frightened and angry, and I reacted. I stomped the hood without thinking.\""), .direct("How close did the car come?", "\"Very close. It came right at me as I stepped out. I jumped back, and then I hit the hood in anger.\""), .direct("Did you mean to damage the car?", "\"No. I wanted the driver to stop. I'm sorry about the dent. I never meant to do that much damage.\""), .direct("Walk us through what happened in the garage.", "\"I was walking to my own car when a vehicle came out of a space fast and nearly hit me. I jumped back and then I was angry.\""), .direct("Why did you jump on the hood?", "\"I was frightened and furious. I wanted the driver to stop and understand how close it was.\""), .direct("What did you do afterward?", "\"I stood there, shaking. I told the driver I was sorry and offered to pay for the dent.\""), .cross("The camera shows you stomping the hood, doesn't it?", "\"Yes, I did. I'm not denying it. I let my temper go.\""), .cross("The repair was $900, wasn't it?", "\"That's what I'm told. I'll pay what's fair. I just wish I'd walked away.\""), .cross("You climbed on someone's car, didn't you?", "\"Yes. It was a bad decision. I was angry and afraid at the same time.\""), .cross("The car had already stopped. Why keep stomping?", "\"I wasn't thinking. I kept going until I realized what I was doing.\""), .cross("A dent for a near miss. Isn't that overreacting?", "\"Yes. I should have walked away.\"")],
